        new Def { Id = "BuldakCup", Kind = Kind.Noodle, RuM = "Оригинальная, но в стакане: бежать с ним к воде удобнее.", EnM = "The original, but in a cup: easier to carry while you run for water.", Mesh = "bigcup", Texture = "BuldakCup", Kg = 0.096f, Water = 0.5f, Shape = "bigcup", Brand = "Buldak", Kcal = 440f, Ru = "Лапша «Больдак» в большом стакане", En = "Burndak Original big cup", RuF = "оригинальная, но в стакане: бежать с ним к воде удобнее", EnF = "the original, but in a cup: easier to carry while you run for water", Spicy = 3, Dry = true, Fx = "appetite heartburn", Broth = "#9e1b10" },
        new Def { Id = "BuldakCupHot", Kind = Kind.Brewed, RuM = "Стакан горячий снаружи и ещё горячее внутри. Держите крепче: ронять такое на деревянный пол жалко и опасно.", EnM = "The cup is hot outside and hotter inside. Hold it tight: dropping this on a wooden floor is both a pity and a hazard.", Raw = "BuldakCup", Mesh = "bigcupHot", Texture = "BuldakCup", Kg = 0.221f, Thirst = -12f, Warm = 1.65f, Shape = "bigcup", Brand = "Buldak", Kcal = 440f, Ru = "Лапша «Больдак» в большом стакане", En = "Burndak Original big cup", RuF = "оригинальная, но в стакане: бежать с ним к воде удобнее", EnF = "the original, but in a cup: easier to carry while you run for water", Spicy = 3, Dry = true, Fx = "appetite heartburn", Broth = "#9e1b10" },
        new Def { Id = "Buldak2xCup", Kind = Kind.Noodle, RuM = "Вдвое острее, в стакане. Стакан одноразовый, воспоминания навсегда.", EnM = "Twice as hot, in a cup. The cup is disposable, the memories are forever.", Mesh = "bigcup", Texture = "Buldak2xCup", Kg = 0.1f, Water = 0.5f, Shape = "bigcup", Brand = "Buldak", Kcal = 500f, Ru = "Лапша «Больдак 2× Острый» в большом стакане", En = "Burndak 2x Spicy big cup", RuF = "вдвое острее, в стакане. Стакан одноразовый, воспоминания навсегда", EnF = "twice as hot, in a cup. The cup is disposable, the memories are forever", Spicy = 4, Dry = true, Fx = "heartburn tears", Broth = "#7f0d08" },
        new Def { Id = "Buldak2xCupHot", Kind = Kind.Brewed, RuM = "Двойная острота, пар столбом. Если заблудитесь в метель, вас найдут по этому запаху. Вопрос, кто именно.", EnM = "Double heat, steam rising in a column. If you get lost in a blizzard they will find you by this smell. The question is who.", Raw = "Buldak2xCup", Mesh = "bigcupHot", Texture = "Buldak2xCup", Kg = 0.225f, Thirst = -14f, Warm = 1.95f, Shape = "bigcup", Brand = "Buldak", Kcal = 500f, Ru = "Лапша «Больдак 2× Острый» в большом стакане", En = "Burndak 2x Spicy big cup", RuF = "вдвое острее, в стакане. Стакан одноразовый, воспоминания навсегда", EnF = "twice as hot, in a cup. The cup is disposable, the memories are forever", Spicy = 4, Dry = true, Fx = "heartburn tears", Broth = "#7f0d08" },
        new Def { Id = "BuldakCarboCup", Kind = Kind.Noodle, RuM = "Розовый стакан боли. В мороз греет лучше костра, проверять на свой страх и риск.", EnM = "A pink cup of pain. Warms better than a campfire in the frost, try at your own risk.", Mesh = "bigcup", Texture = "BuldakCarboCup", Kg = 0.102f, Water = 0.5f, Shape = "bigcup", Brand = "Buldak", Kcal = 470f, Ru = "Лапша «Больдак Карбонара» в большом стакане", En = "Burndak Carbonara big cup", RuF = "розовый стакан боли. В мороз греет лучше костра, проверять на свой страх и риск", EnF = "a pink cup of pain. Warms better than a campfire in the frost, try at your own risk", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#e8b98a" },
        new Def { Id = "BuldakCarboCupHot", Kind = Kind.Brewed, RuM = "Розовое, горячее и опасное. Примерно как рассвет на Волчьей горе, только рассвет не надо запивать литром воды.", EnM = "Pink, hot and dangerous. Much like dawn on Timberwolf Mountain, except you do not chase a dawn with a litre of water.", Raw = "BuldakCarboCup", Mesh = "bigcupHot", Texture = "BuldakCarboCup", Kg = 0.227f, Thirst = -10f, Warm = 1.35f, Shape = "bigcup", Brand = "Buldak", Kcal = 470f, Ru = "Лапша «Больдак Карбонара» в большом стакане", En = "Burndak Carbonara big cup", RuF = "розовый стакан боли. В мороз греет лучше костра, проверять на свой страх и риск", EnF = "a pink cup of pain. Warms better than a campfire in the frost, try at your own risk", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#e8b98a" },
        new Def { Id = "BuldakCheeseBowl", Kind = Kind.Noodle, RuM = "Большая миска на двоих. Вторым обычно оказывается сожаление.", EnM = "A big bowl for two. The second one is usually regret.", Mesh = "kbowl", Texture = "BuldakCheeseBowl", Kg = 0.107f, Water = 0.5f, Shape = "kbowl", Brand = "Buldak", Kcal = 480f, Ru = "Лапша «Больдак Сырный» в большой миске", En = "Burndak Cheese big bowl", RuF = "большая миска на двоих. Вторым обычно оказывается сожаление", EnF = "a big bowl for two. The second one is usually regret", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#e09a2a" },
        new Def { Id = "BuldakCheeseBowlHot", Kind = Kind.Brewed, RuM = "Миска размером с таз, сыр тянется до соседнего региона. Доедать в одиночку считается подвигом.", EnM = "A bowl the size of a basin, the cheese stretches to the next region. Finishing it alone counts as a feat.", Raw = "BuldakCheeseBowl", Mesh = "kbowlHot", Texture = "BuldakCheeseBowl", Kg = 0.232f, Thirst = -10f, Warm = 1.35f, Shape = "kbowl", Brand = "Buldak", Kcal = 480f, Ru = "Лапша «Больдак Сырный» в большой миске", En = "Burndak Cheese big bowl", RuF = "большая миска на двоих. Вторым обычно оказывается сожаление", EnF = "a big bowl for two. The second one is usually regret", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#e09a2a" },
        new Def { Id = "Shine", Kind = Kind.Noodle, RuM = "Красная пачка с чёрным иероглифом. Говорят, он значит «острый». На острове проверить некому, придётся варить.", EnM = "A red pack with a black character on it. They say it means \"spicy\". Nobody on the island can confirm, so you will have to cook it.", Mesh = "brick0", Texture = "Shine", Kg = 0.12f, Water = 0.55f, Shape = "brick", Brand = "Shine", Kcal = 500f, Ru = "Острая лапша «Шайн Рамён»", En = "Shine Ramyun hot noodles", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "ShineHot", Kind = Kind.Brewed, RuM = "Говядина, грибы и перец в красном бульоне. Корейцы едят такое в горах, а гор у нас тут хватает.", EnM = "Beef, mushrooms and pepper in a red broth. Koreans eat this in the mountains, and mountains we have plenty of.", Raw = "Shine", Mesh = "PotHot", Texture = "ShineHot", Kg = 0.615f, Thirst = 16f, Warm = 1.7f, Shape = "brick", Brand = "Shine", Kcal = 500f, Ru = "Острая лапша «Шайн Рамён»", En = "Shine Ramyun hot noodles", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "ShineBlack", Kind = Kind.Noodle, RuM = "Чёрная пачка для тех, кто считает обычную слишком простой. Внутри костный бульон и чеснок, снаружи пафос.", EnM = "A black pack for those who find the regular one too plain. Bone broth and garlic inside, swagger outside.", Mesh = "kpack0", Texture = "ShineBlack", Kg = 0.114f, Water = 0.55f, Shape = "kpack", Brand = "Shine", Kcal = 500f, Ru = "Лапша «Шайн Рамён Блэк»", En = "Shine Ramyun Black noodles", RuF = "наваристый костный бульон, говядина, чеснок", EnF = "rich bone broth, beef and garlic", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b5552a" },
        new Def { Id = "ShineBlackHot", Kind = Kind.Brewed, RuM = "Бульон густой, белёсый и пахнет чесноком так, что медведь в берлоге перевернулся на другой бок.", EnM = "The broth is thick, milky and smells of garlic so hard the bear in its den rolled over.", Raw = "ShineBlack", Mesh = "PotHot", Texture = "ShineBlackHot", Kg = 0.609f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "Shine", Kcal = 500f, Ru = "Лапша «Шайн Рамён Блэк»", En = "Shine Ramyun Black noodles", RuF = "наваристый костный бульон, говядина, чеснок", EnF = "rich bone broth, beef and garlic", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b5552a" },
        new Def { Id = "ShineRed", Kind = Kind.Noodle, RuM = "На пачке написано, что она острее обычной. Обычная при этом тоже никого не жалела.", EnM = "The pack says it is hotter than the regular one. The regular one never spared anyone either.", Mesh = "kpack1", Texture = "ShineRed", Kg = 0.117f, Water = 0.55f, Shape = "kpack", Brand = "Shine", Kcal = 480f, Ru = "Лапша «Шайн Рамён Ред»", En = "Shine Ramyun Red noodles", RuF = "намного острее обычной", EnF = "much hotter than the regular one", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a81408" },
        new Def { Id = "ShineRedHot", Kind = Kind.Brewed, RuM = "Красная, как сигнальная ракета, и действует похоже: вас видно издалека, и вы светитесь.", EnM = "Red as a flare and works much the same: you can be seen from afar, and you glow.", Raw = "ShineRed", Mesh = "PotHot", Texture = "ShineRedHot", Kg = 0.612f, Thirst = 15f, Warm = 2.2f, Shape = "kpack", Brand = "Shine", Kcal = 480f, Ru = "Лапша «Шайн Рамён Ред»", En = "Shine Ramyun Red noodles", RuF = "намного острее обычной", EnF = "much hotter than the regular one", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a81408" },
        new Def { Id = "ShineGold", Kind = Kind.Noodle, RuM = "Золотая пачка. Золота на острове нет, зато есть курица с чесноком, а она полезнее.", EnM = "A golden pack. There is no gold on the island, but there is chicken with garlic, and that is more useful.", Mesh = "kpack0", Texture = "ShineGold", Kg = 0.12f, Water = 0.55f, Shape = "kpack", Brand = "Shine", Kcal = 490f, Ru = "Лапша «Шайн Рамён Голд»", En = "Shine Ramyun Gold noodles", RuF = "куриный бульон с чесноком", EnF = "chicken broth with garlic", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0a83a" },
        new Def { Id = "ShineGoldHot", Kind = Kind.Brewed, RuM = "Куриный бульон с чесноком, золотистый и честный. Лечит простуду, тоску и последствия прогулки до плотины.", EnM = "Chicken broth with garlic, golden and honest. It cures a cold, the blues and the after-effects of a walk to the dam.", Raw = "ShineGold", Mesh = "PotHot", Texture = "ShineGoldHot", Kg = 0.615f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "Shine", Kcal = 490f, Ru = "Лапша «Шайн Рамён Голд»", En = "Shine Ramyun Gold noodles", RuF = "куриный бульон с чесноком", EnF = "chicken broth with garlic", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0a83a" },
        new Def { Id = "ShineStirFry", Kind = Kind.Noodle, RuM = "Та же лапша, только жареная и без бульона. Воду всё равно придётся топить, не расслабляйтесь.", EnM = "The same noodles, only stir-fried and without broth. You still have to melt the water, so do not relax.", Mesh = "kpack0", Texture = "ShineStirFry", Kg = 0.124f, Water = 0.55f, Shape = "kpack", Brand = "Shine", Kcal = 510f, Ru = "Лапша «Шайн Рамён Поккым»", En = "Shine Ramyun Stir Fry noodles", RuF = "жареная, с острым соусом, без бульона", EnF = "stir-fried with a spicy sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a8381a" },
        new Def { Id = "ShineStirFryHot", Kind = Kind.Brewed, RuM = "Блестит от соуса и липнет к вилке. Бульона нет, запивать нечем, перец об этом знает.", EnM = "Glossy with sauce and clinging to the fork. No broth, nothing to wash it down, and the pepper knows it.", Raw = "ShineStirFry", Mesh = "PotHot", Texture = "ShineStirFryHot", Kg = 0.262f, Thirst = -10f, Warm = 1.35f, Shape = "kpack", Brand = "Shine", Kcal = 510f, Ru = "Лапша «Шайн Рамён Поккым»", En = "Shine Ramyun Stir Fry noodles", RuF = "жареная, с острым соусом, без бульона", EnF = "stir-fried with a spicy sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a8381a" },
        new Def { Id = "ShineCup", Kind = Kind.Noodle, RuM = "Стакан с красной крышкой. Крышку не выбрасывайте: на острове всё когда-нибудь пригождается.", EnM = "A cup with a red lid. Do not throw the lid away: on the island everything comes in handy one day.", Mesh = "tallcup", Texture = "ShineCup", Kg = 0.075f, Water = 0.35f, Shape = "tallcup", Brand = "Shine", Kcal = 330f, Ru = "Лапша «Шайн Рамён» в стакане", En = "Shine Ramyun cup", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "ShineCupHot", Kind = Kind.Brewed, RuM = "Говядина с грибами прямо в стакане. Руки греет не хуже костра, и дров при этом не просит.", EnM = "Beef and mushrooms right in the cup. It warms the hands as well as a campfire and asks for no firewood.", Raw = "ShineCup", Mesh = "tallcupHot", Texture = "ShineCup", Kg = 0.39f, Thirst = 18f, Warm = 1.8f, Shape = "tallcup", Brand = "Shine", Kcal = 330f, Ru = "Лапша «Шайн Рамён» в стакане", En = "Shine Ramyun cup", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "ShineBowl", Kind = Kind.Noodle, RuM = "Большая миска, в которую после еды можно собирать снег. Производитель такого не планировал.", EnM = "A big bowl you can gather snow in once you are done. The maker never planned for that.", Mesh = "kbowl", Texture = "ShineBowl", Kg = 0.11f, Water = 0.5f, Shape = "kbowl", Brand = "Shine", Kcal = 510f, Ru = "Лапша «Шайн Рамён» в большой миске", En = "Shine Ramyun big bowl", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "ShineBowlHot", Kind = Kind.Brewed, RuM = "Миска красного бульона на одного очень голодного человека. Других на Великом Медведе и не водится.", EnM = "A bowl of red broth for one very hungry person. Great Bear does not have any other kind.", Raw = "ShineBowl", Mesh = "kbowlHot", Texture = "ShineBowl", Kg = 0.56f, Thirst = 18f, Warm = 1.8f, Shape = "kbowl", Brand = "Shine", Kcal = 510f, Ru = "Лапша «Шайн Рамён» в большой миске", En = "Shine Ramyun big bowl", RuF = "острая говядина с грибами", EnF = "spicy beef and mushroom", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "JinMild", Kind = Kind.Noodle, RuM = "Мягкая, для тех, кто не хочет приключений. Приключения на этом острове и так выдают бесплатно.", EnM = "Mild, for people who want no adventures. On this island adventures are handed out for free anyway.", Mesh = "kpack0", Texture = "JinMild", Kg = 0.115f, Water = 0.55f, Shape = "kpack", Brand = "Jin", Kcal = 520f, Ru = "Лапша «Джин Рамён Мягкий»", En = "Jin Ramyun Mild noodles", RuF = "говяжий бульон, совсем не острый", EnF = "beef broth, not spicy at all", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98a4a" },
        new Def { Id = "JinMildHot", Kind = Kind.Brewed, RuM = "Спокойный говяжий бульон без единой перчинки. Самое мирное, что случалось с вами за последнюю неделю.", EnM = "A calm beef broth without a speck of pepper. The most peaceful thing that has happened to you all week.", Raw = "JinMild", Mesh = "PotHot", Texture = "JinMildHot", Kg = 0.61f, Thirst = 24f, Warm = 1.0f, Shape = "kpack", Brand = "Jin", Kcal = 520f, Ru = "Лапша «Джин Рамён Мягкий»", En = "Jin Ramyun Mild noodles", RuF = "говяжий бульон, совсем не острый", EnF = "beef broth, not spicy at all", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98a4a" },
        new Def { Id = "JinSpicy", Kind = Kind.Noodle, RuM = "Синяя пачка была мягкая, эта красная. Цвета тут как в природе: красное предупреждает.", EnM = "The blue pack was the mild one, this one is red. Colours work as they do in nature: red is a warning.", Mesh = "kpack1", Texture = "JinSpicy", Kg = 0.119f, Water = 0.55f, Shape = "kpack", Brand = "Jin", Kcal = 500f, Ru = "Лапша «Джин Рамён Острый»", En = "Jin Ramyun Spicy noodles", RuF = "говяжий бульон с перцем", EnF = "beef broth with pepper", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "JinSpicyHot", Kind = Kind.Brewed, RuM = "Говяжий бульон с перцем, без фокусов. Греет ровно и долго, как хорошая печка в охотничьем домике.", EnM = "Beef broth with pepper, no tricks. It warms steadily and long, like a good stove in a trapper's cabin.", Raw = "JinSpicy", Mesh = "PotHot", Texture = "JinSpicyHot", Kg = 0.614f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Jin", Kcal = 500f, Ru = "Лапша «Джин Рамён Острый»", En = "Jin Ramyun Spicy noodles", RuF = "говяжий бульон с перцем", EnF = "beef broth with pepper", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "JinCup", Kind = Kind.Noodle, RuM = "Острый бульон в стакане, удобно брать в дорогу. Дорог, правда, нет, есть рельсы и сугробы.", EnM = "Spicy broth in a cup, handy for the road. There are no roads though, only rails and snowdrifts.", Mesh = "tallcup", Texture = "JinCup", Kg = 0.071f, Water = 0.35f, Shape = "tallcup", Brand = "Jin", Kcal = 320f, Ru = "Лапша «Джин Рамён Острый» в стакане", En = "Jin Ramyun Spicy cup", RuF = "говяжий бульон с перцем", EnF = "beef broth with pepper", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "JinCupHot", Kind = Kind.Brewed, RuM = "Пар из стакана идёт вверх, вы сидите на рельсах и смотрите на сияние. Почти романтика, если бы не волки.", EnM = "Steam rises from the cup, you sit on the rails and watch the aurora. Almost romantic, if not for the wolves.", Raw = "JinCup", Mesh = "tallcupHot", Texture = "JinCup", Kg = 0.386f, Thirst = 18f, Warm = 1.8f, Shape = "tallcup", Brand = "Jin", Kcal = 320f, Ru = "Лапша «Джин Рамён Острый» в стакане", En = "Jin Ramyun Spicy cup", RuF = "говяжий бульон с перцем", EnF = "beef broth with pepper", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "NeoguriSpicy", Kind = Kind.Noodle, RuM = "На пачке енот. Что он делает на лапше с морепродуктами, не знает даже сам енот.", EnM = "There is a raccoon on the pack. What it is doing on seafood noodles, not even the raccoon knows.", Mesh = "kpack1", Texture = "NeoguriSpicy", Kg = 0.116f, Water = 0.55f, Shape = "kpack", Brand = "Neoguri", Kcal = 550f, Ru = "Лапша «Ноугури Острый»", En = "Nouguri Spicy noodles", RuF = "толстая лапша удон, морепродукты и ламинария", EnF = "thick udon noodles, seafood and kelp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c9461e" },
        new Def { Id = "NeoguriSpicyHot", Kind = Kind.Brewed, RuM = "Толстый удон, ламинария и перец. Пахнет морем, которое здесь замёрзло до самого горизонта.", EnM = "Thick udon, kelp and pepper. It smells of the sea, which around here is frozen all the way to the horizon.", Raw = "NeoguriSpicy", Mesh = "PotHot", Texture = "NeoguriSpicyHot", Kg = 0.611f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Neoguri", Kcal = 550f, Ru = "Лапша «Ноугури Острый»", En = "Nouguri Spicy noodles", RuF = "толстая лапша удон, морепродукты и ламинария", EnF = "thick udon noodles, seafood and kelp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c9461e" },
        new Def { Id = "NeoguriMild", Kind = Kind.Noodle, RuM = "Тот же енот, только добрый. Толстая лапша и морская капуста для тех, кто бережёт желудок.", EnM = "The same raccoon, only a kind one. Thick noodles and kelp for those who look after their stomach.", Mesh = "kpack0", Texture = "NeoguriMild", Kg = 0.125f, Water = 0.55f, Shape = "kpack", Brand = "Neoguri", Kcal = 530f, Ru = "Лапша «Ноугури Мягкий»", En = "Nouguri Mild noodles", RuF = "толстая лапша удон, морепродукты и ламинария", EnF = "thick udon noodles, seafood and kelp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "NeoguriMildHot", Kind = Kind.Brewed, RuM = "Мягкий морской бульон и лапша толщиной с верёвку альпиниста. По верёвке лезут вверх, эту тянут в рот.", EnM = "Mild sea broth and noodles as thick as a climbing rope. You climb a rope, this one you pull into your mouth.", Raw = "NeoguriMild", Mesh = "PotHot", Texture = "NeoguriMildHot", Kg = 0.62f, Thirst = 24f, Warm = 1.0f, Shape = "kpack", Brand = "Neoguri", Kcal = 530f, Ru = "Лапша «Ноугури Мягкий»", En = "Nouguri Mild noodles", RuF = "толстая лапша удон, морепродукты и ламинария", EnF = "thick udon noodles, seafood and kelp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "Chapagetti", Kind = Kind.Noodle, RuM = "Лапша с соусом из чёрных бобов. В Корее её ест вся семья по воскресеньям, на острове воскресенье отменили.", EnM = "Noodles with black bean sauce. In Korea the whole family eats it on Sundays, on the island Sundays have been cancelled.", Mesh = "kpack0", Texture = "Chapagetti", Kg = 0.12f, Water = 0.55f, Shape = "kpack", Brand = "Chapa", Kcal = 520f, Ru = "Лапша «Чапагэти»", En = "Chapagetti noodles", RuF = "лапша в соусе из чёрных бобов, без бульона", EnF = "noodles in black bean sauce, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "ChapagettiHot", Kind = Kind.Brewed, RuM = "Чёрная, сладковатая и пачкает всё вокруг. После неё улыбаться волкам не стоит: зубы тоже чёрные.", EnM = "Black, sweetish and it stains everything. Do not smile at the wolves afterwards: your teeth are black too.", Raw = "Chapagetti", Mesh = "PotHot", Texture = "ChapagettiHot", Kg = 0.258f, Thirst = -6f, Warm = 0.75f, Shape = "kpack", Brand = "Chapa", Kcal = 520f, Ru = "Лапша «Чапагэти»", En = "Chapagetti noodles", RuF = "лапша в соусе из чёрных бобов, без бульона", EnF = "noodles in black bean sauce, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "ChapaSichuan", Kind = Kind.Noodle, RuM = "Чёрные бобы с перцем. Кто-то решил, что тёмному соусу не хватало тёмных намерений.", EnM = "Black beans with pepper. Someone decided the dark sauce was short of dark intentions.", Mesh = "kpack0", Texture = "ChapaSichuan", Kg = 0.117f, Water = 0.55f, Shape = "kpack", Brand = "Chapa", Kcal = 520f, Ru = "Лапша «Чапагэти Сачхон»", En = "Chapagetti Sichuan noodles", RuF = "острый соус из чёрных бобов, без бульона", EnF = "spicy black bean sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#3a160e" },
        new Def { Id = "ChapaSichuanHot", Kind = Kind.Brewed, RuM = "Чёрный соус, красное масло, язык слегка немеет. В полярную ночь это блюдо можно потерять прямо в миске.", EnM = "Black sauce, red oil, a slightly numb tongue. In the polar night you could lose this dish right in the bowl.", Raw = "ChapaSichuan", Mesh = "PotHot", Texture = "ChapaSichuanHot", Kg = 0.255f, Thirst = -10f, Warm = 1.35f, Shape = "kpack", Brand = "Chapa", Kcal = 520f, Ru = "Лапша «Чапагэти Сачхон»", En = "Chapagetti Sichuan noodles", RuF = "острый соус из чёрных бобов, без бульона", EnF = "spicy black bean sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#3a160e" },
        new Def { Id = "Ansung", Kind = Kind.Noodle, RuM = "Бульон на соевой пасте, спокойный и домашний. Назван в честь города, где её делают; города у нас кончились, лапша осталась.", EnM = "A soybean paste broth, calm and homely. Named after the town that makes it; we ran out of towns, the noodles remained.", Mesh = "kpack1", Texture = "Ansung", Kg = 0.124f, Water = 0.55f, Shape = "kpack", Brand = "Ansung", Kcal = 500f, Ru = "Лапша «Ансон Мён»", En = "Ansung Myun noodles", RuF = "бульон на соевой пасте, мягкий вкус", EnF = "soybean paste broth, a mild taste", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "AnsungHot", Kind = Kind.Brewed, RuM = "Мягкий, чуть ореховый бульон. Пахнет чужой кухней, где тепло, горит свет и никто не слышал про геомагнитную бурю.", EnM = "A mild, slightly nutty broth. It smells of someone's kitchen where it is warm, the lights are on and nobody has heard of the geomagnetic storm.", Raw = "Ansung", Mesh = "PotHot", Texture = "AnsungHot", Kg = 0.619f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "Ansung", Kcal = 500f, Ru = "Лапша «Ансон Мён»", En = "Ansung Myun noodles", RuF = "бульон на соевой пасте, мягкий вкус", EnF = "soybean paste broth, a mild taste", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SamjanOriginal", Kind = Kind.Noodle, RuM = "Первая корейская лапша, с шестьдесят третьего года. Пачка, которую вы нашли, возможно, тоже оттуда.", EnM = "The first Korean noodles, since sixty-three. The pack you found may well be from back then too.", Mesh = "kpack1", Texture = "SamjanOriginal", Kg = 0.114f, Water = 0.55f, Shape = "kpack", Brand = "SamjanR", Kcal = 500f, Ru = "Лапша «Самджан Рамён»", En = "Samjan Ramyun Original noodles", RuF = "первая корейская лапша: бульон с ветчиной", EnF = "the first Korean ramyun: ham broth", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d9772e" },
        new Def { Id = "SamjanOriginalHot", Kind = Kind.Brewed, RuM = "Бульон с ветчиной, простой, как табуретка. Табуретку вы вчера сожгли, так что цените то, что осталось.", EnM = "A ham broth, plain as a stool. You burned the stool yesterday, so value what you have left.", Raw = "SamjanOriginal", Mesh = "PotHot", Texture = "SamjanOriginalHot", Kg = 0.609f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "SamjanR", Kcal = 500f, Ru = "Лапша «Самджан Рамён»", En = "Samjan Ramyun Original noodles", RuF = "первая корейская лапша: бульон с ветчиной", EnF = "the first Korean ramyun: ham broth", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d9772e" },
        new Def { Id = "SamjanCheese", Kind = Kind.Noodle, RuM = "Ветчина и сыр, почти бутерброд, только лапша. На острове, где хлеба нет, это считается за выпечку.", EnM = "Ham and cheese, nearly a sandwich, only it is noodles. On an island with no bread this counts as baking.", Mesh = "kpack0", Texture = "SamjanCheese", Kg = 0.123f, Water = 0.55f, Shape = "kpack", Brand = "SamjanR", Kcal = 490f, Ru = "Лапша «Самджан Рамён Сырный»", En = "Samjan Ramyun Cheese noodles", RuF = "бульон с ветчиной и сыром", EnF = "ham broth with cheese", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#e8a23a" },
        new Def { Id = "SamjanCheeseHot", Kind = Kind.Brewed, RuM = "Сыр растаял в бульоне с ветчиной. Серая Мать такое бы не одобрила, но съела бы.", EnM = "The cheese has melted into the ham broth. Grey Mother would not approve, but she would eat it.", Raw = "SamjanCheese", Mesh = "PotHot", Texture = "SamjanCheeseHot", Kg = 0.618f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "SamjanR", Kcal = 490f, Ru = "Лапша «Самджан Рамён Сырный»", En = "Samjan Ramyun Cheese noodles", RuF = "бульон с ветчиной и сыром", EnF = "ham broth with cheese", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#e8a23a" },
        new Def { Id = "PaltoBibim", Kind = Kind.Noodle, RuM = "Вообще-то её едят холодной. Холода здесь больше, чем нужно, поэтому варим как все.", EnM = "Strictly speaking it is eaten cold. There is more cold here than anyone needs, so we cook it like the rest.", Mesh = "kpack0", Texture = "PaltoBibim", Kg = 0.121f, Water = 0.55f, Shape = "kpack", Brand = "Palto", Kcal = 510f, Ru = "Лапша «Пальто Бибим Мён»", En = "Palto Bibim Myun noodles", RuF = "холодная лапша в кисло-сладком остром соусе, без бульона", EnF = "cold noodles in a sweet-and-sour hot sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#c4321e" },
        new Def { Id = "PaltoBibimHot", Kind = Kind.Brewed, RuM = "Кисло, сладко, остро и всё сразу. Как погода на здешних болотах, только вкусно.", EnM = "Sour, sweet and hot all at once. Like the weather at Forlorn Muskeg, only tasty.", Raw = "PaltoBibim", Mesh = "PotHot", Texture = "PaltoBibimHot", Kg = 0.259f, Thirst = -10f, Warm = 1.35f, Shape = "kpack", Brand = "Palto", Kcal = 510f, Ru = "Лапша «Пальто Бибим Мён»", En = "Palto Bibim Myun noodles", RuF = "холодная лапша в кисло-сладком остром соусе, без бульона", EnF = "cold noodles in a sweet-and-sour hot sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#c4321e" },
        new Def { Id = "PaltoKoko", Kind = Kind.Noodle, RuM = "Прозрачный куриный бульон с зелёным перцем. Выглядит как лекарство, действует как сюрприз.", EnM = "A clear chicken broth with green pepper. Looks like medicine, works like a surprise.", Mesh = "kpack0", Texture = "PaltoKoko", Kg = 0.122f, Water = 0.55f, Shape = "kpack", Brand = "Palto", Kcal = 500f, Ru = "Лапша «Пальто Коко Мён»", En = "Palto Kokomyun noodles", RuF = "прозрачный куриный бульон с зелёным перцем", EnF = "clear chicken broth with green chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#ecdcae" },
        new Def { Id = "PaltoKokoHot", Kind = Kind.Brewed, RuM = "Бульон светлый, перец зелёный и коварный. Курица тут ни при чём, она сама в шоке.", EnM = "The broth is clear, the pepper green and sneaky. The chicken has nothing to do with it, it is in shock itself.", Raw = "PaltoKoko", Mesh = "PotHot", Texture = "PaltoKokoHot", Kg = 0.617f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Palto", Kcal = 500f, Ru = "Лапша «Пальто Коко Мён»", En = "Palto Kokomyun noodles", RuF = "прозрачный куриный бульон с зелёным перцем", EnF = "clear chicken broth with green chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#ecdcae" },
        new Def { Id = "PaltoKing", Kind = Kind.Noodle, RuM = "«Королевская крышка»: крышка такая широкая, что на ней можно разложить карту региона.", EnM = "The \"king lid\": a lid so wide you could spread a region map on it.", Mesh = "kbowl", Texture = "PaltoKing", Kg = 0.113f, Water = 0.5f, Shape = "kbowl", Brand = "Palto", Kcal = 490f, Ru = "Лапша «Пальто Ван Ттуккон» в большой миске", En = "Palto King Lid big bowl", RuF = "большой стакан с широкой крышкой, острая говядина", EnF = "a big cup with a wide lid, spicy beef", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "PaltoKingHot", Kind = Kind.Brewed, RuM = "Большая порция острой говядины. Король на этом острове один, он бурый, и делиться с ним не надо.", EnM = "A big helping of spicy beef. This island has only one king, he is brown, and you need not share with him.", Raw = "PaltoKing", Mesh = "kbowlHot", Texture = "PaltoKing", Kg = 0.563f, Thirst = 18f, Warm = 1.8f, Shape = "kbowl", Brand = "Palto", Kcal = 490f, Ru = "Лапша «Пальто Ван Ттуккон» в большой миске", En = "Palto King Lid big bowl", RuF = "большой стакан с широкой крышкой, острая говядина", EnF = "a big cup with a wide lid, spicy beef", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "Yukgae", Kind = Kind.Noodle, RuM = "Тонкая лапша и острый говяжий суп. Корейцы берут её в поход, вы в походе уже который месяц.", EnM = "Thin noodles and spicy beef soup. Koreans take it hiking, and you have been on a hike for months now.", Mesh = "bowl", Texture = "Yukgae", Kg = 0.103f, Water = 0.45f, Shape = "bowl", Brand = "Yukgae", Kcal = 420f, Ru = "Лапша «Юккэджан» в миске", En = "Yukgaejang bowl", RuF = "острый говяжий суп, тонкая лапша", EnF = "spicy beef soup with thin noodles", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "YukgaeHot", Kind = Kind.Brewed, RuM = "Красный суп, тонкая лапша, пар в лицо. На секунду забываешь, что за дверью минус тридцать и кто-то воет.", EnM = "Red soup, thin noodles, steam in your face. For a second you forget it is minus thirty outside and something is howling.", Raw = "Yukgae", Mesh = "bowlHot", Texture = "Yukgae", Kg = 0.508f, Thirst = 18f, Warm = 1.8f, Shape = "bowl", Brand = "Yukgae", Kcal = 420f, Ru = "Лапша «Юккэджан» в миске", En = "Yukgaejang bowl", RuF = "острый говяжий суп, тонкая лапша", EnF = "spicy beef soup with thin noodles", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "KimchiMyun", Kind = Kind.Noodle, RuM = "Лапша с квашеной капустой. Капуста пережила ферментацию, перелёт и конец света, переживёт и вас.", EnM = "Noodles with fermented cabbage. The cabbage survived fermenting, the flight and the end of the world, it will outlive you too.", Mesh = "kpack2", Texture = "KimchiMyun", Kg = 0.123f, Water = 0.55f, Shape = "kpack", Brand = "KimchiM", Kcal = 510f, Ru = "Лапша «Чонга Кимчи Мён»", En = "Chonga Kimchi Myun noodles", RuF = "бульон с квашеной капустой кимчи", EnF = "broth with fermented kimchi cabbage", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "KimchiMyunHot", Kind = Kind.Brewed, RuM = "Кисло-острый бульон с кимчи. Запах такой, что хижину можно не запирать: никто не войдёт.", EnM = "A sour and spicy kimchi broth. The smell is such that you can leave the cabin unlocked: nobody will come in.", Raw = "KimchiMyun", Mesh = "PotHot", Texture = "KimchiMyunHot", Kg = 0.618f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "KimchiM", Kcal = 510f, Ru = "Лапша «Чонга Кимчи Мён»", En = "Chonga Kimchi Myun noodles", RuF = "бульон с квашеной капустой кимчи", EnF = "broth with fermented kimchi cabbage", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "KimchiCup", Kind = Kind.Noodle, RuM = "Кимчи в стакане. Открывать на улице не советуем: вороны запомнят вас надолго.", EnM = "Kimchi in a cup. We advise against opening it outdoors: the crows will remember you for a long time.", Mesh = "cup", Texture = "KimchiCup", Kg = 0.071f, Water = 0.3f, Shape = "cup", Brand = "KimchiM", Kcal = 320f, Ru = "Лапша «Чонга Кимчи Мён» в стакане", En = "Chonga Kimchi Myun cup", RuF = "бульон с квашеной капустой кимчи", EnF = "broth with fermented kimchi cabbage", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "KimchiCupHot", Kind = Kind.Brewed, RuM = "Горячий стакан с капустой и перцем. Держишь в руках и чувствуешь себя человеком, а не добычей.", EnM = "A hot cup of cabbage and pepper. You hold it and feel like a person, not like prey.", Raw = "KimchiCup", Mesh = "cupHot", Texture = "KimchiCup", Kg = 0.341f, Thirst = 18f, Warm = 1.8f, Shape = "cup", Brand = "KimchiM", Kcal = 320f, Ru = "Лапша «Чонга Кимчи Мён» в стакане", En = "Chonga Kimchi Myun cup", RuF = "бульон с квашеной капустой кимчи", EnF = "broth with fermented kimchi cabbage", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "Gomtang", Kind = Kind.Noodle, RuM = "Белый бульон на говяжьих костях. Кости варили сутки, вам хватит пяти минут и котелка.", EnM = "A white broth on beef bones. The bones were simmered for a day, you will need five minutes and a pot.", Mesh = "kpack2", Texture = "Gomtang", Kg = 0.116f, Water = 0.55f, Shape = "kpack", Brand = "Gomtang", Kcal = 490f, Ru = "Лапша «Сари Комтан»", En = "Sari Gomtang noodles", RuF = "молочно-белый бульон на говяжьих костях", EnF = "milky white beef bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "GomtangHot", Kind = Kind.Brewed, RuM = "Молочно-белый, густой и совсем не острый. После него хочется лечь у печки и никуда не идти. Вот и не ходите.", EnM = "Milky white, thick and not hot at all. It makes you want to lie down by the stove and go nowhere. So do not go.", Raw = "Gomtang", Mesh = "PotHot", Texture = "GomtangHot", Kg = 0.611f, Thirst = 24f, Warm = 1.0f, Shape = "kpack", Brand = "Gomtang", Kcal = 490f, Ru = "Лапша «Сари Комтан»", En = "Sari Gomtang noodles", RuF = "молочно-белый бульон на говяжьих костях", EnF = "milky white beef bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "Jjamppong", Kind = Kind.Noodle, RuM = "Острый суп с морепродуктами и дымком. Дымок настоящий, на пачке так и написано, а мы верим пачкам.", EnM = "A spicy seafood soup with a smoky note. The smoke is real, the pack says so, and we believe packs.", Mesh = "kpack0", Texture = "Jjamppong", Kg = 0.125f, Water = 0.55f, Shape = "kpack", Brand = "Jjamppong", Kcal = 540f, Ru = "Лапша «Чин Чамппон»", En = "Jin Jjamppong noodles", RuF = "острый суп с морепродуктами и дымком", EnF = "a spicy seafood soup with a smoky note", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#c2321a" },
        new Def { Id = "JjamppongHot", Kind = Kind.Brewed, RuM = "Красный бульон пахнет морем и костром сразу. Примерно как Прибрежное шоссе в хороший день, только хороших дней там нет.", EnM = "The red broth smells of sea and campfire at once. Much like Coastal Highway on a good day, only it has no good days.", Raw = "Jjamppong", Mesh = "PotHot", Texture = "JjamppongHot", Kg = 0.62f, Thirst = 15f, Warm = 2.2f, Shape = "kpack", Brand = "Jjamppong", Kcal = 540f, Ru = "Лапша «Чин Чамппон»", En = "Jin Jjamppong noodles", RuF = "острый суп с морепродуктами и дымком", EnF = "a spicy seafood soup with a smoky note", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#c2321a" },
        new Def { Id = "Teumsae", Kind = Kind.Noodle, RuM = "Одна из самых острых в Корее. Название значит «щель»: через неё, видимо, и уходит душа.", EnM = "One of the hottest in Korea. The name means \"gap\": apparently that is where the soul leaves through.", Mesh = "kpack1", Texture = "Teumsae", Kg = 0.117f, Water = 0.55f, Shape = "kpack", Brand = "Teumsae", Kcal = 540f, Ru = "Лапша «Тхымсэ»", En = "Teumsae noodles", RuF = "одна из самых острых: красный бульон-огонь", EnF = "one of the hottest: a fiery red broth", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#9c1208" },
        new Def { Id = "TeumsaeHot", Kind = Kind.Brewed, RuM = "Красный бульон-огонь. Мороз за окном минус сорок, у вас внутри плюс сорок, в среднем нормально.", EnM = "A red broth of pure fire. It is minus forty outside the window, plus forty inside you, fine on average.", Raw = "Teumsae", Mesh = "PotHot", Texture = "TeumsaeHot", Kg = 0.612f, Thirst = 12f, Warm = 2.6f, Shape = "kpack", Brand = "Teumsae", Kcal = 540f, Ru = "Лапша «Тхымсэ»", En = "Teumsae noodles", RuF = "одна из самых острых: красный бульон-огонь", EnF = "one of the hottest: a fiery red broth", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#9c1208" },
        new Def { Id = "Yeul", Kind = Kind.Noodle, RuM = "«Ёль» значит «жар». Корейцы называют вещи прямо, им некогда.", EnM = "\"Yeul\" means \"heat\". Koreans call things what they are, they have no time to waste.", Mesh = "kpack2", Texture = "Yeul", Kg = 0.123f, Water = 0.55f, Shape = "kpack", Brand = "Yeul", Kcal = 500f, Ru = "Лапша «Ёль Рамён»", En = "Yeul Ramyun noodles", RuF = "жгучий говяжий бульон", EnF = "a burning beef broth", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#b01c0c" },
        new Def { Id = "YeulHot", Kind = Kind.Brewed, RuM = "Жгучий говяжий бульон. Одна миска заменяет вязанку дров, только дрова так не жалуются на утро.", EnM = "A scorching beef broth. One bowl replaces a bundle of firewood, only firewood does not complain like this in the morning.", Raw = "Yeul", Mesh = "PotHot", Texture = "YeulHot", Kg = 0.618f, Thirst = 15f, Warm = 2.2f, Shape = "kpack", Brand = "Yeul", Kcal = 500f, Ru = "Лапша «Ёль Рамён»", En = "Yeul Ramyun noodles", RuF = "жгучий говяжий бульон", EnF = "a burning beef broth", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#b01c0c" },
        new Def { Id = "Kalguksu", Kind = Kind.Noodle, RuM = "Плоская лапша «из-под ножа» в бульоне из анчоусов. Нож у вас есть, анчоусов нет, поэтому пачка.", EnM = "Flat \"knife-cut\" noodles in anchovy broth. You have a knife, you have no anchovies, hence the pack.", Mesh = "kpack2", Texture = "Kalguksu", Kg = 0.121f, Water = 0.55f, Shape = "kpack", Brand = "Kalguksu", Kcal = 480f, Ru = "Лапша «Мёльчи Кальгуксу»", En = "Myeolchi Kalguksu noodles", RuF = "плоская лапша в бульоне из анчоусов, не острая", EnF = "flat noodles in anchovy broth, not spicy", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#ecd9a0" },
        new Def { Id = "KalguksuHot", Kind = Kind.Brewed, RuM = "Широкая мягкая лапша в светлом рыбном бульоне. Рыбаки с Загадочного озера оценили бы, если бы там остались рыбаки.", EnM = "Wide soft noodles in a light fish broth. The fishermen of Mystery Lake would approve, if any fishermen were left there.", Raw = "Kalguksu", Mesh = "PotHot", Texture = "KalguksuHot", Kg = 0.616f, Thirst = 24f, Warm = 1.0f, Shape = "kpack", Brand = "Kalguksu", Kcal = 480f, Ru = "Лапша «Мёльчи Кальгуксу»", En = "Myeolchi Kalguksu noodles", RuF = "плоская лапша в бульоне из анчоусов, не острая", EnF = "flat noodles in anchovy broth, not spicy", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#ecd9a0" },
        new Def { Id = "SesameCup", Kind = Kind.Noodle, RuM = "Кунжут и яичные хлопья в большом стакане. Яйцо на острове можно увидеть только здесь, любуйтесь.", EnM = "Sesame and egg flakes in a big cup. This is the only place on the island to see an egg, so enjoy the view.", Mesh = "bigcup", Texture = "SesameCup", Kg = 0.1f, Water = 0.5f, Shape = "bigcup", Brand = "Sesame", Kcal = 470f, Ru = "Лапша «Чхамккэ Рамён» в большом стакане", En = "Chamkkae Ramyun big cup", RuF = "кунжут и яичные хлопья в остром бульоне", EnF = "sesame and egg flakes in a spicy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#d8642a" },
        new Def { Id = "SesameCupHot", Kind = Kind.Brewed, RuM = "Острый бульон, сверху плавает кунжут. Пахнет так уютно, что хочется позвать гостей. Не зовите, придут волки.", EnM = "Spicy broth with sesame floating on top. It smells so cosy you want to invite guests. Do not, the wolves will come.", Raw = "SesameCup", Mesh = "bigcupHot", Texture = "SesameCup", Kg = 0.55f, Thirst = 18f, Warm = 1.8f, Shape = "bigcup", Brand = "Sesame", Kcal = 470f, Ru = "Лапша «Чхамккэ Рамён» в большом стакане", En = "Chamkkae Ramyun big cup", RuF = "кунжут и яичные хлопья в остром бульоне", EnF = "sesame and egg flakes in a spicy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#d8642a" },
        new Def { Id = "SesamePack", Kind = Kind.Noodle, RuM = "Та же кунжутная, только в пачке. Яичный брикетик внутри выглядит странно, но это еда, честное слово.", EnM = "The same sesame one, only in a pack. The little egg block inside looks odd, but it is food, honest.", Mesh = "kpack1", Texture = "SesamePack", Kg = 0.121f, Water = 0.55f, Shape = "kpack", Brand = "Sesame", Kcal = 520f, Ru = "Лапша «Чхамккэ Рамён»", En = "Chamkkae Ramyun noodles", RuF = "кунжут и яичные хлопья в остром бульоне", EnF = "sesame and egg flakes in a spicy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#d8642a" },
        new Def { Id = "SesamePackHot", Kind = Kind.Brewed, RuM = "Яичные хлопья распустились в бульоне, как цветы. Других цветов до весны не будет, а весны не будет вообще.", EnM = "The egg flakes have opened in the broth like flowers. There will be no other flowers until spring, and there will be no spring.", Raw = "SesamePack", Mesh = "PotHot", Texture = "SesamePackHot", Kg = 0.616f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Sesame", Kcal = 520f, Ru = "Лапша «Чхамккэ Рамён»", En = "Chamkkae Ramyun noodles", RuF = "кунжут и яичные хлопья в остром бульоне", EnF = "sesame and egg flakes in a spicy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#d8642a" },
        new Def { Id = "Chikin", Kind = Kind.Noodle, RuM = "Первая лапша быстрого приготовления в мире. С неё всё началось, а закончилось вами на острове с котелком.", EnM = "The first instant noodles in the world. It all began with them and ended with you on an island with a pot.", Mesh = "brick0", Texture = "Chikin", Kg = 0.085f, Water = 0.45f, Shape = "brick", Brand = "Chikin", Kcal = 380f, Ru = "Лапша «Ниссун Чикин Рамен»", En = "Nissun Chikin Ramen", RuF = "классическая куриная", EnF = "the classic chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d9a441" },
        new Def { Id = "ChikinHot", Kind = Kind.Brewed, RuM = "Простой куриный вкус, которому больше шестидесяти лет. Старше него на острове только Серая Мать и медведь.", EnM = "A plain chicken taste more than sixty years old. Only Grey Mother and the bear are older on this island.", Raw = "Chikin", Mesh = "DonburiHot", Texture = "ChikinHot", Kg = 0.49f, Thirst = 22f, Warm = 1.0f, Shape = "brick", Brand = "Chikin", Kcal = 380f, Ru = "Лапша «Ниссун Чикин Рамен»", En = "Nissun Chikin Ramen", RuF = "классическая куриная", EnF = "the classic chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d9a441" },
        new Def { Id = "ChikinDon", Kind = Kind.Noodle, RuM = "Миска с ямкой для яйца. Яйца нет, ямка есть. На Великом Медведе вообще много пустых мест.", EnM = "A bowl with a dent for an egg. There is no egg, but there is a dent. Great Bear has a lot of empty places in general.", Mesh = "bowl", Texture = "ChikinDon", Kg = 0.096f, Water = 0.45f, Shape = "bowl", Brand = "Chikin", Kcal = 460f, Ru = "Лапша «Ниссун Чикин Рамен» в миске", En = "Nissun Chikin Ramen bowl", RuF = "классическая куриная, с сушёным яйцом", EnF = "the classic chicken, with dried egg", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d9a441" },
        new Def { Id = "ChikinDonHot", Kind = Kind.Brewed, RuM = "Куриная лапша под сушёным яйцом. Залил, накрыл, подождал. Три минуты покоя, редкая роскошь.", EnM = "Chicken noodles under a dried egg. Pour, cover, wait. Three minutes of peace, a rare luxury.", Raw = "ChikinDon", Mesh = "bowlHot", Texture = "ChikinDon", Kg = 0.501f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Chikin", Kcal = 460f, Ru = "Лапша «Ниссун Чикин Рамен» в миске", En = "Nissun Chikin Ramen bowl", RuF = "классическая куриная, с сушёным яйцом", EnF = "the classic chicken, with dried egg", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d9a441" },
        new Def { Id = "KappNoodle", Kind = Kind.Noodle, RuM = "Стакан, который летал в космос. Теперь он лежит в шкафчике на заправке, и это тоже своего рода космос.", EnM = "A cup that has been to space. Now it sits in a cupboard at a gas station, which is a kind of space too.", Mesh = "cup", Texture = "KappNoodle", Kg = 0.07f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 330f, Ru = "Лапша «Капп Нудл» в стакане", En = "Kapp Noodle cup", RuF = "морепродукты", EnF = "seafood", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "KappNoodleHot", Kind = Kind.Brewed, RuM = "Креветки, кальмар и яйцо в белом бульоне. Море в стакане, пока настоящее стоит под метровым льдом.", EnM = "Shrimp, squid and egg in a white broth. The sea in a cup while the real one lies under a metre of ice.", Raw = "KappNoodle", Mesh = "cupHot", Texture = "KappNoodle", Kg = 0.34f, Thirst = 20f, Warm = 1.0f, Shape = "cup", Brand = "Kapp", Kcal = 330f, Ru = "Лапша «Капп Нудл» в стакане", En = "Kapp Noodle cup", RuF = "морепродукты", EnF = "seafood", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "KappSoy", Kind = Kind.Noodle, RuM = "Оригинальный вкус семьдесят первого года. Мясные кубики внутри прозвали «загадочным мясом», и загадку так и не раскрыли.", EnM = "The original taste of seventy-one. The meat cubes inside were nicknamed \"mystery meat\", and the mystery was never solved.", Mesh = "cup", Texture = "KappSoy", Kg = 0.072f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 340f, Ru = "Лапша «Капп Нудл Оригинальный» в стакане", En = "Kapp Noodle Original cup", RuF = "соевый бульон, креветки, яйцо и мясные кубики", EnF = "soy broth with shrimp, egg and meat cubes", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "KappSoyHot", Kind = Kind.Brewed, RuM = "Соевый бульон, креветки и те самые кубики. Загадочное мясо у Загадочного озера: всё сошлось.", EnM = "Soy broth, shrimp and those very cubes. Mystery meat by Mystery Lake: it all adds up.", Raw = "KappSoy", Mesh = "cupHot", Texture = "KappSoy", Kg = 0.342f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "Kapp", Kcal = 340f, Ru = "Лапша «Капп Нудл Оригинальный» в стакане", En = "Kapp Noodle Original cup", RuF = "соевый бульон, креветки, яйцо и мясные кубики", EnF = "soy broth with shrimp, egg and meat cubes", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "KappCurry", Kind = Kind.Noodle, RuM = "Карри в стакане, густое, как туман над болотом. Ложка стоит, если у вас есть ложка.", EnM = "Curry in a cup, thick as the fog over the muskeg. A spoon stands up in it, if you have a spoon.", Mesh = "cup", Texture = "KappCurry", Kg = 0.074f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 340f, Ru = "Лапша «Капп Нудл Карри» в стакане", En = "Kapp Noodle Curry cup", RuF = "густое японское карри", EnF = "thick Japanese curry", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "KappCurryHot", Kind = Kind.Brewed, RuM = "Густое японское карри с лапшой. Одежду потом не отстирать, но стиральных машин тут всё равно нет.", EnM = "Thick Japanese curry with noodles. It will never wash out of your clothes, but there are no washing machines here anyway.", Raw = "KappCurry", Mesh = "cupHot", Texture = "KappCurry", Kg = 0.344f, Thirst = 21f, Warm = 1.4f, Shape = "cup", Brand = "Kapp", Kcal = 340f, Ru = "Лапша «Капп Нудл Карри» в стакане", En = "Kapp Noodle Curry cup", RuF = "густое японское карри", EnF = "thick Japanese curry", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "KappChili", Kind = Kind.Noodle, RuM = "Томат и перец, красный стакан. По виду суп, по характеру предупреждение.", EnM = "Tomato and pepper, a red cup. A soup by the look of it, a warning by nature.", Mesh = "cup", Texture = "KappChili", Kg = 0.074f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 310f, Ru = "Лапша «Капп Нудл Чили-томат» в стакане", En = "Kapp Noodle Chili Tomato cup", RuF = "томатный бульон с перцем", EnF = "tomato broth with chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#d2452a" },
        new Def { Id = "KappChiliHot", Kind = Kind.Brewed, RuM = "Томатный бульон с перцем. Кисловатый, бодрый, красный. Самое яркое пятно в этом белом пейзаже.", EnM = "Tomato broth with pepper. Tangy, lively, red. The brightest spot in this white landscape.", Raw = "KappChili", Mesh = "cupHot", Texture = "KappChili", Kg = 0.344f, Thirst = 18f, Warm = 1.8f, Shape = "cup", Brand = "Kapp", Kcal = 310f, Ru = "Лапша «Капп Нудл Чили-томат» в стакане", En = "Kapp Noodle Chili Tomato cup", RuF = "томатный бульон с перцем", EnF = "tomato broth with chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#d2452a" },
        new Def { Id = "KappMiso", Kind = Kind.Noodle, RuM = "Мисо с имбирём. Имбирь от простуды, мисо от тоски, стакан от голода. Аптечка, а не еда.", EnM = "Miso with ginger. Ginger for a cold, miso for the blues, the cup for hunger. A first aid kit, not a meal.", Mesh = "cup", Texture = "KappMiso", Kg = 0.072f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 310f, Ru = "Лапша «Капп Нудл Мисо» в стакане", En = "Kapp Noodle Miso cup", RuF = "бульон на мисо с имбирём", EnF = "miso broth with ginger", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "KappMisoHot", Kind = Kind.Brewed, RuM = "Мутный тёплый бульон пахнет имбирём. Греет изнутри тихо и надёжно, как свитер, который связала бабушка.", EnM = "A cloudy warm broth that smells of ginger. It warms you from inside quietly and surely, like a sweater your grandmother knitted.", Raw = "KappMiso", Mesh = "cupHot", Texture = "KappMiso", Kg = 0.342f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "Kapp", Kcal = 310f, Ru = "Лапша «Капп Нудл Мисо» в стакане", En = "Kapp Noodle Miso cup", RuF = "бульон на мисо с имбирём", EnF = "miso broth with ginger", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "KappCheese", Kind = Kind.Noodle, RuM = "Карри с сыром. Кто-то в Японии решил, что карри недостаточно густое, и исправил это.", EnM = "Curry with cheese. Someone in Japan decided curry was not thick enough and fixed that.", Mesh = "cup", Texture = "KappCheese", Kg = 0.068f, Water = 0.3f, Shape = "cup", Brand = "Kapp", Kcal = 330f, Ru = "Лапша «Капп Нудл Сырное карри» в стакане", En = "Kapp Noodle Cheese Curry cup", RuF = "карри с расплавленным сыром", EnF = "curry with melted cheese", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#e0a428" },
        new Def { Id = "KappCheeseHot", Kind = Kind.Brewed, RuM = "Сыр расплавился в карри. Калорий столько, что можно дойти до Волчьей горы. Обратно уже сами.", EnM = "The cheese has melted into the curry. Enough calories to walk to Timberwolf Mountain. Getting back is up to you.", Raw = "KappCheese", Mesh = "cupHot", Texture = "KappCheese", Kg = 0.338f, Thirst = 21f, Warm = 1.4f, Shape = "cup", Brand = "Kapp", Kcal = 330f, Ru = "Лапша «Капп Нудл Сырное карри» в стакане", En = "Kapp Noodle Cheese Curry cup", RuF = "карри с расплавленным сыром", EnF = "curry with melted cheese", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#e0a428" },
        new Def { Id = "KappBig", Kind = Kind.Noodle, RuM = "Королевский размер. Двойная порция для тех, кто весь день рубил дрова и убегал.", EnM = "King size. A double helping for those who spent the day chopping wood and running away.", Mesh = "bigcup", Texture = "KappBig", Kg = 0.104f, Water = 0.5f, Shape = "bigcup", Brand = "Kapp", Kcal = 480f, Ru = "Лапша «Капп Нудл Кинг» в большом стакане", En = "Kapp Noodle King big cup", RuF = "двойная порция в соевом бульоне", EnF = "a double helping in soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "KappBigHot", Kind = Kind.Brewed, RuM = "Двойная порция в соевом бульоне. Стакан кончается не скоро, и это единственное, что на острове не кончается быстро.", EnM = "A double helping in soy broth. The cup takes a while to finish, the only thing on the island that does not run out fast.", Raw = "KappBig", Mesh = "bigcupHot", Texture = "KappBig", Kg = 0.554f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "Kapp", Kcal = 480f, Ru = "Лапша «Капп Нудл Кинг» в большом стакане", En = "Kapp Noodle King big cup", RuF = "двойная порция в соевом бульоне", EnF = "a double helping in soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "SappuroShoyu", Kind = Kind.Noodle, RuM = "Соевый бульон из города, где снега выпадает по пять метров. Там бы ваши жалобы на погоду не поняли.", EnM = "A soy broth from a city that gets five metres of snow. They would not understand your complaints about the weather there.", Mesh = "jpack1", Texture = "SappuroShoyu", Kg = 0.1f, Water = 0.5f, Shape = "jpack", Brand = "Sappuro", Kcal = 450f, Ru = "Лапша «Саппуро Итибан Сёю»", En = "Sappuro Ichiban Shoyu noodles", RuF = "соевый бульон", EnF = "soy sauce broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "SappuroShoyuHot", Kind = Kind.Brewed, RuM = "Тёмный прозрачный бульон, простой и правильный. Северная еда для северных людей, даже если вы тут случайно.", EnM = "A dark clear broth, simple and right. Northern food for northern people, even if you are here by accident.", Raw = "SappuroShoyu", Mesh = "DonburiHot", Texture = "SappuroShoyuHot", Kg = 0.55f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Sappuro", Kcal = 450f, Ru = "Лапша «Саппуро Итибан Сёю»", En = "Sappuro Ichiban Shoyu noodles", RuF = "соевый бульон", EnF = "soy sauce broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "SappuroMiso", Kind = Kind.Noodle, RuM = "Мисо с овощами. В Саппоро этим греются после лыж, а вы греетесь после волков.", EnM = "Miso with vegetables. In Sapporo they warm up with it after skiing, you warm up after wolves.", Mesh = "jpack1", Texture = "SappuroMiso", Kg = 0.1f, Water = 0.5f, Shape = "jpack", Brand = "Sappuro", Kcal = 420f, Ru = "Лапша «Саппуро Итибан Мисо»", En = "Sappuro Ichiban Miso noodles", RuF = "бульон на мисо с овощами", EnF = "miso broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SappuroMisoHot", Kind = Kind.Brewed, RuM = "Густой бульон на мисо. Овощи в нём сушёные, но это больше овощей, чем вы видели с самого крушения.", EnM = "A thick miso broth. The vegetables in it are dried, but that is still more vegetables than you have seen since the crash.", Raw = "SappuroMiso", Mesh = "DonburiHot", Texture = "SappuroMisoHot", Kg = 0.55f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Sappuro", Kcal = 420f, Ru = "Лапша «Саппуро Итибан Мисо»", En = "Sappuro Ichiban Miso noodles", RuF = "бульон на мисо с овощами", EnF = "miso broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SappuroShio", Kind = Kind.Noodle, RuM = "Светлый солёный бульон с кунжутом. Самый скромный в семье, зато его никто не ругает.", EnM = "A light salt broth with sesame. The most modest of the family, yet nobody ever scolds it.", Mesh = "jpack1", Texture = "SappuroShio", Kg = 0.101f, Water = 0.5f, Shape = "jpack", Brand = "Sappuro", Kcal = 410f, Ru = "Лапша «Саппуро Итибан Сио»", En = "Sappuro Ichiban Shio noodles", RuF = "светлый солёный бульон с кунжутом", EnF = "a light salt broth with sesame", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "SappuroShioHot", Kind = Kind.Brewed, RuM = "Прозрачный, как лёд на озере, только тёплый и в него можно лапшу. Со льдом так не получится.", EnM = "Clear as lake ice, only warm and you can put noodles in it. That does not work with ice.", Raw = "SappuroShio", Mesh = "DonburiHot", Texture = "SappuroShioHot", Kg = 0.551f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Sappuro", Kcal = 410f, Ru = "Лапша «Саппуро Итибан Сио»", En = "Sappuro Ichiban Shio noodles", RuF = "светлый солёный бульон с кунжутом", EnF = "a light salt broth with sesame", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "SappuroTonkotsu", Kind = Kind.Noodle, RuM = "Густой свиной бульон. Свиней на острове нет, поэтому берегите пачку.", EnM = "A thick pork broth. There are no pigs on the island, so look after the pack.", Mesh = "jpack0", Texture = "SappuroTonkotsu", Kg = 0.106f, Water = 0.5f, Shape = "jpack", Brand = "Sappuro", Kcal = 440f, Ru = "Лапша «Саппуро Итибан Тонкоцу»", En = "Sappuro Ichiban Tonkotsu noodles", RuF = "густой свиной бульон", EnF = "a thick pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "SappuroTonkotsuHot", Kind = Kind.Brewed, RuM = "Белый, жирный и сытный. После миски такого можно час не думать о еде. На острове это отпуск.", EnM = "White, rich and filling. After a bowl of it you can spend an hour not thinking about food. On the island that is a holiday.", Raw = "SappuroTonkotsu", Mesh = "DonburiHot", Texture = "SappuroTonkotsuHot", Kg = 0.556f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Sappuro", Kcal = 440f, Ru = "Лапша «Саппуро Итибан Тонкоцу»", En = "Sappuro Ichiban Tonkotsu noodles", RuF = "густой свиной бульон", EnF = "a thick pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "SappuroYakisoba", Kind = Kind.Noodle, RuM = "Жареная лапша в соусе. Жарить не надо, заливать и сливать. Сливать воду на острове обидно, но так велит рецепт.", EnM = "Fried noodles in sauce. No frying needed, pour and drain. Draining water on the island hurts, but the recipe says so.", Mesh = "jpack1", Texture = "SappuroYakisoba", Kg = 0.096f, Water = 0.5f, Shape = "jpack", Brand = "Sappuro", Kcal = 450f, Ru = "Лапша «Саппуро Итибан Якисоба»", En = "Sappuro Ichiban Yakisoba noodles", RuF = "жареная лапша в соусе, без бульона", EnF = "fried noodles in sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "SappuroYakisobaHot", Kind = Kind.Brewed, RuM = "Соус сладковатый, лапша упругая, бульона нет. Еда уличных праздников для места, где на улице лучше не задерживаться.", EnM = "Sweetish sauce, springy noodles, no broth. Street festival food for a place where you had better not linger in the street.", Raw = "SappuroYakisoba", Mesh = "PlateHot", Texture = "SappuroYakisobaHot", Kg = 0.221f, Thirst = -6f, Warm = 0.75f, Shape = "jpack", Brand = "Sappuro", Kcal = 450f, Ru = "Лапша «Саппуро Итибан Якисоба»", En = "Sappuro Ichiban Yakisoba noodles", RuF = "жареная лапша в соусе, без бульона", EnF = "fried noodles in sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "SappuroMisoCup", Kind = Kind.Noodle, RuM = "Мисо в миске с крышкой. Крышку придавите чем-нибудь тяжёлым. Топор подойдёт.", EnM = "Miso in a bowl with a lid. Weigh the lid down with something heavy. A hatchet will do.", Mesh = "bowl", Texture = "SappuroMisoCup", Kg = 0.101f, Water = 0.45f, Shape = "bowl", Brand = "Sappuro", Kcal = 410f, Ru = "Лапша «Саппуро Итибан Мисо» в миске", En = "Sappuro Ichiban Miso bowl", RuF = "бульон на мисо с овощами", EnF = "miso broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SappuroMisoCupHot", Kind = Kind.Brewed, RuM = "Бульон на мисо с овощами, пар валит из-под крышки. В хижине сразу пахнет так, будто тут кто-то живёт.", EnM = "Miso broth with vegetables, steam pouring from under the lid. At once the cabin smells as if somebody lives here.", Raw = "SappuroMisoCup", Mesh = "bowlHot", Texture = "SappuroMisoCup", Kg = 0.506f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Sappuro", Kcal = 410f, Ru = "Лапша «Саппуро Итибан Мисо» в миске", En = "Sappuro Ichiban Miso bowl", RuF = "бульон на мисо с овощами", EnF = "miso broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "AkaiKitsune", Kind = Kind.Noodle, RuM = "«Красная лиса». По легенде лисы обожают жареный тофу. Местные волки легенду не читали.", EnM = "\"Red Fox\". Legend says foxes adore fried tofu. The local wolves have not read the legend.", Mesh = "bowl", Texture = "AkaiKitsune", Kg = 0.1f, Water = 0.45f, Shape = "bowl", Brand = "Marutyan", Kcal = 440f, Ru = "Удон «Акай Кицунэ»", En = "Akai Kitsune udon", RuF = "удон с жареным тофу", EnF = "udon with fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a4a" },
        new Def { Id = "AkaiKitsuneHot", Kind = Kind.Brewed, RuM = "Толстый удон и сладкий кусок тофу размером с ладонь. Лиса бы оценила, а вы просто съешьте.", EnM = "Thick udon and a sweet slab of tofu the size of your palm. A fox would appreciate it, you just eat it.", Raw = "AkaiKitsune", Mesh = "bowlHot", Texture = "AkaiKitsune", Kg = 0.505f, Thirst = 24f, Warm = 1.2f, Shape = "bowl", Brand = "Marutyan", Kcal = 440f, Ru = "Удон «Акай Кицунэ»", En = "Akai Kitsune udon", RuF = "удон с жареным тофу", EnF = "udon with fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a4a" },
        new Def { Id = "MidoriTanuki", Kind = Kind.Noodle, RuM = "«Зелёный тануки». Тануки в сказках превращается во что угодно, этот превратился в гречневую лапшу.", EnM = "\"Green Tanuki\". In the tales a tanuki turns into anything, this one turned into buckwheat noodles.", Mesh = "bowl", Texture = "MidoriTanuki", Kg = 0.105f, Water = 0.45f, Shape = "bowl", Brand = "Marutyan", Kcal = 450f, Ru = "Лапша «Марутян Мидори-но Тануки» в миске", En = "Maruchyan Midori no Tanuki bowl", RuF = "гречневая соба с темпурой", EnF = "buckwheat soba with tempura", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "MidoriTanukiHot", Kind = Kind.Brewed, RuM = "Гречневая соба, сверху диск темпуры. Сначала он хрустит, потом размокает. Всё как с вашими ботинками.", EnM = "Buckwheat soba with a disc of tempura on top. First it crunches, then it goes soggy. Just like your boots.", Raw = "MidoriTanuki", Mesh = "bowlHot", Texture = "MidoriTanuki", Kg = 0.51f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Marutyan", Kcal = 450f, Ru = "Лапша «Марутян Мидори-но Тануки» в миске", En = "Maruchyan Midori no Tanuki bowl", RuF = "гречневая соба с темпурой", EnF = "buckwheat soba with tempura", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "KuroiButa", Kind = Kind.Noodle, RuM = "«Чёрная свинья» в карри. Звучит как прозвище медведя с Волчьей горы, а это просто ужин.", EnM = "\"Black Pig\" in curry. Sounds like a nickname for the bear of Timberwolf Mountain, but it is just dinner.", Mesh = "bowl", Texture = "KuroiButa", Kg = 0.102f, Water = 0.45f, Shape = "bowl", Brand = "Marutyan", Kcal = 440f, Ru = "Удон «Марутян Курой Бута Карри» в миске", En = "Maruchyan Kuroi Buta Curry bowl", RuF = "удон в карри со свининой", EnF = "curry udon with pork", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#a8741c" },
        new Def { Id = "KuroiButaHot", Kind = Kind.Brewed, RuM = "Удон тонет в карри со свининой. Густо, сытно, коричнево. После такой миски в спальник падают без снотворного.", EnM = "Udon sinking in pork curry. Thick, filling, brown. After a bowl like this you drop into the bedroll with no sleeping aid.", Raw = "KuroiButa", Mesh = "bowlHot", Texture = "KuroiButa", Kg = 0.507f, Thirst = 21f, Warm = 1.4f, Shape = "bowl", Brand = "Marutyan", Kcal = 440f, Ru = "Удон «Марутян Курой Бута Карри» в миске", En = "Maruchyan Kuroi Buta Curry bowl", RuF = "удон в карри со свининой", EnF = "curry udon with pork", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#a8741c" },
        new Def { Id = "SeimenShoyu", Kind = Kind.Noodle, RuM = "Лапша, которая притворяется свежей. У неё получается лучше, чем у вас притворяться спокойным при виде медведя.", EnM = "Noodles that pretend to be fresh. They do it better than you pretend to be calm at the sight of the bear.", Mesh = "jpack2", Texture = "SeimenShoyu", Kg = 0.095f, Water = 0.5f, Shape = "jpack", Brand = "Marutyan", Kcal = 450f, Ru = "Лапша «Марутян Сэймэн Сёю»", En = "Maruchyan Seimen Shoyu noodles", RuF = "лапша как свежая, соевый бульон", EnF = "noodles like fresh ones, soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "SeimenShoyuHot", Kind = Kind.Brewed, RuM = "Соевый бульон и лапша как из лапшичной. Закрой глаза, и ты в Токио. Открой, и ты опять в рыбацкой будке.", EnM = "Soy broth and noodles as if from a noodle shop. Close your eyes and you are in Tokyo. Open them and you are back in a fishing hut.", Raw = "SeimenShoyu", Mesh = "DonburiHot", Texture = "SeimenShoyuHot", Kg = 0.545f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Marutyan", Kcal = 450f, Ru = "Лапша «Марутян Сэймэн Сёю»", En = "Maruchyan Seimen Shoyu noodles", RuF = "лапша как свежая, соевый бульон", EnF = "noodles like fresh ones, soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "SeimenMiso", Kind = Kind.Noodle, RuM = "Мисо и лапша «как свежая». Свежего на острове только снег, и тот вчерашний.", EnM = "Miso and \"fresh-style\" noodles. The only fresh thing on the island is snow, and that is yesterday's.", Mesh = "jpack1", Texture = "SeimenMiso", Kg = 0.102f, Water = 0.5f, Shape = "jpack", Brand = "Marutyan", Kcal = 470f, Ru = "Лапша «Марутян Сэймэн Мисо»", En = "Maruchyan Seimen Miso noodles", RuF = "лапша как свежая, бульон на мисо", EnF = "noodles like fresh ones, miso broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SeimenMisoHot", Kind = Kind.Brewed, RuM = "Густое мисо обнимает упругую лапшу. Больше вас на этом острове никто обнимать не собирается.", EnM = "Thick miso hugs the springy noodles. Nobody else on this island is planning to hug you.", Raw = "SeimenMiso", Mesh = "DonburiHot", Texture = "SeimenMisoHot", Kg = 0.552f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Marutyan", Kcal = 470f, Ru = "Лапша «Марутян Сэймэн Мисо»", En = "Maruchyan Seimen Miso noodles", RuF = "лапша как свежая, бульон на мисо", EnF = "noodles like fresh ones, miso broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "KonKitsune", Kind = Kind.Noodle, RuM = "«Тёмно-синяя лиса»: гречневая соба с жареным тофу. Лисы на пачке нет, тофу она уже унесла.", EnM = "\"Navy Fox\": buckwheat soba with fried tofu. There is no fox on the pack, it has already run off with the tofu.", Mesh = "bowl", Texture = "KonKitsune", Kg = 0.096f, Water = 0.45f, Shape = "bowl", Brand = "Marutyan", Kcal = 420f, Ru = "Лапша «Марутян Кон-но Кицунэ Соба» в миске", En = "Maruchyan Kon no Kitsune Soba bowl", RuF = "гречневая соба с жареным тофу", EnF = "buckwheat soba with fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "KonKitsuneHot", Kind = Kind.Brewed, RuM = "Серая гречневая лапша и сладкий тофу. В Японии собу едят под Новый год, а какой сейчас месяц, вы всё равно не знаете.", EnM = "Grey buckwheat noodles and sweet tofu. In Japan soba is eaten on New Year's Eve, and you do not know what month it is anyway.", Raw = "KonKitsune", Mesh = "bowlHot", Texture = "KonKitsune", Kg = 0.501f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Marutyan", Kcal = 420f, Ru = "Лапша «Марутян Кон-но Кицунэ Соба» в миске", En = "Maruchyan Kon no Kitsune Soba bowl", RuF = "гречневая соба с жареным тофу", EnF = "buckwheat soba with fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "SeimenShio", Kind = Kind.Noodle, RuM = "Солёный бульон и лапша «как свежая». Просто, чисто, без характера. Характер на острове у вас должен быть свой.", EnM = "Salt broth and \"fresh-style\" noodles. Simple, clean, no temper. On the island the temper has to be your own.", Mesh = "jpack2", Texture = "SeimenShio", Kg = 0.106f, Water = 0.5f, Shape = "jpack", Brand = "Marutyan", Kcal = 440f, Ru = "Лапша «Марутян Сэймэн Сио»", En = "Maruchyan Seimen Shio noodles", RuF = "прозрачный солёный бульон", EnF = "a clear salt broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "SeimenShioHot", Kind = Kind.Brewed, RuM = "Прозрачный бульон, в нём видно дно миски. Редкий случай, когда дно на этом острове радует.", EnM = "A clear broth, you can see the bottom of the bowl through it. A rare case of the bottom being good news on this island.", Raw = "SeimenShio", Mesh = "DonburiHot", Texture = "SeimenShioHot", Kg = 0.556f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Marutyan", Kcal = 440f, Ru = "Лапша «Марутян Сэймэн Сио»", En = "Maruchyan Seimen Shio noodles", RuF = "прозрачный солёный бульон", EnF = "a clear salt broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "SeimenTonkotsu", Kind = Kind.Noodle, RuM = "Белый свиной бульон из пакетика. Повар в Фукуоке варит такой двенадцать часов и очень бы обиделся.", EnM = "White pork broth out of a sachet. A cook in Fukuoka simmers his for twelve hours and would be deeply offended.", Mesh = "jpack1", Texture = "SeimenTonkotsu", Kg = 0.104f, Water = 0.5f, Shape = "jpack", Brand = "Marutyan", Kcal = 460f, Ru = "Лапша «Марутян Сэймэн Тонкоцу»", En = "Maruchyan Seimen Tonkotsu noodles", RuF = "белый свиной бульон", EnF = "a white pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "SeimenTonkotsuHot", Kind = Kind.Brewed, RuM = "Белый, как пурга, но тёплый и со вкусом свинины. Пурга бы так не смогла.", EnM = "White as a whiteout, but warm and tasting of pork. A whiteout could never manage that.", Raw = "SeimenTonkotsu", Mesh = "DonburiHot", Texture = "SeimenTonkotsuHot", Kg = 0.554f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Marutyan", Kcal = 460f, Ru = "Лапша «Марутян Сэймэн Тонкоцу»", En = "Maruchyan Seimen Tonkotsu noodles", RuF = "белый свиной бульон", EnF = "a white pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "DonbeiKitsune", Kind = Kind.Noodle, RuM = "Удон с куском тофу такой толщины, что им можно утеплить окно. Но лучше съесть.", EnM = "Udon with a slab of tofu thick enough to insulate a window. Better to eat it though.", Mesh = "bowl", Texture = "DonbeiKitsune", Kg = 0.104f, Water = 0.45f, Shape = "bowl", Brand = "Donbei", Kcal = 420f, Ru = "Удон «Домбэй Кицунэ Удон» в миске", En = "Dombei Kitsune Udon bowl", RuF = "толстый удон с большим куском жареного тофу", EnF = "thick udon with a big piece of fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c9a052" },
        new Def { Id = "DonbeiKitsuneHot", Kind = Kind.Brewed, RuM = "Тофу впитал бульон и стал как губка счастья. Толстый удон лежит под ним и ждёт своей очереди.", EnM = "The tofu has soaked up the broth and become a sponge of happiness. The thick udon lies beneath, waiting its turn.", Raw = "DonbeiKitsune", Mesh = "bowlHot", Texture = "DonbeiKitsune", Kg = 0.509f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Donbei", Kcal = 420f, Ru = "Удон «Домбэй Кицунэ Удон» в миске", En = "Dombei Kitsune Udon bowl", RuF = "толстый удон с большим куском жареного тофу", EnF = "thick udon with a big piece of fried tofu", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c9a052" },
        new Def { Id = "DonbeiSoba", Kind = Kind.Noodle, RuM = "Соба с темпурой. Темпура лежит отдельно, чтобы хрустела. На острове хрустит обычно только наст.", EnM = "Soba with tempura. The tempura comes separately so it stays crisp. On the island the only crisp thing is usually the snow crust.", Mesh = "bowl", Texture = "DonbeiSoba", Kg = 0.1f, Water = 0.45f, Shape = "bowl", Brand = "Donbei", Kcal = 420f, Ru = "Лапша «Домбэй Тэмпура Соба» в миске", En = "Dombei Tempura Soba bowl", RuF = "гречневая соба с хрустящей темпурой", EnF = "buckwheat soba with crisp tempura", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "DonbeiSobaHot", Kind = Kind.Brewed, RuM = "Тёмный бульон, серая лапша, золотая темпура. Три цвета, и ни один из них не белый. Уже праздник.", EnM = "Dark broth, grey noodles, golden tempura. Three colours and none of them white. That is already a celebration.", Raw = "DonbeiSoba", Mesh = "bowlHot", Texture = "DonbeiSoba", Kg = 0.505f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Donbei", Kcal = 420f, Ru = "Лапша «Домбэй Тэмпура Соба» в миске", En = "Dombei Tempura Soba bowl", RuF = "гречневая соба с хрустящей темпурой", EnF = "buckwheat soba with crisp tempura", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#7a4a26" },
        new Def { Id = "UFO", Kind = Kind.Noodle, RuM = "Круглая коробка, похожая на летающую тарелку. После северного сияния тут и не такое находили.", EnM = "A round box shaped like a flying saucer. After the aurora people have found stranger things here.", Mesh = "ufo", Texture = "UFO", Kg = 0.12f, Water = 0.5f, Shape = "ufo", Brand = "UFO", Kcal = 540f, Ru = "Лапша «Ю.Ф.О. Якисоба» в круглой коробке", En = "U.F.O. Yakisoba round box", RuF = "жареная лапша в густом соусе, без бульона", EnF = "fried noodles in a thick sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "UFOHot", Kind = Kind.Brewed, RuM = "Жареная лапша в густом тёмном соусе. Неопознанный, но очень съедобный объект.", EnM = "Fried noodles in a thick dark sauce. An unidentified but very edible object.", Raw = "UFO", Mesh = "ufoHot", Texture = "UFO", Kg = 0.245f, Thirst = -6f, Warm = 0.75f, Shape = "ufo", Brand = "UFO", Kcal = 540f, Ru = "Лапша «Ю.Ф.О. Якисоба» в круглой коробке", En = "U.F.O. Yakisoba round box", RuF = "жареная лапша в густом соусе, без бульона", EnF = "fried noodles in a thick sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "UFOShio", Kind = Kind.Noodle, RuM = "Тарелка с солью и лимоном. Лимон на Великом Медведе звучит так же фантастично, как и НЛО.", EnM = "A saucer with salt and lemon. A lemon on Great Bear sounds about as far-fetched as a UFO.", Mesh = "ufo", Texture = "UFOShio", Kg = 0.116f, Water = 0.5f, Shape = "ufo", Brand = "UFO", Kcal = 540f, Ru = "Лапша «Ю.Ф.О. Сио-якисоба» в круглой коробке", En = "U.F.O. Shio Yakisoba round box", RuF = "жареная лапша с солью и лимоном, без бульона", EnF = "fried noodles with salt and lemon, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d8c890" },
        new Def { Id = "UFOShioHot", Kind = Kind.Brewed, RuM = "Светлая жареная лапша пахнет лимоном. Цинга отступает от одного запаха, хотя врач бы с этим поспорил.", EnM = "Pale fried noodles that smell of lemon. Scurvy backs off from the smell alone, though a doctor would argue.", Raw = "UFOShio", Mesh = "ufoHot", Texture = "UFOShio", Kg = 0.241f, Thirst = -6f, Warm = 0.75f, Shape = "ufo", Brand = "UFO", Kcal = 540f, Ru = "Лапша «Ю.Ф.О. Сио-якисоба» в круглой коробке", En = "U.F.O. Shio Yakisoba round box", RuF = "жареная лапша с солью и лимоном, без бульона", EnF = "fried noodles with salt and lemon, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d8c890" },
        new Def { Id = "Peyangu", Kind = Kind.Noodle, RuM = "Квадратная коробка, придуманная, чтобы есть вдвоём. Название от слова «пара». Пары у вас нет, зато порция вся ваша.", EnM = "A square box invented for eating together. The name comes from \"pair\". You have no pair, but the whole helping is yours.", Mesh = "box", Texture = "Peyangu", Kg = 0.129f, Water = 0.5f, Shape = "box", Brand = "Peyangu", Kcal = 590f, Ru = "Лапша «Пеянгу Якисоба» в коробке", En = "Peyangu Yakisoba box", RuF = "жареная лапша с соусом, без бульона", EnF = "fried noodles with sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "PeyanguHot", Kind = Kind.Brewed, RuM = "Якисоба с соусом, лежит ровным квадратом. Единственная прямоугольная вещь на острове, которая не дверь и не кровать.", EnM = "Yakisoba with sauce, lying in a neat square. The only rectangular thing on the island that is neither a door nor a bed.", Raw = "Peyangu", Mesh = "PlateHot", Texture = "PeyanguHot", Kg = 0.254f, Thirst = -6f, Warm = 0.75f, Shape = "box", Brand = "Peyangu", Kcal = 590f, Ru = "Лапша «Пеянгу Якисоба» в коробке", En = "Peyangu Yakisoba box", RuF = "жареная лапша с соусом, без бульона", EnF = "fried noodles with sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "PeyanguHell", Kind = Kind.Noodle, RuM = "На коробке честно написано «экстремально острая». Японцы обычно преуменьшают, так что готовьте снег.", EnM = "The box honestly says \"extremely hot\". The Japanese usually understate, so get the snow ready.", Mesh = "box", Texture = "PeyanguHell", Kg = 0.133f, Water = 0.5f, Shape = "box", Brand = "Peyangu", Kcal = 530f, Ru = "Лапша «Пеянгу Гоку-гэки-кара» в коробке", En = "Peyangu Goku Geki Kara box", RuF = "адски острая якисоба, без бульона", EnF = "hellishly hot yakisoba, no broth", Spicy = 4, Dry = true, Fx = "appetite heartburn tears", Broth = "#6a1208" },
        new Def { Id = "PeyanguHellHot", Kind = Kind.Brewed, RuM = "Адская якисоба. Мороз щиплет снаружи, она изнутри, а вы посередине и уже не понимаете, кому жаловаться.", EnM = "Yakisoba from hell. The frost nips from outside, this from inside, and you are in the middle with no idea whom to complain to.", Raw = "PeyanguHell", Mesh = "PlateHot", Texture = "PeyanguHellHot", Kg = 0.258f, Thirst = -14f, Warm = 1.95f, Shape = "box", Brand = "Peyangu", Kcal = 530f, Ru = "Лапша «Пеянгу Гоку-гэки-кара» в коробке", En = "Peyangu Goku Geki Kara box", RuF = "адски острая якисоба, без бульона", EnF = "hellishly hot yakisoba, no broth", Spicy = 4, Dry = true, Fx = "appetite heartburn tears", Broth = "#6a1208" },
        new Def { Id = "Yomise", Kind = Kind.Noodle, RuM = "«Якисоба с ночной ярмарки». Ночь на острове есть, ярмарки нет, зато есть пакетик горчичного майонеза.", EnM = "\"Night market yakisoba\". The island has the night, it lacks the market, but there is a sachet of mustard mayo.", Mesh = "box", Texture = "Yomise", Kg = 0.135f, Water = 0.5f, Shape = "box", Brand = "Peyangu", Kcal = 550f, Ru = "Лапша «Иппэй-тян Ёмисэ-но Якисоба» в коробке", En = "Ippei-chan Yomise no Yakisoba box", RuF = "якисоба с ярмарки, с горчичным майонезом, без бульона", EnF = "festival-stall yakisoba with mustard mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "YomiseHot", Kind = Kind.Brewed, RuM = "Лапша под жёлтой сеткой майонеза. Закройте глаза: фонарики, толпа, музыка. Откройте: фонарь, и в нём кончается керосин.", EnM = "Noodles under a yellow net of mayo. Close your eyes: paper lanterns, crowds, music. Open them: one lantern, running out of kerosene.", Raw = "Yomise", Mesh = "PlateHot", Texture = "YomiseHot", Kg = 0.26f, Thirst = -6f, Warm = 0.75f, Shape = "box", Brand = "Peyangu", Kcal = 550f, Ru = "Лапша «Иппэй-тян Ёмисэ-но Якисоба» в коробке", En = "Ippei-chan Yomise no Yakisoba box", RuF = "якисоба с ярмарки, с горчичным майонезом, без бульона", EnF = "festival-stall yakisoba with mustard mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "DemaeSesame", Kind = Kind.Noodle, RuM = "На пачке мальчик-разносчик несёт лапшу. До Великого Медведя он не дошёл, пачка добралась сама.", EnM = "On the pack a delivery boy carries noodles. He never made it to Great Bear, the pack got here by itself.", Mesh = "jpack1", Texture = "DemaeSesame", Kg = 0.099f, Water = 0.5f, Shape = "jpack", Brand = "Demae", Kcal = 430f, Ru = "Лапша «Демаэ Иттё Кунжутное масло»", En = "Demae Itcho Sesame Oil noodles", RuF = "соевый бульон с кунжутным маслом", EnF = "soy broth with sesame oil", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "DemaeSesameHot", Kind = Kind.Brewed, RuM = "Соевый бульон с каплей кунжутного масла. Пахнет так, будто доставка всё-таки приехала.", EnM = "Soy broth with a drop of sesame oil. It smells as if the delivery did arrive after all.", Raw = "DemaeSesame", Mesh = "DonburiHot", Texture = "DemaeSesameHot", Kg = 0.549f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Demae", Kcal = 430f, Ru = "Лапша «Демаэ Иттё Кунжутное масло»", En = "Demae Itcho Sesame Oil noodles", RuF = "соевый бульон с кунжутным маслом", EnF = "soy broth with sesame oil", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "DemaeTonkotsu", Kind = Kind.Noodle, RuM = "Свиной бульон от мальчика с пачки. Он улыбается уже полвека, ему легко, он не на острове.", EnM = "Pork broth from the boy on the pack. He has been smiling for half a century, easy for him, he is not on the island.", Mesh = "jpack2", Texture = "DemaeTonkotsu", Kg = 0.099f, Water = 0.5f, Shape = "jpack", Brand = "Demae", Kcal = 410f, Ru = "Лапша «Демаэ Иттё Тонкоцу»", En = "Demae Itcho Tonkotsu noodles", RuF = "свиной бульон", EnF = "pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "DemaeTonkotsuHot", Kind = Kind.Brewed, RuM = "Белый бульон, жирные капли сверху. Жир на морозе ценится выше золота, а тут он ещё и вкусный.", EnM = "White broth with drops of fat on top. In the cold fat is worth more than gold, and here it is tasty too.", Raw = "DemaeTonkotsu", Mesh = "DonburiHot", Texture = "DemaeTonkotsuHot", Kg = 0.549f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Demae", Kcal = 410f, Ru = "Лапша «Демаэ Иттё Тонкоцу»", En = "Demae Itcho Tonkotsu noodles", RuF = "свиной бульон", EnF = "pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "DemaeMayu", Kind = Kind.Noodle, RuM = "Свиной бульон с маслом жжёного чеснока. Жжёное на острове обычно значит беду, но не в этот раз.", EnM = "Pork broth with burnt garlic oil. On the island burnt usually means trouble, but not this time.", Mesh = "jpack2", Texture = "DemaeMayu", Kg = 0.105f, Water = 0.5f, Shape = "jpack", Brand = "Demae", Kcal = 460f, Ru = "Лапша «Демаэ Иттё Чёрный чеснок»", En = "Demae Itcho Black Garlic noodles", RuF = "свиной бульон с маслом жжёного чеснока", EnF = "pork broth with burnt garlic oil", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8a488" },
        new Def { Id = "DemaeMayuHot", Kind = Kind.Brewed, RuM = "Чёрные капли масла на белом бульоне. Как следы на свежем снегу, только эти ведут к ужину.", EnM = "Black drops of oil on white broth. Like tracks on fresh snow, only these lead to dinner.", Raw = "DemaeMayu", Mesh = "DonburiHot", Texture = "DemaeMayuHot", Kg = 0.555f, Thirst = 21f, Warm = 1.4f, Shape = "jpack", Brand = "Demae", Kcal = 460f, Ru = "Лапша «Демаэ Иттё Чёрный чеснок»", En = "Demae Itcho Black Garlic noodles", RuF = "свиной бульон с маслом жжёного чеснока", EnF = "pork broth with burnt garlic oil", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8a488" },
        new Def { Id = "DemaeSeafood", Kind = Kind.Noodle, RuM = "Морепродукты в пачке. Ближе к живой креветке вы на этом острове уже не подберётесь.", EnM = "Seafood in a pack. This is as close to a live shrimp as you will ever get on this island.", Mesh = "jpack0", Texture = "DemaeSeafood", Kg = 0.098f, Water = 0.5f, Shape = "jpack", Brand = "Demae", Kcal = 440f, Ru = "Лапша «Демаэ Иттё Морепродукты»", En = "Demae Itcho Seafood noodles", RuF = "бульон с морепродуктами", EnF = "seafood broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "DemaeSeafoodHot", Kind = Kind.Brewed, RuM = "Бульон пахнет портом, из которого больше не выходят корабли. Зато креветки в нём не сушёные, а почти настоящие.", EnM = "The broth smells of a harbour the ships no longer leave. But the shrimp in it are not dried, they are almost real.", Raw = "DemaeSeafood", Mesh = "DonburiHot", Texture = "DemaeSeafoodHot", Kg = 0.548f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Demae", Kcal = 440f, Ru = "Лапша «Демаэ Иттё Морепродукты»", En = "Demae Itcho Seafood noodles", RuF = "бульон с морепродуктами", EnF = "seafood broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "DemaeSpicy", Kind = Kind.Noodle, RuM = "Мальчик-разносчик в красном. Когда он в красном, улыбка у него та же, а вот у вас будет другая.", EnM = "The delivery boy in red. In red his smile is the same, yours will be different.", Mesh = "jpack2", Texture = "DemaeSpicy", Kg = 0.102f, Water = 0.5f, Shape = "jpack", Brand = "Demae", Kcal = 470f, Ru = "Лапша «Демаэ Иттё Острый»", En = "Demae Itcho Spicy noodles", RuF = "острый соевый бульон", EnF = "a spicy soy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "DemaeSpicyHot", Kind = Kind.Brewed, RuM = "Острый соевый бульон. Пот на лбу, пар из носа. Главное, не выходить после этого на ветер.", EnM = "Spicy soy broth. Sweat on the brow, steam from the nose. The main thing is not to step into the wind afterwards.", Raw = "DemaeSpicy", Mesh = "DonburiHot", Texture = "DemaeSpicyHot", Kg = 0.552f, Thirst = 18f, Warm = 1.8f, Shape = "jpack", Brand = "Demae", Kcal = 470f, Ru = "Лапша «Демаэ Иттё Острый»", En = "Demae Itcho Spicy noodles", RuF = "острый соевый бульон", EnF = "a spicy soy broth", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "CharumeraShoyu", Kind = Kind.Noodle, RuM = "На пачке старик с тележкой и дудочкой. Раньше так по ночам продавали лапшу; услышав дудочку на острове, бегите.", EnM = "On the pack an old man with a cart and a flute. Noodles used to be sold that way at night; if you hear a flute on the island, run.", Mesh = "jpack2", Texture = "CharumeraShoyu", Kg = 0.096f, Water = 0.5f, Shape = "jpack", Brand = "Charumera", Kcal = 440f, Ru = "Лапша «Тярумэра Сёю»", En = "Charumera Shoyu noodles", RuF = "соевый бульон как в уличной лапшичной", EnF = "soy broth as at a street noodle cart", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "CharumeraShoyuHot", Kind = Kind.Brewed, RuM = "Соевый бульон как из уличной тележки. Тёмный, горячий, с перцем. Полночь, мороз, и вы сами себе лапшичник.", EnM = "Soy broth as if from a street cart. Dark, hot, peppery. Midnight, frost, and you are your own noodle man.", Raw = "CharumeraShoyu", Mesh = "DonburiHot", Texture = "CharumeraShoyuHot", Kg = 0.546f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Charumera", Kcal = 440f, Ru = "Лапша «Тярумэра Сёю»", En = "Charumera Shoyu noodles", RuF = "соевый бульон как в уличной лапшичной", EnF = "soy broth as at a street noodle cart", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "CharumeraMiso", Kind = Kind.Noodle, RuM = "Мисо от старика с тележкой. Он кормит ночных прохожих с шестьдесят шестого года, прохожих тут только нет.", EnM = "Miso from the old man with the cart. He has fed night passers-by since sixty-six, there are just no passers-by here.", Mesh = "jpack0", Texture = "CharumeraMiso", Kg = 0.096f, Water = 0.5f, Shape = "jpack", Brand = "Charumera", Kcal = 450f, Ru = "Лапша «Тярумэра Мисо»", En = "Charumera Miso noodles", RuF = "бульон на мисо как в уличной лапшичной", EnF = "miso broth as at a street noodle cart", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "CharumeraMisoHot", Kind = Kind.Brewed, RuM = "Густое мисо со специями из отдельного пакетика. Пакетик маленький, а радости от него на целый вечер.", EnM = "Thick miso with spices from a separate sachet. The sachet is small, the joy lasts all evening.", Raw = "CharumeraMiso", Mesh = "DonburiHot", Texture = "CharumeraMisoHot", Kg = 0.546f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Charumera", Kcal = 450f, Ru = "Лапша «Тярумэра Мисо»", En = "Charumera Miso noodles", RuF = "бульон на мисо как в уличной лапшичной", EnF = "miso broth as at a street noodle cart", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "HakataTonkotsu", Kind = Kind.Noodle, RuM = "Прямая лапша палочками, как спагетти. Лежит в пачке ровно, как дрова в поленнице у аккуратного хозяина.", EnM = "Straight noodles in sticks, like spaghetti. They lie in the pack as neatly as logs in a tidy owner's woodpile.", Mesh = "long1", Texture = "HakataTonkotsu", Kg = 0.088f, Water = 0.45f, Shape = "long", Brand = "Hakata", Kcal = 330f, Ru = "Лапша «Хаката Бо-рамен Тонкоцу»", En = "Hakata Bo-Ramen Tonkotsu noodles", RuF = "прямая тонкая лапша, свиной бульон", EnF = "straight thin noodles, pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "HakataTonkotsuHot", Kind = Kind.Brewed, RuM = "Тонкая прямая лапша в свином бульоне. В Хакате просят добавку лапши криком. Здесь кричать не надо, услышат не те.", EnM = "Thin straight noodles in pork broth. In Hakata you shout for a refill of noodles. Do not shout here, the wrong ones will hear.", Raw = "HakataTonkotsu", Mesh = "DonburiHot", Texture = "HakataTonkotsuHot", Kg = 0.493f, Thirst = 24f, Warm = 1.0f, Shape = "long", Brand = "Hakata", Kcal = 330f, Ru = "Лапша «Хаката Бо-рамен Тонкоцу»", En = "Hakata Bo-Ramen Tonkotsu noodles", RuF = "прямая тонкая лапша, свиной бульон", EnF = "straight thin noodles, pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "HakataMayu", Kind = Kind.Noodle, RuM = "Прямая лапша и чёрное чесночное масло из Кумамото. На гербе тех мест медведь. Совпадение, но неприятное.", EnM = "Straight noodles and black garlic oil from Kumamoto. The mascot of that region is a bear. A coincidence, but an uneasy one.", Mesh = "long0", Texture = "HakataMayu", Kg = 0.091f, Water = 0.45f, Shape = "long", Brand = "Hakata", Kcal = 320f, Ru = "Лапша «Хаката Бо-рамен Кумамото»", En = "Hakata Bo-Ramen Kumamoto noodles", RuF = "прямая лапша, свиной бульон с чёрным чесноком", EnF = "straight noodles, pork broth with black garlic", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8a488" },
        new Def { Id = "HakataMayuHot", Kind = Kind.Brewed, RuM = "Белый бульон под чёрной плёнкой чеснока. Вампиров на острове и так нет, теперь не будет точно.", EnM = "White broth under a black film of garlic. The island had no vampires anyway, now it certainly never will.", Raw = "HakataMayu", Mesh = "DonburiHot", Texture = "HakataMayuHot", Kg = 0.496f, Thirst = 21f, Warm = 1.4f, Shape = "long", Brand = "Hakata", Kcal = 320f, Ru = "Лапша «Хаката Бо-рамен Кумамото»", En = "Hakata Bo-Ramen Kumamoto noodles", RuF = "прямая лапша, свиной бульон с чёрным чесноком", EnF = "straight noodles, pork broth with black garlic", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8a488" },
        new Def { Id = "RaoMiso", Kind = Kind.Noodle, RuM = "«Король рамена», миска почти ресторанная. Ресторан ближайший в трёхстах километрах и закрыт навсегда.", EnM = "\"The King of Ramen\", a nearly restaurant bowl. The nearest restaurant is three hundred kilometres away and closed forever.", Mesh = "bowl", Texture = "RaoMiso", Kg = 0.1f, Water = 0.45f, Shape = "bowl", Brand = "Rao", Kcal = 450f, Ru = "Лапша «Ра-О Мисо» в миске", En = "Ra-O Miso bowl", RuF = "ресторанный рамен: густое мисо", EnF = "restaurant-style ramen: a rich miso", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "RaoMisoHot", Kind = Kind.Brewed, RuM = "Густое мисо, лапша как у повара. Чаевые оставлять некому, поэтому просто вымойте котелок.", EnM = "Thick miso, noodles as a chef would make them. There is nobody to tip, so just wash the pot.", Raw = "RaoMiso", Mesh = "bowlHot", Texture = "RaoMiso", Kg = 0.505f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Rao", Kcal = 450f, Ru = "Лапша «Ра-О Мисо» в миске", En = "Ra-O Miso bowl", RuF = "ресторанный рамен: густое мисо", EnF = "restaurant-style ramen: a rich miso", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "RaoTonkotsu", Kind = Kind.Noodle, RuM = "Ресторанный свиной бульон в миске. На крышке золотые буквы, и они заслужены.", EnM = "Restaurant pork broth in a bowl. Golden letters on the lid, and well earned.", Mesh = "bowl", Texture = "RaoTonkotsu", Kg = 0.105f, Water = 0.45f, Shape = "bowl", Brand = "Rao", Kcal = 410f, Ru = "Лапша «Ра-О Тонкоцу» в миске", En = "Ra-O Tonkotsu bowl", RuF = "ресторанный рамен: свиной бульон", EnF = "restaurant-style ramen: pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "RaoTonkotsuHot", Kind = Kind.Brewed, RuM = "Бульон густой, как сливки. Для полного счастья не хватает только официанта, тепла, света и цивилизации.", EnM = "The broth is thick as cream. All that is missing for perfect happiness is a waiter, warmth, light and civilisation.", Raw = "RaoTonkotsu", Mesh = "bowlHot", Texture = "RaoTonkotsu", Kg = 0.51f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Rao", Kcal = 410f, Ru = "Лапша «Ра-О Тонкоцу» в миске", En = "Ra-O Tonkotsu bowl", RuF = "ресторанный рамен: свиной бульон", EnF = "restaurant-style ramen: pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "RaoShoyu", Kind = Kind.Noodle, RuM = "Соевый рамен «как в ресторане». Дресс-кода нет: можно в волчьей шубе и в двух шапках.", EnM = "Soy ramen \"restaurant style\". No dress code: a wolfskin coat and two hats are fine.", Mesh = "bowl", Texture = "RaoShoyu", Kg = 0.1f, Water = 0.45f, Shape = "bowl", Brand = "Rao", Kcal = 410f, Ru = "Лапша «Ра-О Сёю» в миске", En = "Ra-O Shoyu bowl", RuF = "ресторанный рамен: соевый бульон", EnF = "restaurant-style ramen: soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "RaoShoyuHot", Kind = Kind.Brewed, RuM = "Тёмный бульон с блёстками жира, упругая лапша. За такой в Токио стоят в очереди, а вы тут один на весь регион.", EnM = "Dark broth glinting with fat, springy noodles. In Tokyo they queue for this, and you are alone in the whole region.", Raw = "RaoShoyu", Mesh = "bowlHot", Texture = "RaoShoyu", Kg = 0.505f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Rao", Kcal = 410f, Ru = "Лапша «Ра-О Сёю» в миске", En = "Ra-O Shoyu bowl", RuF = "ресторанный рамен: соевый бульон", EnF = "restaurant-style ramen: soy broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#8a5a2b" },
        new Def { Id = "Ichiran", Kind = Kind.Noodle, RuM = "Подарочная коробка из лапшичной, где едят в отдельных кабинках, чтобы никто не мешал. На острове кабинка размером с остров.", EnM = "A gift box from the noodle shop where you eat in a private booth so nobody bothers you. On the island the booth is the size of the island.", Mesh = "box", Texture = "Ichiran", Kg = 0.126f, Water = 0.5f, Shape = "box", Brand = "Ichiran", Kcal = 560f, Ru = "Лапша «Итиран Тонкоцу» в коробке", En = "Ichiran Tonkotsu box", RuF = "подарочная коробка: свиной бульон с красным соусом", EnF = "a gift box: pork broth with a red sauce", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "IchiranHot", Kind = Kind.Brewed, RuM = "Свиной бульон с красной каплей острого соуса посередине. Размешивать или нет, решайте сами: советчиков тут нет.", EnM = "Pork broth with a red drop of hot sauce in the middle. To stir or not is up to you: there are no advisers here.", Raw = "Ichiran", Mesh = "DonburiHot", Texture = "IchiranHot", Kg = 0.576f, Thirst = 21f, Warm = 1.4f, Shape = "box", Brand = "Ichiran", Kcal = 560f, Ru = "Лапша «Итиран Тонкоцу» в коробке", En = "Ichiran Tonkotsu box", RuF = "подарочная коробка: свиной бульон с красным соусом", EnF = "a gift box: pork broth with a red sauce", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "Rolltan", Kind = Kind.Noodle, RuM = "Пачка из детства, общежития и поезда. Как она попала на канадский остров, вопрос к геомагнитной буре.", EnM = "A pack from childhood, the dorm and the long-distance train. How it reached a Canadian island is a question for the geomagnetic storm.", Mesh = "brick1", Texture = "Rolltan", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Rolltan", Kcal = 390f, Ru = "Лапша «Роллтан»", En = "Rolltan noodles", RuF = "по-домашнему, с курицей", EnF = "home-style chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "RolltanHot", Kind = Kind.Brewed, RuM = "Жёлтый бульон «по-домашнему». Дома так никто не готовил, но в хижине у озера сойдёт за мамин суп.", EnM = "A yellow \"home-style\" broth. Nobody ever cooked like this at home, but in a cabin by the lake it passes for mum's soup.", Raw = "Rolltan", Mesh = "BowlHot", Texture = "RolltanHot", Kg = 0.445f, Thirst = 22f, Warm = 1.0f, Shape = "brick", Brand = "Rolltan", Kcal = 390f, Ru = "Лапша «Роллтан»", En = "Rolltan noodles", RuF = "по-домашнему, с курицей", EnF = "home-style chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "RolltanBeef", Kind = Kind.Noodle, RuM = "Говядина на пачке нарисована красиво. Внутри её представляет пакетик порошка, и он старается.", EnM = "The beef on the pack is drawn beautifully. Inside it is represented by a sachet of powder, and it does its best.", Mesh = "brick1", Texture = "RolltanBeef", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "Rolltan", Kcal = 400f, Ru = "Лапша «Роллтан Говядина»", En = "Rolltan Beef noodles", RuF = "с говядиной", EnF = "beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "RolltanBeefHot", Kind = Kind.Brewed, RuM = "Коричневый бульон, кудрявая лапша. Оленина у вас в рюкзаке настоящая, а тянет почему-то на эту.", EnM = "Brown broth, curly noodles. The venison in your pack is real, yet somehow it is this you crave.", Raw = "RolltanBeef", Mesh = "BowlHot", Texture = "RolltanBeefHot", Kg = 0.448f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Rolltan", Kcal = 400f, Ru = "Лапша «Роллтан Говядина»", En = "Rolltan Beef noodles", RuF = "с говядиной", EnF = "beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "RolltanMushroom", Kind = Kind.Noodle, RuM = "Грибная. Грибы на острове растут на деревьях и годятся на чай, эти годятся на суп.", EnM = "Mushroom flavour. The island's mushrooms grow on trees and go into tea, these go into soup.", Mesh = "brick2", Texture = "RolltanMushroom", Kg = 0.082f, Water = 0.4f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Грибы»", En = "Rolltan Mushroom noodles", RuF = "с грибами", EnF = "mushroom", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b58a55" },
        new Def { Id = "RolltanMushroomHot", Kind = Kind.Brewed, RuM = "Пахнет грибами и лесом, каким он был до всего этого. Тёплым, осенним и без волков за каждым кустом.", EnM = "It smells of mushrooms and of the forest as it was before all this. Warm, autumnal and with no wolf behind every bush.", Raw = "RolltanMushroom", Mesh = "BowlHot", Texture = "RolltanMushroomHot", Kg = 0.442f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Грибы»", En = "Rolltan Mushroom noodles", RuF = "с грибами", EnF = "mushroom", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b58a55" },
        new Def { Id = "RolltanBacon", Kind = Kind.Noodle, RuM = "Бекон и сыр, оба в виде порошка. Химия, конечно, но химия тёплая и на вашей стороне.", EnM = "Bacon and cheese, both as powder. Chemistry, of course, but warm chemistry that is on your side.", Mesh = "brick0", Texture = "RolltanBacon", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Бекон и сыр»", En = "Rolltan Bacon & Cheese noodles", RuF = "со вкусом бекона и сыра", EnF = "bacon and cheese flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e0a040" },
        new Def { Id = "RolltanBaconHot", Kind = Kind.Brewed, RuM = "Бульон пахнет беконом так убедительно, что из-под крыльца выглянул кто-то серый. Дверь лучше прикрыть.", EnM = "The broth smells of bacon so convincingly that something grey peeked from under the porch. Better shut the door.", Raw = "RolltanBacon", Mesh = "BowlHot", Texture = "RolltanBaconHot", Kg = 0.448f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Бекон и сыр»", En = "Rolltan Bacon & Cheese noodles", RuF = "со вкусом бекона и сыра", EnF = "bacon and cheese flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e0a040" },
        new Def { Id = "RolltanSpicy", Kind = Kind.Noodle, RuM = "Острая курица. По меркам корейских соседей по полке это детский утренник, но вам хватит.", EnM = "Spicy chicken. By the standards of its Korean shelf neighbours this is a children's party, but it will do for you.", Mesh = "brick1", Texture = "RolltanSpicy", Kg = 0.08f, Water = 0.4f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Острая курица»", En = "Rolltan Hot Chicken noodles", RuF = "с курицей и перцем", EnF = "chicken with pepper", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#c4381c" },
        new Def { Id = "RolltanSpicyHot", Kind = Kind.Brewed, RuM = "Куриный бульон с красными точками перца. Щёки розовеют, нос оттаивает, жить опять можно.", EnM = "Chicken broth with red specks of pepper. Cheeks go pink, the nose thaws, life is possible again.", Raw = "RolltanSpicy", Mesh = "BowlHot", Texture = "RolltanSpicyHot", Kg = 0.44f, Thirst = 21f, Warm = 1.4f, Shape = "brick", Brand = "Rolltan", Kcal = 370f, Ru = "Лапша «Роллтан Острая курица»", En = "Rolltan Hot Chicken noodles", RuF = "с курицей и перцем", EnF = "chicken with pepper", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#c4381c" },
        new Def { Id = "Mivinka", Kind = Kind.Noodle, RuM = "Её можно грызть сухой прямо из пачки. Половина страны так и делала, вторая половина врёт, что нет.", EnM = "You can crunch it dry straight from the pack. Half the country did just that, the other half lies that it did not.", Mesh = "brick1", Texture = "Mivinka", Kg = 0.06f, Water = 0.35f, Shape = "brick", Brand = "Mivinka", Kcal = 300f, Ru = "Лапша «Мивинка»", En = "Mivinka noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "MivinkaHot", Kind = Kind.Brewed, RuM = "Лапша разварилась, бульон коричневый. Вкус девяностых, которые тоже были своего рода выживанием.", EnM = "The noodles have gone soft, the broth is brown. The taste of the nineties, which were survival of a kind too.", Raw = "Mivinka", Mesh = "BowlHot", Texture = "MivinkaHot", Kg = 0.375f, Thirst = 20f, Warm = 1.0f, Shape = "brick", Brand = "Mivinka", Kcal = 300f, Ru = "Лапша «Мивинка»", En = "Mivinka noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "MivinkaChicken", Kind = Kind.Noodle, RuM = "Куриная. Пакетик приправы внутри ценнее самой лапши: им можно спасти любую оленину.", EnM = "Chicken flavour. The seasoning sachet inside is worth more than the noodles: it can rescue any venison.", Mesh = "mini2", Texture = "MivinkaChicken", Kg = 0.057f, Water = 0.35f, Shape = "mini", Brand = "Mivinka", Kcal = 300f, Ru = "Лапша «Мивинка Курица»", En = "Mivinka Chicken noodles", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "MivinkaChickenHot", Kind = Kind.Brewed, RuM = "Жёлтый бульон и мелкая кудрявая лапша. Едят её быстро, пока горячая и пока никто не пришёл на запах.", EnM = "Yellow broth and small curly noodles. Eat it fast, while it is hot and before anyone follows the smell.", Raw = "MivinkaChicken", Mesh = "BowlHot", Texture = "MivinkaChickenHot", Kg = 0.372f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Mivinka", Kcal = 300f, Ru = "Лапша «Мивинка Курица»", En = "Mivinka Chicken noodles", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "MivinkaShrimp", Kind = Kind.Noodle, RuM = "Со вкусом креветок. Креветок при её создании никто не беспокоил.", EnM = "Shrimp flavour. No shrimp were troubled in the making of it.", Mesh = "mini0", Texture = "MivinkaShrimp", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Mivinka", Kcal = 290f, Ru = "Лапша «Мивинка Креветка»", En = "Mivinka Shrimp noodles", RuF = "со вкусом креветок", EnF = "shrimp flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "MivinkaShrimpHot", Kind = Kind.Brewed, RuM = "Розоватый бульон пахнет морем из пакетика. Настоящее море замёрзло, так что это сейчас главное в округе.", EnM = "A pinkish broth that smells of sea from a sachet. The real sea is frozen, so this is now the main one around.", Raw = "MivinkaShrimp", Mesh = "BowlHot", Texture = "MivinkaShrimpHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Mivinka", Kcal = 290f, Ru = "Лапша «Мивинка Креветка»", En = "Mivinka Shrimp noodles", RuF = "со вкусом креветок", EnF = "shrimp flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "MivinkaSpicy", Kind = Kind.Noodle, RuM = "Острая говядина. Красный пакетик сыпать весь или половину, каждый решает сам и потом винит себя.", EnM = "Spicy beef. Whether to pour in the whole red sachet or half is for each to decide and then to blame themselves.", Mesh = "mini2", Texture = "MivinkaSpicy", Kg = 0.057f, Water = 0.35f, Shape = "mini", Brand = "Mivinka", Kcal = 280f, Ru = "Лапша «Мивинка Острая»", En = "Mivinka Hot noodles", RuF = "острая, со вкусом говядины", EnF = "hot, beef flavour", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c4381c" },
        new Def { Id = "MivinkaSpicyHot", Kind = Kind.Brewed, RuM = "Бульон с красным маслом, лапша мелкой волной. Согревает быстро, как глоток из фляжки, только голова ясная.", EnM = "Broth with red oil, noodles in small waves. It warms as fast as a swig from a flask, only your head stays clear.", Raw = "MivinkaSpicy", Mesh = "BowlHot", Texture = "MivinkaSpicyHot", Kg = 0.372f, Thirst = 21f, Warm = 1.4f, Shape = "mini", Brand = "Mivinka", Kcal = 280f, Ru = "Лапша «Мивинка Острая»", En = "Mivinka Hot noodles", RuF = "острая, со вкусом говядины", EnF = "hot, beef flavour", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c4381c" },
        new Def { Id = "MivinkaCheese", Kind = Kind.Noodle, RuM = "Сыр и зелень. Зелень сушёная, сыр условный, настроение настоящее.", EnM = "Cheese and herbs. The herbs are dried, the cheese is notional, the mood is real.", Mesh = "mini2", Texture = "MivinkaCheese", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Mivinka", Kcal = 270f, Ru = "Лапша «Мивинка Сыр и зелень»", En = "Mivinka Cheese & Herbs noodles", RuF = "со вкусом сыра и зелени", EnF = "cheese and herbs flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e8c060" },
        new Def { Id = "MivinkaCheeseHot", Kind = Kind.Brewed, RuM = "Светлый бульон с зелёными крапинками. Единственная зелень на острове, если не считать хвою и ваше лицо после сырой рыбы.", EnM = "Pale broth with green flecks. The only greens on the island, not counting pine needles and your face after raw fish.", Raw = "MivinkaCheese", Mesh = "BowlHot", Texture = "MivinkaCheeseHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Mivinka", Kcal = 270f, Ru = "Лапша «Мивинка Сыр и зелень»", En = "Mivinka Cheese & Herbs noodles", RuF = "со вкусом сыра и зелени", EnF = "cheese and herbs flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e8c060" },
        new Def { Id = "Doshik", Kind = Kind.Noodle, RuM = "Лоток, из которого ела вся Транссибирская магистраль. Рельсы на острове тоже есть, не хватает только проводницы с кипятком.", EnM = "The tray the whole Trans-Siberian Railway ate from. The island has rails too, all it lacks is the attendant with boiling water.", Mesh = "tray", Texture = "Doshik", Kg = 0.1f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 430f, Ru = "Лапша «Дошик» в лотке", En = "Doshik noodle tray", RuF = "говядина", EnF = "beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b5642c" },
        new Def { Id = "DoshikHot", Kind = Kind.Brewed, RuM = "Лоток с говяжьим бульоном. В пустом лотке потом удобно хранить рыболовные крючки. Проверено поколениями.", EnM = "A tray of beef broth. The empty tray is handy for keeping fish hooks afterwards. Proven by generations.", Raw = "Doshik", Mesh = "BowlHot", Texture = "DoshikHot", Kg = 0.55f, Thirst = 24f, Warm = 1.1f, Shape = "tray", Brand = "Doshik", Kcal = 430f, Ru = "Лапша «Дошик» в лотке", En = "Doshik noodle tray", RuF = "говядина", EnF = "beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b5642c" },
        new Def { Id = "DoshikChicken", Kind = Kind.Noodle, RuM = "Куриный, в том самом лотке с крышкой. Вилка пластиковая в комплекте: первый столовый прибор за месяц.", EnM = "Chicken flavour, in that same tray with a lid. A plastic fork is included: your first piece of cutlery in a month.", Mesh = "tray", Texture = "DoshikChicken", Kg = 0.094f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Курица» в лотке", En = "Doshik Chicken tray", RuF = "курица", EnF = "chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "DoshikChickenHot", Kind = Kind.Brewed, RuM = "Куриный бульон в прямоугольном лотке. Форма странная, зато не опрокинется, когда хижину тряхнёт ветром.", EnM = "Chicken broth in a rectangular tray. An odd shape, but it will not tip over when the wind shakes the cabin.", Raw = "DoshikChicken", Mesh = "BowlHot", Texture = "DoshikChickenHot", Kg = 0.544f, Thirst = 24f, Warm = 1.0f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Курица» в лотке", En = "Doshik Chicken tray", RuF = "курица", EnF = "chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "DoshikPork", Kind = Kind.Noodle, RuM = "Свинина. Самая сытная в семье, её берут те, кому завтра идти через перевал.", EnM = "Pork. The most filling of the family, taken by those who cross the pass tomorrow.", Mesh = "tray", Texture = "DoshikPork", Kg = 0.089f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Свинина» в лотке", En = "Doshik Pork tray", RuF = "свинина", EnF = "pork", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c98050" },
        new Def { Id = "DoshikPorkHot", Kind = Kind.Brewed, RuM = "Жирный свиной бульон. Ложка, две, три, и рыбацкая будка уже кажется купе с видом на тайгу.", EnM = "Rich pork broth. One spoonful, two, three, and the fishing hut already feels like a train compartment with a taiga view.", Raw = "DoshikPork", Mesh = "BowlHot", Texture = "DoshikPorkHot", Kg = 0.539f, Thirst = 24f, Warm = 1.0f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Свинина» в лотке", En = "Doshik Pork tray", RuF = "свинина", EnF = "pork", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c98050" },
        new Def { Id = "DoshikMushroom", Kind = Kind.Noodle, RuM = "Грибной. Пахнет так, будто кто-то в соседнем купе открыл банку бабушкиных грибов.", EnM = "Mushroom flavour. It smells as if someone in the next compartment opened a jar of granny's mushrooms.", Mesh = "tray", Texture = "DoshikMushroom", Kg = 0.09f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Грибы» в лотке", En = "Doshik Mushroom tray", RuF = "грибы", EnF = "mushroom", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b58a55" },
        new Def { Id = "DoshikMushroomHot", Kind = Kind.Brewed, RuM = "Грибной бульон в лотке. За окном тоже темно и лес, только поезд никуда не едет, а вы никуда не торопитесь.", EnM = "Mushroom broth in a tray. Outside it is also dark and wooded, only the train is going nowhere and you are in no hurry.", Raw = "DoshikMushroom", Mesh = "BowlHot", Texture = "DoshikMushroomHot", Kg = 0.54f, Thirst = 24f, Warm = 1.0f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Грибы» в лотке", En = "Doshik Mushroom tray", RuF = "грибы", EnF = "mushroom", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b58a55" },
        new Def { Id = "DoshikShrimp", Kind = Kind.Noodle, RuM = "Острая креветка. Красный лоток среди бежевых братьев, семейный бунтарь.", EnM = "Spicy shrimp. A red tray among its beige brothers, the family rebel.", Mesh = "tray", Texture = "DoshikShrimp", Kg = 0.088f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 460f, Ru = "Лапша «Дошик Острая креветка» в лотке", En = "Doshik Spicy Shrimp tray", RuF = "острая, с креветкой", EnF = "spicy shrimp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#d85a2a" },
        new Def { Id = "DoshikShrimpHot", Kind = Kind.Brewed, RuM = "Красный бульон с креветочным духом. Острый ровно настолько, чтобы снять шапку. Одну из двух.", EnM = "Red broth with a shrimp spirit. Just hot enough to take off a hat. One of the two.", Raw = "DoshikShrimp", Mesh = "BowlHot", Texture = "DoshikShrimpHot", Kg = 0.538f, Thirst = 18f, Warm = 1.8f, Shape = "tray", Brand = "Doshik", Kcal = 460f, Ru = "Лапша «Дошик Острая креветка» в лотке", En = "Doshik Spicy Shrimp tray", RuF = "острая, с креветкой", EnF = "spicy shrimp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#d85a2a" },
        new Def { Id = "DoshikKimchi", Kind = Kind.Noodle, RuM = "С кимчи. Лоток вспомнил, что он вообще-то родом из Кореи.", EnM = "With kimchi. The tray remembered it actually comes from Korea.", Mesh = "tray", Texture = "DoshikKimchi", Kg = 0.088f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Кимчи» в лотке", En = "Doshik Kimchi tray", RuF = "острая, с кимчи", EnF = "spicy, with kimchi", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "DoshikKimchiHot", Kind = Kind.Brewed, RuM = "Кисло-острый бульон с капустой. В вагоне за такой запах высадили бы, а здесь высаживать уже некуда.", EnM = "Sour and spicy cabbage broth. On a train this smell would get you thrown off, here there is nowhere left to be thrown.", Raw = "DoshikKimchi", Mesh = "BowlHot", Texture = "DoshikKimchiHot", Kg = 0.538f, Thirst = 18f, Warm = 1.8f, Shape = "tray", Brand = "Doshik", Kcal = 440f, Ru = "Лапша «Дошик Кимчи» в лотке", En = "Doshik Kimchi tray", RuF = "острая, с кимчи", EnF = "spicy, with kimchi", Spicy = 2, Dry = false, Fx = "", Broth = "#d4502a" },
        new Def { Id = "DoshikBeefSpicy", Kind = Kind.Noodle, RuM = "Острая говядина в лотке. Для тех, кому обычный казался слишком мирным попутчиком.", EnM = "Spicy beef in a tray. For those who found the regular one too peaceful a travelling companion.", Mesh = "tray", Texture = "DoshikBeefSpicy", Kg = 0.092f, Water = 0.5f, Shape = "tray", Brand = "Doshik", Kcal = 420f, Ru = "Лапша «Дошик Острая говядина» в лотке", En = "Doshik Spicy Beef tray", RuF = "острая говядина", EnF = "spicy beef", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "DoshikBeefSpicyHot", Kind = Kind.Brewed, RuM = "Тёмный бульон с перцем. Греет руки через стенки лотка, а потом и всё остальное.", EnM = "Dark peppery broth. It warms your hands through the walls of the tray, and then everything else.", Raw = "DoshikBeefSpicy", Mesh = "BowlHot", Texture = "DoshikBeefSpicyHot", Kg = 0.542f, Thirst = 18f, Warm = 1.8f, Shape = "tray", Brand = "Doshik", Kcal = 420f, Ru = "Лапша «Дошик Острая говядина» в лотке", En = "Doshik Spicy Beef tray", RuF = "острая говядина", EnF = "spicy beef", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "BiggLanch", Kind = Kind.Noodle, RuM = "Большой стакан, говядина и грибы. Обед офисного работника, а офис теперь у вас в конторе лесорубов.", EnM = "A big cup, beef and mushrooms. An office worker's lunch, and your office is now in the logging camp.", Mesh = "bigcup", Texture = "BiggLanch", Kg = 0.1f, Water = 0.5f, Shape = "bigcup", Brand = "Bigg", Kcal = 480f, Ru = "Лапша «Бигг Ланч» в большом стакане", En = "Bigg Lanch big cup", RuF = "говядина и грибы", EnF = "beef and mushroom", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#a65e2c" },
        new Def { Id = "BiggLanchHot", Kind = Kind.Brewed, RuM = "Говяжий бульон с грибами, полный стакан до краёв. Обеденный перерыв длится, пока не погаснет огонь.", EnM = "Beef broth with mushrooms, a cup full to the brim. The lunch break lasts until the fire goes out.", Raw = "BiggLanch", Mesh = "bigcupHot", Texture = "BiggLanch", Kg = 0.55f, Thirst = 24f, Warm = 1.2f, Shape = "bigcup", Brand = "Bigg", Kcal = 480f, Ru = "Лапша «Бигг Ланч» в большом стакане", En = "Bigg Lanch big cup", RuF = "говядина и грибы", EnF = "beef and mushroom", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#a65e2c" },
        new Def { Id = "BiggChicken", Kind = Kind.Noodle, RuM = "Курица с зеленью в стакане размером с ведро. Ну, с небольшое ведро. Ну, с большой стакан.", EnM = "Chicken with herbs in a cup the size of a bucket. Well, a small bucket. Well, a big cup.", Mesh = "bigcup", Texture = "BiggChicken", Kg = 0.106f, Water = 0.5f, Shape = "bigcup", Brand = "Bigg", Kcal = 500f, Ru = "Лапша «Бигг Ланч Курица» в большом стакане", En = "Bigg Lanch Chicken big cup", RuF = "курица с зеленью", EnF = "chicken with herbs", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "BiggChickenHot", Kind = Kind.Brewed, RuM = "Куриный бульон с укропом. Пахнет дачей и летом. Дача сгорела бы тут за одну ночь в печке, а запах остался.", EnM = "Chicken broth with dill. It smells of a summer cottage. Here the cottage would be burned in the stove overnight, but the smell remains.", Raw = "BiggChicken", Mesh = "bigcupHot", Texture = "BiggChicken", Kg = 0.556f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "Bigg", Kcal = 500f, Ru = "Лапша «Бигг Ланч Курица» в большом стакане", En = "Bigg Lanch Chicken big cup", RuF = "курица с зеленью", EnF = "chicken with herbs", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "BiggBacon", Kind = Kind.Noodle, RuM = "Бекон с сыром, большой стакан. Диетологи против, но диетологи остались на материке.", EnM = "Bacon with cheese, a big cup. Dietitians object, but the dietitians stayed on the mainland.", Mesh = "bigcup", Texture = "BiggBacon", Kg = 0.105f, Water = 0.5f, Shape = "bigcup", Brand = "Bigg", Kcal = 440f, Ru = "Лапша «Бигг Ланч Бекон» в большом стакане", En = "Bigg Lanch Bacon big cup", RuF = "бекон с сыром", EnF = "bacon with cheese", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d89040" },
        new Def { Id = "BiggBaconHot", Kind = Kind.Brewed, RuM = "Жирно, солоно, сырно. Ровно то, что нужно организму после дня на морозе, что бы он там ни говорил раньше.", EnM = "Fatty, salty, cheesy. Exactly what a body needs after a day in the frost, whatever it used to say before.", Raw = "BiggBacon", Mesh = "bigcupHot", Texture = "BiggBacon", Kg = 0.555f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "Bigg", Kcal = 440f, Ru = "Лапша «Бигг Ланч Бекон» в большом стакане", En = "Bigg Lanch Bacon big cup", RuF = "бекон с сыром", EnF = "bacon with cheese", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d89040" },
        new Def { Id = "BiggPuree", Kind = Kind.Noodle, RuM = "Говядина с перцем. Острота вежливая: сначала спрашивает разрешения.", EnM = "Beef with pepper. A polite heat: it asks permission first.", Mesh = "bigcup", Texture = "BiggPuree", Kg = 0.1f, Water = 0.5f, Shape = "bigcup", Brand = "Bigg", Kcal = 460f, Ru = "Лапша «Бигг Ланч Острый говяжий» в большом стакане", En = "Bigg Lanch Spicy Beef big cup", RuF = "говядина с перцем", EnF = "beef with pepper", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c4381c" },
        new Def { Id = "BiggPureeHot", Kind = Kind.Brewed, RuM = "Говяжий бульон с перчинкой. Большой стакан держат двумя руками, как последнюю надежду. Иногда так и есть.", EnM = "Beef broth with a touch of pepper. You hold the big cup with both hands, like a last hope. Sometimes it is.", Raw = "BiggPuree", Mesh = "bigcupHot", Texture = "BiggPuree", Kg = 0.55f, Thirst = 21f, Warm = 1.4f, Shape = "bigcup", Brand = "Bigg", Kcal = 460f, Ru = "Лапша «Бигг Ланч Острый говяжий» в большом стакане", En = "Bigg Lanch Spicy Beef big cup", RuF = "говядина с перцем", EnF = "beef with pepper", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c4381c" },
        new Def { Id = "BigBumBeef", Kind = Kind.Noodle, RuM = "Говядина с томатным соусом. Название громкое, на острове с таким осторожнее: сходят лавины.", EnM = "Beef with tomato sauce. A loud name, careful with it on the island: avalanches happen.", Mesh = "big2", Texture = "BigBumBeef", Kg = 0.128f, Water = 0.55f, Shape = "big", Brand = "BigBum", Kcal = 590f, Ru = "Лапша «Биг Бум Говядина»", En = "Big Boom Beef noodles", RuF = "с говядиной и томатным соусом", EnF = "beef with a tomato sauce", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b85a2a" },
        new Def { Id = "BigBumBeefHot", Kind = Kind.Brewed, RuM = "Лапша в томатном соусе с говядиной. Соус отдельным пакетиком, почти высокая кухня для хижины без окон.", EnM = "Noodles in tomato sauce with beef. The sauce comes in its own sachet, near haute cuisine for a cabin with no windows.", Raw = "BigBumBeef", Mesh = "BowlHot", Texture = "BigBumBeefHot", Kg = 0.623f, Thirst = 21f, Warm = 1.4f, Shape = "big", Brand = "BigBum", Kcal = 590f, Ru = "Лапша «Биг Бум Говядина»", En = "Big Boom Beef noodles", RuF = "с говядиной и томатным соусом", EnF = "beef with a tomato sauce", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b85a2a" },
        new Def { Id = "BigBumChicken", Kind = Kind.Noodle, RuM = "Курица и сальса. Мексика встретилась с Сибирью на канадском острове. География сдалась.", EnM = "Chicken and salsa. Mexico met Siberia on a Canadian island. Geography gave up.", Mesh = "big0", Texture = "BigBumChicken", Kg = 0.135f, Water = 0.55f, Shape = "big", Brand = "BigBum", Kcal = 570f, Ru = "Лапша «Биг Бум Курица»", En = "Big Boom Chicken noodles", RuF = "с курицей и соусом сальса", EnF = "chicken with a salsa sauce", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0a040" },
        new Def { Id = "BigBumChickenHot", Kind = Kind.Brewed, RuM = "Куриный бульон с красным соусом. Остро слегка, тепло надолго. Сомбреро надевать поверх шапки.", EnM = "Chicken broth with a red sauce. A little hot, warm for long. Wear the sombrero over the hat.", Raw = "BigBumChicken", Mesh = "BowlHot", Texture = "BigBumChickenHot", Kg = 0.63f, Thirst = 21f, Warm = 1.4f, Shape = "big", Brand = "BigBum", Kcal = 570f, Ru = "Лапша «Биг Бум Курица»", En = "Big Boom Chicken noodles", RuF = "с курицей и соусом сальса", EnF = "chicken with a salsa sauce", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0a040" },
        new Def { Id = "BigBumPork", Kind = Kind.Noodle, RuM = "Свинина с сырным соусом. Сырный соус жёлтый, как куртка спасателя, и тоже спасает.", EnM = "Pork with cheese sauce. The cheese sauce is as yellow as a rescuer's jacket and saves lives too.", Mesh = "big1", Texture = "BigBumPork", Kg = 0.13f, Water = 0.55f, Shape = "big", Brand = "BigBum", Kcal = 520f, Ru = "Лапша «Биг Бум Свинина»", En = "Big Boom Pork noodles", RuF = "со свининой и сырным соусом", EnF = "pork with a cheese sauce", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d89848" },
        new Def { Id = "BigBumPorkHot", Kind = Kind.Brewed, RuM = "Густой жёлтый соус обволакивает лапшу. Изящества ноль, сытости на полдня. На острове выбирают второе.", EnM = "A thick yellow sauce coats the noodles. Zero grace, half a day of fullness. On the island you pick the latter.", Raw = "BigBumPork", Mesh = "BowlHot", Texture = "BigBumPorkHot", Kg = 0.625f, Thirst = 24f, Warm = 1.0f, Shape = "big", Brand = "BigBum", Kcal = 520f, Ru = "Лапша «Биг Бум Свинина»", En = "Big Boom Pork noodles", RuF = "со свининой и сырным соусом", EnF = "pork with a cheese sauce", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d89848" },
        new Def { Id = "AnakomChicken", Kind = Kind.Noodle, RuM = "Тонкая вермишель с курицей. Варится за минуту: быстрее на острове только портится погода.", EnM = "Thin vermicelli with chicken. Done in a minute: the only thing faster on the island is the weather turning bad.", Mesh = "mini1", Texture = "AnakomChicken", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Anakom", Kcal = 290f, Ru = "Лапша «Анакомыч Курица»", En = "Anakomych Chicken noodles", RuF = "тонкая вермишель с курицей", EnF = "thin vermicelli with chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AnakomChickenHot", Kind = Kind.Brewed, RuM = "Вермишель тонкая, как рыболовная леска. Леску берегите для лунки, а это ешьте.", EnM = "Vermicelli as thin as fishing line. Save the line for the ice hole and eat this.", Raw = "AnakomChicken", Mesh = "BowlHot", Texture = "AnakomChickenHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Anakom", Kcal = 290f, Ru = "Лапша «Анакомыч Курица»", En = "Anakomych Chicken noodles", RuF = "тонкая вермишель с курицей", EnF = "thin vermicelli with chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AnakomBeef", Kind = Kind.Noodle, RuM = "Вермишель с говядиной. Скромная пачка, которая никогда не обещала лишнего и ни разу не подвела.", EnM = "Vermicelli with beef. A modest pack that never promised too much and never once let you down.", Mesh = "mini1", Texture = "AnakomBeef", Kg = 0.06f, Water = 0.35f, Shape = "mini", Brand = "Anakom", Kcal = 290f, Ru = "Лапша «Анакомыч Говядина»", En = "Anakomych Beef noodles", RuF = "тонкая вермишель с говядиной", EnF = "thin vermicelli with beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "AnakomBeefHot", Kind = Kind.Brewed, RuM = "Тёмный бульон, тонкие нити лапши. Хлебать можно прямо из котелка, манеры остались в самолёте.", EnM = "Dark broth, fine threads of noodles. You can slurp it straight from the pot, manners stayed on the plane.", Raw = "AnakomBeef", Mesh = "BowlHot", Texture = "AnakomBeefHot", Kg = 0.375f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Anakom", Kcal = 290f, Ru = "Лапша «Анакомыч Говядина»", En = "Anakomych Beef noodles", RuF = "тонкая вермишель с говядиной", EnF = "thin vermicelli with beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "AnakomShashlik", Kind = Kind.Noodle, RuM = "Со вкусом шашлыка. Запах костра прилагается, хотя костёр у вас и так свой.", EnM = "Shashlik flavour. The campfire smell is included, though you have a campfire of your own anyway.", Mesh = "mini1", Texture = "AnakomShashlik", Kg = 0.057f, Water = 0.35f, Shape = "mini", Brand = "Anakom", Kcal = 270f, Ru = "Лапша «Анакомыч Шашлык»", En = "Anakomych Shashlik noodles", RuF = "тонкая вермишель со вкусом шашлыка", EnF = "thin vermicelli, shashlik flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b06028" },
        new Def { Id = "AnakomShashlikHot", Kind = Kind.Brewed, RuM = "Бульон пахнет дымом и жареным мясом. Майские праздники в январе, без комаров и без соседей.", EnM = "The broth smells of smoke and grilled meat. A May barbecue in January, with no mosquitoes and no neighbours.", Raw = "AnakomShashlik", Mesh = "BowlHot", Texture = "AnakomShashlikHot", Kg = 0.372f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Anakom", Kcal = 270f, Ru = "Лапша «Анакомыч Шашлык»", En = "Anakomych Shashlik noodles", RuF = "тонкая вермишель со вкусом шашлыка", EnF = "thin vermicelli, shashlik flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b06028" },
        new Def { Id = "MiGoreng", Kind = Kind.Noodle, RuM = "Пять пакетиков внутри: соус, масло, перец, лук, приправа. Собирается как конструктор, только вкусный.", EnM = "Five sachets inside: sauce, oil, chilli, onion, seasoning. It goes together like a building kit, only tasty.", Mesh = "brick0", Texture = "MiGoreng", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 460f, Ru = "Жареная лапша «Индомэй Ми Горенг»", En = "Indomay Mi Goreng fried noodles", RuF = "сладкий соевый соус, без бульона", EnF = "sweet soy sauce, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#8a4a1c" },
        new Def { Id = "MiGorengHot", Kind = Kind.Brewed, RuM = "Сладкая, блестящая, с хрустящим луком. Индонезия на вилке, плюс тридцать во рту, минус тридцать за дверью.", EnM = "Sweet, glossy, with crispy onion. Indonesia on a fork, plus thirty in your mouth, minus thirty outside the door.", Raw = "MiGoreng", Mesh = "PlateHot", Texture = "MiGorengHot", Kg = 0.185f, Thirst = -6f, Warm = 0.6f, Shape = "brick", Brand = "Indomay", Kcal = 460f, Ru = "Жареная лапша «Индомэй Ми Горенг»", En = "Indomay Mi Goreng fried noodles", RuF = "сладкий соевый соус, без бульона", EnF = "sweet soy sauce, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#8a4a1c" },
        new Def { Id = "MiGorengRendang", Kind = Kind.Noodle, RuM = "Говядина ренданг: блюдо, которое на Суматре тушат полдня. В пачке уложились в один пакетик.", EnM = "Beef rendang: a dish stewed for half a day in Sumatra. The pack fits it into one sachet.", Mesh = "brick0", Texture = "MiGorengRendang", Kg = 0.081f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 380f, Ru = "Лапша «Индомэй Ми Горенг Ренданг»", En = "Indomay Mi Goreng Rendang noodles", RuF = "пряная говядина ренданг, без бульона", EnF = "spiced rendang beef, no broth", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#7a3a16" },
        new Def { Id = "MiGorengRendangHot", Kind = Kind.Brewed, RuM = "Пряная, тёмная и густая. Корица, кокос, перец. Пахнет джунглями, где волков нет, зато есть тигры. Везде свои минусы.", EnM = "Spiced, dark and thick. Cinnamon, coconut, chilli. It smells of a jungle with no wolves but with tigers. Every place has its downside.", Raw = "MiGorengRendang", Mesh = "PlateHot", Texture = "MiGorengRendangHot", Kg = 0.181f, Thirst = -10f, Warm = 1.35f, Shape = "brick", Brand = "Indomay", Kcal = 380f, Ru = "Лапша «Индомэй Ми Горенг Ренданг»", En = "Indomay Mi Goreng Rendang noodles", RuF = "пряная говядина ренданг, без бульона", EnF = "spiced rendang beef, no broth", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#7a3a16" },
        new Def { Id = "MiGorengPedas", Kind = Kind.Noodle, RuM = "«Педас» значит «острая». Выучите это слово, оно ещё встретится и уже не обманет.", EnM = "\"Pedas\" means \"hot\". Learn the word, you will meet it again and it will not fool you twice.", Mesh = "brick1", Texture = "MiGorengPedas", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Ми Горенг Педас»", En = "Indomay Mi Goreng Pedas noodles", RuF = "острая жареная лапша, без бульона", EnF = "hot fried noodles, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#9a3414" },
        new Def { Id = "MiGorengPedasHot", Kind = Kind.Brewed, RuM = "Жареная лапша в красном соусе. Тропическая жара в отдельно взятой хижине. Окно не открывать, выстудит.", EnM = "Fried noodles in red sauce. Tropical heat in one particular cabin. Keep the window shut, you will lose the warmth.", Raw = "MiGorengPedas", Mesh = "PlateHot", Texture = "MiGorengPedasHot", Kg = 0.185f, Thirst = -12f, Warm = 1.65f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Ми Горенг Педас»", En = "Indomay Mi Goreng Pedas noodles", RuF = "острая жареная лапша, без бульона", EnF = "hot fried noodles, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#9a3414" },
        new Def { Id = "MiGorengSatay", Kind = Kind.Noodle, RuM = "Арахисовый соус сатэ. Орехи на острове не растут, так что это ещё и редкость.", EnM = "Peanut satay sauce. No nuts grow on the island, so this is a rarity as well.", Mesh = "brick0", Texture = "MiGorengSatay", Kg = 0.081f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 410f, Ru = "Лапша «Индомэй Ми Горенг Сатэ»", En = "Indomay Mi Goreng Satay noodles", RuF = "арахисовый соус сатэ, без бульона", EnF = "peanut satay sauce, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#9a6a2a" },
        new Def { Id = "MiGorengSatayHot", Kind = Kind.Brewed, RuM = "Сладко-ореховая лапша липнет к губам. Калорий в ней столько, что белка запасла бы на зиму. Вы тоже запасайте.", EnM = "Sweet nutty noodles that stick to your lips. So many calories a squirrel would store them for winter. You should too.", Raw = "MiGorengSatay", Mesh = "PlateHot", Texture = "MiGorengSatayHot", Kg = 0.181f, Thirst = -8f, Warm = 1.05f, Shape = "brick", Brand = "Indomay", Kcal = 410f, Ru = "Лапша «Индомэй Ми Горенг Сатэ»", En = "Indomay Mi Goreng Satay noodles", RuF = "арахисовый соус сатэ, без бульона", EnF = "peanut satay sauce, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#9a6a2a" },
        new Def { Id = "IndomaySoto", Kind = Kind.Noodle, RuM = "Жёлтый суп сото с лаймом. Жёлтый от куркумы, а не от того, о чём вы подумали, глядя на снег.", EnM = "Yellow soto soup with lime. Yellow from turmeric, not from what you thought of, looking at the snow.", Mesh = "brick2", Texture = "IndomaySoto", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Сото Ми»", En = "Indomay Soto Mie noodles", RuF = "куриный суп с лаймом и куркумой", EnF = "chicken soup with lime and turmeric", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0c040" },
        new Def { Id = "IndomaySotoHot", Kind = Kind.Brewed, RuM = "Золотистый бульон, кислинка лайма. Суп, которым в Индонезии лечат всё. Обморожение не проверяли.", EnM = "Golden broth with a tang of lime. The soup that cures everything in Indonesia. Frostbite was never tested.", Raw = "IndomaySoto", Mesh = "BowlHot", Texture = "IndomaySotoHot", Kg = 0.446f, Thirst = 21f, Warm = 1.4f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Сото Ми»", En = "Indomay Soto Mie noodles", RuF = "куриный суп с лаймом и куркумой", EnF = "chicken soup with lime and turmeric", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#e0c040" },
        new Def { Id = "IndomayKari", Kind = Kind.Noodle, RuM = "Куриное карри. Пакетик с кокосовым порошком внутри делает из воды сливки. Почти волшебство.", EnM = "Chicken curry. The coconut powder sachet inside turns water into cream. Nearly magic.", Mesh = "brick1", Texture = "IndomayKari", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Кари Аям»", En = "Indomay Kari Ayam noodles", RuF = "куриное карри", EnF = "chicken curry", Spicy = 2, Dry = false, Fx = "", Broth = "#d39a1e" },
        new Def { Id = "IndomayKariHot", Kind = Kind.Brewed, RuM = "Густой жёлтый бульон с перцем. Пальмы, пляж, тёплый океан. Всё это в миске, а вы на льду.", EnM = "A thick yellow broth with chilli. Palms, a beach, a warm ocean. All of it in the bowl, and you on the ice.", Raw = "IndomayKari", Mesh = "BowlHot", Texture = "IndomayKariHot", Kg = 0.445f, Thirst = 18f, Warm = 1.8f, Shape = "brick", Brand = "Indomay", Kcal = 370f, Ru = "Лапша «Индомэй Кари Аям»", En = "Indomay Kari Ayam noodles", RuF = "куриное карри", EnF = "chicken curry", Spicy = 2, Dry = false, Fx = "", Broth = "#d39a1e" },
        new Def { Id = "IndomayOnion", Kind = Kind.Noodle, RuM = "Версия для Нигерии, где её едят больше, чем дома: курица с луком.", EnM = "The Nigerian version, eaten there more than at home: chicken and onion.", Mesh = "brick1", Texture = "IndomayOnion", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 390f, Ru = "Лапша «Индомэй Онион Чикен»", En = "Indomay Onion Chicken noodles", RuF = "версия для Нигерии, где её едят больше, чем дома: курица с луком", EnF = "the Nigerian version, eaten there more than at home: chicken and onion", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "IndomayOnionHot", Kind = Kind.Brewed, RuM = "Курица с луком, простая и сытная. Полконтинента выросло на этой миске, и никто не жаловался.", EnM = "Chicken with onion, plain and filling. Half a continent grew up on this bowl and nobody complained.", Raw = "IndomayOnion", Mesh = "BowlHot", Texture = "IndomayOnionHot", Kg = 0.45f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Indomay", Kcal = 390f, Ru = "Лапша «Индомэй Онион Чикен»", En = "Indomay Onion Chicken noodles", RuF = "версия для Нигерии, где её едят больше, чем дома: курица с луком", EnF = "the Nigerian version, eaten there more than at home: chicken and onion", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "IndomayPepper", Kind = Kind.Noodle, RuM = "Нигерийский перечный суп с курицей. Перец в названии не для красоты.", EnM = "Nigerian chicken pepper soup. The pepper in the name is not there for show.", Mesh = "brick1", Texture = "IndomayPepper", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "Indomay", Kcal = 390f, Ru = "Лапша «Индомэй Пеппер Суп»", En = "Indomay Pepper Soup noodles", RuF = "нигерийский перечный суп с курицей. Перец в названии не для красоты", EnF = "Nigerian chicken pepper soup. The pepper in the name is not there for show", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#b8401c" },
        new Def { Id = "IndomayPepperHot", Kind = Kind.Brewed, RuM = "Перечный суп, которым в Нигерии выгоняют простуду. Простуда уходит быстро, вместе с голосом.", EnM = "The pepper soup Nigerians use to drive out a cold. The cold leaves fast, and takes your voice along.", Raw = "IndomayPepper", Mesh = "BowlHot", Texture = "IndomayPepperHot", Kg = 0.45f, Thirst = 15f, Warm = 2.2f, Shape = "brick", Brand = "Indomay", Kcal = 390f, Ru = "Лапша «Индомэй Пеппер Суп»", En = "Indomay Pepper Soup noodles", RuF = "нигерийский перечный суп с курицей. Перец в названии не для красоты", EnF = "Nigerian chicken pepper soup. The pepper in the name is not there for show", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#b8401c" },
        new Def { Id = "SedapGoreng", Kind = Kind.Noodle, RuM = "«Сэдап» значит «вкусно». Скромностью производитель не страдает, зато положил пакетик хрустящего лука.", EnM = "\"Sedap\" means \"tasty\". The maker is not troubled by modesty, but did put in a sachet of crispy onion.", Mesh = "brick2", Texture = "SedapGoreng", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "Sedap", Kcal = 400f, Ru = "Лапша «Ми Сэдап Горенг»", En = "Mie Sedap Goreng noodles", RuF = "жареная лапша с хрустящим луком, без бульона", EnF = "fried noodles with crisp shallots, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#8a4a1c" },
        new Def { Id = "SedapGorengHot", Kind = Kind.Brewed, RuM = "Лук хрустит, соус блестит. Хрустите потише: в тихую ночь на льду такое слышно через всё озеро.", EnM = "The onion crunches, the sauce shines. Crunch quietly: on a still night on the ice it carries across the whole lake.", Raw = "SedapGoreng", Mesh = "PlateHot", Texture = "SedapGorengHot", Kg = 0.19f, Thirst = -8f, Warm = 1.05f, Shape = "brick", Brand = "Sedap", Kcal = 400f, Ru = "Лапша «Ми Сэдап Горенг»", En = "Mie Sedap Goreng noodles", RuF = "жареная лапша с хрустящим луком, без бульона", EnF = "fried noodles with crisp shallots, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#8a4a1c" },
        new Def { Id = "SedapKorean", Kind = Kind.Noodle, RuM = "Индонезийский ответ корейской огненной курице. Отвечали громко.", EnM = "Indonesia's answer to Korean fire chicken. They answered loudly.", Mesh = "brick0", Texture = "SedapKorean", Kg = 0.081f, Water = 0.4f, Shape = "brick", Brand = "Sedap", Kcal = 370f, Ru = "Лапша «Ми Сэдап Корейская острая»", En = "Mie Sedap Korean Spicy noodles", RuF = "острая курица по-корейски, без бульона", EnF = "Korean-style hot chicken, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#9e1b10" },
        new Def { Id = "SedapKoreanHot", Kind = Kind.Brewed, RuM = "Красная, липкая, беспощадная. Два народа объединили усилия, чтобы вы заплакали посреди канадской тайги.", EnM = "Red, sticky, merciless. Two nations joined forces to make you cry in the middle of the Canadian wilderness.", Raw = "SedapKorean", Mesh = "PlateHot", Texture = "SedapKoreanHot", Kg = 0.181f, Thirst = -12f, Warm = 1.65f, Shape = "brick", Brand = "Sedap", Kcal = 370f, Ru = "Лапша «Ми Сэдап Корейская острая»", En = "Mie Sedap Korean Spicy noodles", RuF = "острая курица по-корейски, без бульона", EnF = "Korean-style hot chicken, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#9e1b10" },
        new Def { Id = "MamaTomYum", Kind = Kind.Noodle, RuM = "«Мама» из Таиланда. Мама бы не отпустила вас на этот остров, но хотя бы положила лапши в дорогу.", EnM = "\"Mama\" from Thailand. Mama would never have let you go to this island, but at least she packed noodles for the trip.", Mesh = "mini2", Texture = "MamaTomYum", Kg = 0.057f, Water = 0.35f, Shape = "mini", Brand = "Mama", Kcal = 290f, Ru = "Лапша «Мама Том Ям»", En = "Mama Tom Yum noodles", RuF = "кисло-острый суп с креветками", EnF = "hot and sour shrimp soup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "MamaTomYumHot", Kind = Kind.Brewed, RuM = "Кисло, остро, креветочно. Том-ям прочищает нос так, что запахи чуешь не хуже волка.", EnM = "Sour, hot, shrimpy. Tom yum clears your nose so well you can smell things as well as a wolf.", Raw = "MamaTomYum", Mesh = "BowlHot", Texture = "MamaTomYumHot", Kg = 0.372f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "Mama", Kcal = 290f, Ru = "Лапша «Мама Том Ям»", En = "Mama Tom Yum noodles", RuF = "кисло-острый суп с креветками", EnF = "hot and sour shrimp soup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "MamaCreamy", Kind = Kind.Noodle, RuM = "Том-ям со сливками из кокоса. Мама подобрела, но перец на всякий случай оставила.", EnM = "Tom yum with coconut cream. Mama has softened, but kept the chilli just in case.", Mesh = "mini0", Texture = "MamaCreamy", Kg = 0.059f, Water = 0.35f, Shape = "mini", Brand = "Mama", Kcal = 280f, Ru = "Лапша «Мама Том Ям сливочный»", En = "Mama Creamy Tom Yum noodles", RuF = "кисло-острый суп с кокосовым молоком", EnF = "hot and sour soup with coconut milk", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eb8a4a" },
        new Def { Id = "MamaCreamyHot", Kind = Kind.Brewed, RuM = "Оранжевый бульон, мягкий на первый глоток. На второй мама напоминает, кто в доме главный.", EnM = "An orange broth, gentle on the first sip. On the second Mama reminds you who runs the house.", Raw = "MamaCreamy", Mesh = "BowlHot", Texture = "MamaCreamyHot", Kg = 0.374f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "Mama", Kcal = 280f, Ru = "Лапша «Мама Том Ям сливочный»", En = "Mama Creamy Tom Yum noodles", RuF = "кисло-острый суп с кокосовым молоком", EnF = "hot and sour soup with coconut milk", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eb8a4a" },
        new Def { Id = "MamaPork", Kind = Kind.Noodle, RuM = "Рубленая свинина с чесноком. Самая спокойная у мамы, для тех, кто сегодня уже натерпелся.", EnM = "Minced pork with garlic. Mama's calmest, for those who have had enough for one day.", Mesh = "mini1", Texture = "MamaPork", Kg = 0.06f, Water = 0.35f, Shape = "mini", Brand = "Mama", Kcal = 260f, Ru = "Лапша «Мама Свинина»", En = "Mama Pork noodles", RuF = "рубленая свинина с чесноком", EnF = "minced pork with garlic", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c9925a" },
        new Def { Id = "MamaPorkHot", Kind = Kind.Brewed, RuM = "Прозрачный бульон, чеснок, маленькая порция. Мама считает, что вы мало едите, и на этом острове она права.", EnM = "A clear broth, garlic, a small helping. Mama thinks you do not eat enough, and on this island she is right.", Raw = "MamaPork", Mesh = "BowlHot", Texture = "MamaPorkHot", Kg = 0.375f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Mama", Kcal = 260f, Ru = "Лапша «Мама Свинина»", En = "Mama Pork noodles", RuF = "рубленая свинина с чесноком", EnF = "minced pork with garlic", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c9925a" },
        new Def { Id = "MamaGreenCurry", Kind = Kind.Noodle, RuM = "Зелёное карри. Зелёный в Таиланде не значит «можно». Он значит «тоже остро, но по-другому».", EnM = "Green curry. In Thailand green does not mean \"go\". It means \"also hot, in a different way\".", Mesh = "mini2", Texture = "MamaGreenCurry", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "Mama", Kcal = 280f, Ru = "Лапша «Мама Зелёное карри»", En = "Mama Green Curry noodles", RuF = "тайское зелёное карри", EnF = "Thai green curry", Spicy = 2, Dry = false, Fx = "", Broth = "#a8b85a" },
        new Def { Id = "MamaGreenCurryHot", Kind = Kind.Brewed, RuM = "Зеленоватый бульон с кокосом и базиликом. Цвет как у северного сияния, действует тоже ночью.", EnM = "A greenish broth with coconut and basil. The colour of the aurora, and it works at night too.", Raw = "MamaGreenCurry", Mesh = "BowlHot", Texture = "MamaGreenCurryHot", Kg = 0.377f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "Mama", Kcal = 280f, Ru = "Лапша «Мама Зелёное карри»", En = "Mama Green Curry noodles", RuF = "тайское зелёное карри", EnF = "Thai green curry", Spicy = 2, Dry = false, Fx = "", Broth = "#a8b85a" },
        new Def { Id = "MamaCup", Kind = Kind.Noodle, RuM = "Мамин том-ям в стакане. Маленький, зато помещается в карман куртки вместе со спичками.", EnM = "Mama's tom yum in a cup. Small, but it fits in a jacket pocket along with the matches.", Mesh = "cup", Texture = "MamaCup", Kg = 0.071f, Water = 0.3f, Shape = "cup", Brand = "Mama", Kcal = 350f, Ru = "Лапша «Мама Том Ям» в стакане", En = "Mama Tom Yum cup", RuF = "кисло-острый суп с креветками", EnF = "hot and sour shrimp soup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "MamaCupHot", Kind = Kind.Brewed, RuM = "Маленький стакан, большой характер. Три глотка бульона, и уши горят уже не от мороза.", EnM = "A small cup with a big temper. Three sips of broth and your ears burn, no longer from the frost.", Raw = "MamaCup", Mesh = "cupHot", Texture = "MamaCup", Kg = 0.341f, Thirst = 18f, Warm = 1.8f, Shape = "cup", Brand = "Mama", Kcal = 350f, Ru = "Лапша «Мама Том Ям» в стакане", En = "Mama Tom Yum cup", RuF = "кисло-острый суп с креветками", EnF = "hot and sour shrimp soup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "MamaTomYumBowl", Kind = Kind.Noodle, RuM = "Том-ям в большом стакане с сушёной креветкой. Креветка одна, зато настоящая и смотрит с укором.", EnM = "Tom yum in a big cup with a dried shrimp. Just one shrimp, but a real one, and it looks at you with reproach.", Mesh = "bigcup", Texture = "MamaTomYumBowl", Kg = 0.104f, Water = 0.5f, Shape = "bigcup", Brand = "Mama", Kcal = 470f, Ru = "Лапша «Мама Том-ям» в большом стакане", En = "Mama Tom Yum big cup", RuF = "том-ям с креветкой, большой стакан", EnF = "shrimp tom yum, a big cup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "MamaTomYumBowlHot", Kind = Kind.Brewed, RuM = "Большой стакан кисло-острого бульона. Креветка размокла и почти ожила. Для неё поздно, для вас в самый раз.", EnM = "A big cup of sour and spicy broth. The shrimp has soaked and almost come alive. Too late for it, just right for you.", Raw = "MamaTomYumBowl", Mesh = "bigcupHot", Texture = "MamaTomYumBowl", Kg = 0.554f, Thirst = 18f, Warm = 1.8f, Shape = "bigcup", Brand = "Mama", Kcal = 470f, Ru = "Лапша «Мама Том-ям» в большом стакане", En = "Mama Tom Yum big cup", RuF = "том-ям с креветкой, большой стакан", EnF = "shrimp tom yum, a big cup", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "YumYumDuck", Kind = Kind.Noodle, RuM = "С уткой. Уток на острове нет, есть куропатки, но их ещё надо поймать, а пачку надо только открыть.", EnM = "With duck. The island has no ducks, it has ptarmigans, but those must be caught, and the pack only needs opening.", Mesh = "mini0", Texture = "YumYumDuck", Kg = 0.061f, Water = 0.35f, Shape = "mini", Brand = "YumYum", Kcal = 270f, Ru = "Лапша «Ям-Ям Утка»", En = "Yum-Yum Duck noodles", RuF = "бульон с уткой", EnF = "duck broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b8763a" },
        new Def { Id = "YumYumDuckHot", Kind = Kind.Brewed, RuM = "Тёмный утиный бульон с пряностями. Название обещает «ням-ням» и держит слово обоими слогами.", EnM = "A dark, spiced duck broth. The name promises \"yum yum\" and keeps its word on both syllables.", Raw = "YumYumDuck", Mesh = "BowlHot", Texture = "YumYumDuckHot", Kg = 0.376f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "YumYum", Kcal = 270f, Ru = "Лапша «Ям-Ям Утка»", En = "Yum-Yum Duck noodles", RuF = "бульон с уткой", EnF = "duck broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b8763a" },
        new Def { Id = "YumYumSeafood", Kind = Kind.Noodle, RuM = "Острые морепродукты. «Ням-ням» тут произносят с паузой, чтобы отдышаться.", EnM = "Spicy seafood. Here \"yum yum\" is said with a pause in between to catch your breath.", Mesh = "mini2", Texture = "YumYumSeafood", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "YumYum", Kcal = 290f, Ru = "Лапша «Ям-Ям Морепродукты»", En = "Yum-Yum Seafood noodles", RuF = "острый бульон с морепродуктами", EnF = "a spicy seafood broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "YumYumSeafoodHot", Kind = Kind.Brewed, RuM = "Красный бульон с запахом моря и перца. Кит у причала такого не пробовал, ему не повезло дважды.", EnM = "A red broth smelling of sea and chilli. The whale at the pier never tried it, unlucky twice over.", Raw = "YumYumSeafood", Mesh = "BowlHot", Texture = "YumYumSeafoodHot", Kg = 0.377f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "YumYum", Kcal = 290f, Ru = "Лапша «Ям-Ям Морепродукты»", En = "Yum-Yum Seafood noodles", RuF = "острый бульон с морепродуктами", EnF = "a spicy seafood broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "WaiWai", Kind = Kind.Noodle, RuM = "Лапша из Непала. Её придумали у подножия Гималаев, так что с горами и холодом она на ты.", EnM = "Noodles from Nepal. Invented at the foot of the Himalayas, so they are on first-name terms with mountains and cold.", Mesh = "mini1", Texture = "WaiWai", Kg = 0.06f, Water = 0.35f, Shape = "mini", Brand = "WaiWai", Kcal = 280f, Ru = "Лапша «Вай-Вай»", En = "Wai-Wai noodles", RuF = "непальская лапша с курицей и специями", EnF = "Nepali noodles with chicken and spices", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d8a030" },
        new Def { Id = "WaiWaiHot", Kind = Kind.Brewed, RuM = "Курица и гималайские специи. Шерпы едят её на высоте, вы на вершине Волчьей горы. Вид похожий, компания хуже.", EnM = "Chicken and Himalayan spices. Sherpas eat it at altitude, you on the summit of Timberwolf Mountain. Similar view, worse company.", Raw = "WaiWai", Mesh = "BowlHot", Texture = "WaiWaiHot", Kg = 0.375f, Thirst = 21f, Warm = 1.4f, Shape = "mini", Brand = "WaiWai", Kcal = 280f, Ru = "Лапша «Вай-Вай»", En = "Wai-Wai noodles", RuF = "непальская лапша с курицей и специями", EnF = "Nepali noodles with chicken and spices", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d8a030" },
        new Def { Id = "HauHau", Kind = Kind.Noodle, RuM = "«Хау Хау» значит «хорошо-хорошо». Во Вьетнаме это правда, на острове звучит как издёвка.", EnM = "\"Hao Hao\" means \"good, good\". In Vietnam that is true, on the island it sounds like a taunt.", Mesh = "mini1", Texture = "HauHau", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "HauHau", Kcal = 290f, Ru = "Лапша «Хау Хау»", En = "Hau Hau noodles", RuF = "кисло-острая креветка по-вьетнамски", EnF = "Vietnamese hot and sour shrimp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "HauHauHot", Kind = Kind.Brewed, RuM = "Кисло-острый бульон с креветкой. Розовый, жаркий, шумный. Маленький Сайгон в котелке посреди большой тишины.", EnM = "A sour and spicy shrimp broth. Pink, hot, noisy. A little Saigon in a pot amid a great silence.", Raw = "HauHau", Mesh = "BowlHot", Texture = "HauHauHot", Kg = 0.373f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "HauHau", Kcal = 290f, Ru = "Лапша «Хау Хау»", En = "Hau Hau noodles", RuF = "кисло-острая креветка по-вьетнамски", EnF = "Vietnamese hot and sour shrimp", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "VifoPhoBo", Kind = Kind.Noodle, RuM = "Рисовая лапша для супа фо. Белая, плоская и ломкая, как лёд у берега в оттепель.", EnM = "Rice noodles for pho soup. White, flat and brittle, like shore ice in a thaw.", Mesh = "brick2", Texture = "VifoPhoBo", Kg = 0.082f, Water = 0.4f, Shape = "brick", Brand = "Vifo", Kcal = 370f, Ru = "Лапша «Вифо Фо Бо»", En = "Vifo Pho Bo noodles", RuF = "рисовая лапша в говяжьем бульоне с бадьяном", EnF = "rice noodles in beef broth with star anise", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "VifoPhoBoHot", Kind = Kind.Brewed, RuM = "Говяжий бульон с бадьяном. Во Вьетнаме фо едят на завтрак. На острове это завтрак, обед и повод встать.", EnM = "Beef broth with star anise. In Vietnam pho is breakfast. On the island it is breakfast, lunch and a reason to get up.", Raw = "VifoPhoBo", Mesh = "BowlHot", Texture = "VifoPhoBoHot", Kg = 0.442f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Vifo", Kcal = 370f, Ru = "Лапша «Вифо Фо Бо»", En = "Vifo Pho Bo noodles", RuF = "рисовая лапша в говяжьем бульоне с бадьяном", EnF = "rice noodles in beef broth with star anise", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "VifoPhoGa", Kind = Kind.Noodle, RuM = "Фо с курицей. Легче говяжьего, для тех дней, когда вы и так еле несёте рюкзак.", EnM = "Chicken pho. Lighter than the beef one, for days when you can barely carry your pack as it is.", Mesh = "brick2", Texture = "VifoPhoGa", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "Vifo", Kcal = 390f, Ru = "Лапша «Вифо Фо Га»", En = "Vifo Pho Ga noodles", RuF = "рисовая лапша в курином бульоне", EnF = "rice noodles in chicken broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0cc8a" },
        new Def { Id = "VifoPhoGaHot", Kind = Kind.Brewed, RuM = "Светлый куриный бульон, белая лапша, зелёный лук. Чисто, как первый снег, пока по нему никто не прошёл.", EnM = "Light chicken broth, white noodles, green onion. Clean as the first snow before anyone has walked on it.", Raw = "VifoPhoGa", Mesh = "BowlHot", Texture = "VifoPhoGaHot", Kg = 0.446f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Vifo", Kcal = 390f, Ru = "Лапша «Вифо Фо Га»", En = "Vifo Pho Ga noodles", RuF = "рисовая лапша в курином бульоне", EnF = "rice noodles in chicken broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0cc8a" },
        new Def { Id = "VifoBowl", Kind = Kind.Noodle, RuM = "Фо в миске. Палочек в комплекте нет, но веток вокруг целый лес.", EnM = "Pho in a bowl. No chopsticks included, but there is a whole forest of twigs around.", Mesh = "bowl", Texture = "VifoBowl", Kg = 0.098f, Water = 0.45f, Shape = "bowl", Brand = "Vifo", Kcal = 450f, Ru = "Лапша «Вифо Фо Бо» в миске", En = "Vifo Pho Bo bowl", RuF = "рисовая лапша в говяжьем бульоне с бадьяном", EnF = "rice noodles in beef broth with star anise", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "VifoBowlHot", Kind = Kind.Brewed, RuM = "Миска говяжьего фо дымится на подоконнике. Запах бадьяна и корицы в доме, где пахло только сыростью и печалью.", EnM = "A bowl of beef pho steaming on the windowsill. Star anise and cinnamon in a house that smelled only of damp and sorrow.", Raw = "VifoBowl", Mesh = "bowlHot", Texture = "VifoBowl", Kg = 0.503f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Vifo", Kcal = 450f, Ru = "Лапша «Вифо Фо Бо» в миске", En = "Vifo Pho Bo bowl", RuF = "рисовая лапша в говяжьем бульоне с бадьяном", EnF = "rice noodles in beef broth with star anise", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "KunBeef", Kind = Kind.Noodle, RuM = "Ведёрко от мастера Куна. Мастер улыбается с крышки, как человек, который точно знает, где сейчас тепло.", EnM = "A bucket from Master Kun. The master smiles from the lid like a man who knows exactly where it is warm right now.", Mesh = "bucket", Texture = "KunBeef", Kg = 0.104f, Water = 0.5f, Shape = "bucket", Brand = "Kun", Kcal = 480f, Ru = "Лапша «Мастер Кун Тушёная говядина» в ведёрке", En = "Master Kun Braised Beef bucket", RuF = "густой бульон с тушёной говядиной", EnF = "a thick braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "KunBeefHot", Kind = Kind.Brewed, RuM = "Тушёная говядина в густом бульоне. Самая продаваемая лапша Китая: миллиард человек не может ошибаться, и вы не ошиблись.", EnM = "Stewed beef in a thick broth. China's best-selling noodles: a billion people cannot be wrong, and neither were you.", Raw = "KunBeef", Mesh = "bucketHot", Texture = "KunBeef", Kg = 0.554f, Thirst = 21f, Warm = 1.4f, Shape = "bucket", Brand = "Kun", Kcal = 480f, Ru = "Лапша «Мастер Кун Тушёная говядина» в ведёрке", En = "Master Kun Braised Beef bucket", RuF = "густой бульон с тушёной говядиной", EnF = "a thick braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "KunSpicy", Kind = Kind.Noodle, RuM = "Говядина в остром масле. Красное ведёрко, и красный цвет здесь не для красоты.", EnM = "Beef in hot oil. A red bucket, and the red is not there for looks.", Mesh = "bucket", Texture = "KunSpicy", Kg = 0.108f, Water = 0.5f, Shape = "bucket", Brand = "Kun", Kcal = 500f, Ru = "Лапша «Мастер Кун Острая говядина» в ведёрке", En = "Master Kun Spicy Beef bucket", RuF = "говядина в остром масле", EnF = "beef in hot oil", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#a8200e" },
