        new Def { Id = "KunCabbage", Kind = Kind.Noodle, RuM = "Говядина с квашеной капустой. Китайская зима тоже длинная, и капусту там тоже квасят бочками.", EnM = "Beef with pickled cabbage. Chinese winters are long too, and they pickle cabbage by the barrel as well.", Mesh = "big2", Texture = "KunCabbage", Kg = 0.133f, Water = 0.55f, Shape = "big", Brand = "Kun", Kcal = 540f, Ru = "Лапша «Мастер Кун Квашеная капуста»", En = "Master Kun Pickled Cabbage noodles", RuF = "говядина с квашеной капустой", EnF = "beef with pickled cabbage", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8862a" },
        new Def { Id = "KunCabbageHot", Kind = Kind.Brewed, RuM = "Кисловатый бульон с говядиной. Капуста хрустит, как шаги по насту, только от этого хруста никто не просыпается.", EnM = "A tangy beef broth. The cabbage crunches like footsteps on crusted snow, only this crunch wakes nobody up.", Raw = "KunCabbage", Mesh = "DonburiHot", Texture = "KunCabbageHot", Kg = 0.628f, Thirst = 21f, Warm = 1.4f, Shape = "big", Brand = "Kun", Kcal = 540f, Ru = "Лапша «Мастер Кун Квашеная капуста»", En = "Master Kun Pickled Cabbage noodles", RuF = "говядина с квашеной капустой", EnF = "beef with pickled cabbage", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#b8862a" },
