        new Def { Id = "KunSeafoodHot", Kind = Kind.Brewed, RuM = "Светлый бульон с креветкой и водорослями. Мастер Кун на крышке одобрительно кивает. Или это пар.", EnM = "A light broth with shrimp and seaweed. Master Kun on the lid nods in approval. Or that is the steam.", Raw = "KunSeafood", Mesh = "bucketHot", Texture = "KunSeafood", Kg = 0.56f, Thirst = 24f, Warm = 1.0f, Shape = "bucket", Brand = "Kun", Kcal = 490f, Ru = "Лапша «Мастер Кун Морепродукты» в ведёрке", En = "Master Kun Seafood bucket", RuF = "бульон с морепродуктами", EnF = "seafood broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "DanDan", Kind = Kind.Noodle, RuM = "Дандань: лапша, которую в Сычуани носили на коромысле. Коромысла у вас нет, есть рюкзак на тридцать кило.", EnM = "Dan dan: noodles once carried on a shoulder pole in Sichuan. You have no pole, you have a thirty-kilo pack.", Mesh = "brick1", Texture = "DanDan", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "DanDan", Kcal = 390f, Ru = "Лапша «Сычуань Дандань»", En = "Sichuan Dandan noodles", RuF = "лапша в остром кунжутном соусе, без бульона", EnF = "noodles in a hot sesame sauce, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#a84a1a" },
        new Def { Id = "DanDanHot", Kind = Kind.Brewed, RuM = "Кунжутная паста, масло чили и онемевший язык. Говорить после неё трудно, но на острове и не с кем.", EnM = "Sesame paste, chilli oil and a numb tongue. Talking is hard afterwards, but on the island there is nobody to talk to.", Raw = "DanDan", Mesh = "PlateHot", Texture = "DanDanHot", Kg = 0.19f, Thirst = -12f, Warm = 1.65f, Shape = "brick", Brand = "DanDan", Kcal = 390f, Ru = "Лапша «Сычуань Дандань»", En = "Sichuan Dandan noodles", RuF = "лапша в остром кунжутном соусе, без бульона", EnF = "noodles in a hot sesame sauce, no broth", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#a84a1a" },
        new Def { Id = "ManHan", Kind = Kind.Noodle, RuM = "Ведёрко с пакетом настоящего мяса. Не порошок, не кубики, а куски. Проверьте, вы не спите.", EnM = "A bucket with a pouch of real meat. Not powder, not cubes, but chunks. Check that you are not dreaming.", Mesh = "bucket", Texture = "ManHan", Kg = 0.108f, Water = 0.5f, Shape = "bucket", Brand = "ManHan", Kcal = 510f, Ru = "Лапша «Мань Хань Говядина» в ведёрке", En = "Man Han Beef bucket", RuF = "тайваньский суп с настоящими кусками говядины", EnF = "Taiwanese soup with real chunks of beef", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#8a4420" },
