        new Def { Id = "PancitCantonHot", Kind = Kind.Brewed, RuM = "Солоноватая, с кислинкой каламанси. Маленький цитрус с тёплых островов на острове, который тёплым не был никогда.", EnM = "Savoury, with the tang of calamansi. A small citrus from warm islands on an island that was never warm.", Raw = "PancitCanton", Mesh = "PlateHot", Texture = "PancitCantonHot", Kg = 0.145f, Thirst = -8f, Warm = 1.05f, Shape = "mini", Brand = "LuckyMi", Kcal = 300f, Ru = "Лапша «Лаки Ми Пансит Кантон»", En = "Lucky Mi Pancit Canton noodles", RuF = "филиппинская жареная лапша с каламанси, без бульона", EnF = "Filipino fried noodles with calamansi, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#b8782a" },
        new Def { Id = "PancitChilimansi", Kind = Kind.Noodle, RuM = "Чили плюс каламанси равно «чилиманси». Филиппинцы скрестили два слова и получили пожар с лимоном.", EnM = "Chilli plus calamansi makes \"chilimansi\". Filipinos crossed two words and got a fire with lemon.", Mesh = "mini0", Texture = "PancitChilimansi", Kg = 0.059f, Water = 0.35f, Shape = "mini", Brand = "LuckyMi", Kcal = 300f, Ru = "Лапша «Лаки Ми Пансит Чилиманси»", En = "Lucky Mi Pancit Chilimansi noodles", RuF = "острая, с каламанси, без бульона", EnF = "hot, with calamansi, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a84a1a" },
        new Def { Id = "PancitChilimansiHot", Kind = Kind.Brewed, RuM = "Остро и кисло в одной вилке. Глаза щиплет, скулы сводит, жить хочется. Редкий набор для этих мест.", EnM = "Hot and sour on one fork. Eyes sting, jaws clench, you want to live. A rare combination in these parts.", Raw = "PancitChilimansi", Mesh = "PlateHot", Texture = "PancitChilimansiHot", Kg = 0.146f, Thirst = -10f, Warm = 1.35f, Shape = "mini", Brand = "LuckyMi", Kcal = 300f, Ru = "Лапша «Лаки Ми Пансит Чилиманси»", En = "Lucky Mi Pancit Chilimansi noodles", RuF = "острая, с каламанси, без бульона", EnF = "hot, with calamansi, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a84a1a" },
