        new Def { Id = "TopBeef", Kind = Kind.Noodle, RuM = "Говядина. Вкус, знакомый каждому, кто хоть раз ждал зарплату.", EnM = "Beef. A taste familiar to anyone who has ever waited for payday.", Mesh = "brick2", Texture = "TopBeef", Kg = 0.087f, Water = 0.4f, Shape = "brick", Brand = "TopRamen", Kcal = 370f, Ru = "Лапша «Топ Рамен Говядина»", En = "Top Ramen Beef noodles", RuF = "американская классика: говядина", EnF = "the American classic: beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "TopBeefHot", Kind = Kind.Brewed, RuM = "Коричневый бульон и квадратный брикет лапши. Кулинарное событие уровня «разогрел», но в метель и это событие.", EnM = "Brown broth and a square block of noodles. A culinary event at the \"heated it up\" level, but in a blizzard that is still an event.", Raw = "TopBeef", Mesh = "BowlHot", Texture = "TopBeefHot", Kg = 0.447f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "TopRamen", Kcal = 370f, Ru = "Лапша «Топ Рамен Говядина»", En = "Top Ramen Beef noodles", RuF = "американская классика: говядина", EnF = "the American classic: beef", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "TopShrimp", Kind = Kind.Noodle, RuM = "Креветка. Розовая пачка, которую берут, когда курица и говядина уже снятся.", EnM = "Shrimp. The pink pack you pick when you already dream of chicken and beef.", Mesh = "brick0", Texture = "TopShrimp", Kg = 0.089f, Water = 0.4f, Shape = "brick", Brand = "TopRamen", Kcal = 360f, Ru = "Лапша «Топ Рамен Креветка»", En = "Top Ramen Shrimp noodles", RuF = "американская классика: креветка", EnF = "the American classic: shrimp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "TopShrimpHot", Kind = Kind.Brewed, RuM = "Розоватый бульон с намёком на море. Намёк тонкий, но после месяца на оленине ловишь его сразу.", EnM = "A pinkish broth with a hint of the sea. A faint hint, but after a month of venison you catch it at once.", Raw = "TopShrimp", Mesh = "BowlHot", Texture = "TopShrimpHot", Kg = 0.449f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "TopRamen", Kcal = 360f, Ru = "Лапша «Топ Рамен Креветка»", En = "Top Ramen Shrimp noodles", RuF = "американская классика: креветка", EnF = "the American classic: shrimp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#e3c98a" },
        new Def { Id = "TopChili", Kind = Kind.Noodle, RuM = "Чили. Американское представление об остроте: громко на пачке, терпимо в миске.", EnM = "Chili. The American idea of heat: loud on the pack, bearable in the bowl.", Mesh = "brick0", Texture = "TopChili", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "TopRamen", Kcal = 390f, Ru = "Лапша «Топ Рамен Чили»", En = "Top Ramen Chili noodles", RuF = "американская классика: перец чили", EnF = "the American classic: chili", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "TopChiliHot", Kind = Kind.Brewed, RuM = "Красноватый бульон с перцем. Острый ровно настолько, чтобы почувствовать нос. Он, оказывается, ещё на месте.", EnM = "A reddish broth with pepper. Hot enough to feel your nose. It turns out it is still there.", Raw = "TopChili", Mesh = "BowlHot", Texture = "TopChiliHot", Kg = 0.448f, Thirst = 18f, Warm = 1.8f, Shape = "brick", Brand = "TopRamen", Kcal = 390f, Ru = "Лапша «Топ Рамен Чили»", En = "Top Ramen Chili noodles", RuF = "американская классика: перец чили", EnF = "the American classic: chili", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "Chapaguri", Kind = Kind.Noodle, RuM = "Та самая «рам-дон» из кино про подвал: две лапши в одной пачке, без бульона. Стейк ищи сам.", EnM = "The very \"ram-don\" from the film about the basement: two noodles in one pack, no broth. Find the steak yourself.", Mesh = "kpack0", Texture = "Chapaguri", Kg = 0.125f, Water = 0.55f, Shape = "kpack", Brand = "Chapaguri", Kcal = 520f, Ru = "Лапша «Чапагури»", En = "Chapaguri noodles", RuF = "та самая «рам-дон» из кино про подвал: две лапши в одной пачке, без бульона. Стейк ищи сам", EnF = "the very \"ram-don\" from the film about the basement: two noodles in one pack, no broth. Find the steak yourself", Spicy = 1, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "ChapaguriHot", Kind = Kind.Brewed, RuM = "Две лапши смешались в одну, чёрную и густую. В кино сверху клали мраморную говядину. У вас есть оленина, и это не хуже.", EnM = "Two noodles blended into one, black and thick. In the film they topped it with marbled beef. You have venison, and it is no worse.", Raw = "Chapaguri", Mesh = "PotHot", Texture = "ChapaguriHot", Kg = 0.263f, Thirst = -8f, Warm = 1.05f, Shape = "kpack", Brand = "Chapaguri", Kcal = 520f, Ru = "Лапша «Чапагури»", En = "Chapaguri noodles", RuF = "та самая «рам-дон» из кино про подвал: две лапши в одной пачке, без бульона. Стейк ищи сам", EnF = "the very \"ram-don\" from the film about the basement: two noodles in one pack, no broth. Find the steak yourself", Spicy = 1, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "ChapaguriSpicy", Kind = Kind.Noodle, RuM = "Рам-дон поострее, без бульона. Богатые соседи сверху такое не едят.", EnM = "A hotter ram-don, no broth. The rich folks upstairs do not eat this.", Mesh = "kpack0", Texture = "ChapaguriSpicy", Kg = 0.12f, Water = 0.55f, Shape = "kpack", Brand = "Chapaguri", Kcal = 530f, Ru = "Лапша «Чапагури Острый»", En = "Chapaguri Spicy noodles", RuF = "рам-дон поострее, без бульона. Богатые соседи сверху такое не едят", EnF = "a hotter ram-don, no broth. The rich folks upstairs do not eat this", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#3a140c" },
        new Def { Id = "ChapaguriSpicyHot", Kind = Kind.Brewed, RuM = "Чёрный соус с красным подтекстом. Внизу, в подвале, такое любили, а подвал на острове самое тёплое место.", EnM = "A black sauce with a red undertone. Down in the basement they loved this, and on the island a basement is the warmest place.", Raw = "ChapaguriSpicy", Mesh = "PotHot", Texture = "ChapaguriSpicyHot", Kg = 0.258f, Thirst = -12f, Warm = 1.65f, Shape = "kpack", Brand = "Chapaguri", Kcal = 530f, Ru = "Лапша «Чапагури Острый»", En = "Chapaguri Spicy noodles", RuF = "рам-дон поострее, без бульона. Богатые соседи сверху такое не едят", EnF = "a hotter ram-don, no broth. The rich folks upstairs do not eat this", Spicy = 3, Dry = true, Fx = "heartburn", Broth = "#3a140c" },
        new Def { Id = "ChapaguriCup", Kind = Kind.Noodle, RuM = "Рам-дон в стакане. Режиссёр получил за фильм «Оскар», лапша получила стакан. Каждому своё.", EnM = "Ram-don in a cup. The director got an Oscar for the film, the noodles got a cup. To each their own.", Mesh = "bigcup", Texture = "ChapaguriCup", Kg = 0.096f, Water = 0.5f, Shape = "bigcup", Brand = "Chapaguri", Kcal = 470f, Ru = "Лапша «Чапагури» в большом стакане", En = "Chapaguri big cup", RuF = "рам-дон в стакане, без бульона", EnF = "ram-don in a cup, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "ChapaguriCupHot", Kind = Kind.Brewed, RuM = "Густая чёрная лапша прямо в стакане. Есть её полагается быстро, пока хозяева дома не вернулись. Тут уже не вернутся.", EnM = "Thick black noodles right in the cup. You are meant to eat it fast, before the owners of the house return. Here they will not.", Raw = "ChapaguriCup", Mesh = "bigcupHot", Texture = "ChapaguriCup", Kg = 0.221f, Thirst = -8f, Warm = 1.05f, Shape = "bigcup", Brand = "Chapaguri", Kcal = 470f, Ru = "Лапша «Чапагури» в большом стакане", En = "Chapaguri big cup", RuF = "рам-дон в стакане, без бульона", EnF = "ram-don in a cup, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#2b1a12" },
        new Def { Id = "CheeseRamyun", Kind = Kind.Noodle, RuM = "Рамён с пакетиком сырного порошка. Сыр жёлтый, как школьный автобус, и такой же настоящий, как автобус на острове.", EnM = "Ramyun with a sachet of cheese powder. The cheese is as yellow as a school bus and as real as a bus on the island.", Mesh = "kpack2", Texture = "CheeseRamyun", Kg = 0.125f, Water = 0.55f, Shape = "kpack", Brand = "CheeseR", Kcal = 490f, Ru = "Лапша «Чиз Рамён»", En = "Cheese Ramyun noodles", RuF = "острый бульон с пакетиком сырного порошка", EnF = "a spicy broth with a sachet of cheese powder", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#f2b73a" },
        new Def { Id = "CheeseRamyunHot", Kind = Kind.Brewed, RuM = "Острый бульон помутнел от сыра и подобрел. Корейские школьники едят это после уроков, ваш урок сегодня был про волков.", EnM = "The spicy broth has gone cloudy with cheese and kinder for it. Korean kids eat this after class, your class today was on wolves.", Raw = "CheeseRamyun", Mesh = "PotHot", Texture = "CheeseRamyunHot", Kg = 0.62f, Thirst = 21f, Warm = 1.4f, Shape = "kpack", Brand = "CheeseR", Kcal = 490f, Ru = "Лапша «Чиз Рамён»", En = "Cheese Ramyun noodles", RuF = "острый бульон с пакетиком сырного порошка", EnF = "a spicy broth with a sachet of cheese powder", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#f2b73a" },
        new Def { Id = "CheeseRamyunFire", Kind = Kind.Noodle, RuM = "Сыр и двойной перец. Сыр обещал всех помирить и не справился.", EnM = "Cheese and double chilli. The cheese promised to make peace and failed.", Mesh = "kpack1", Texture = "CheeseRamyunFire", Kg = 0.124f, Water = 0.55f, Shape = "kpack", Brand = "CheeseR", Kcal = 530f, Ru = "Лапша «Чиз Рамён Острый»", En = "Cheese Ramyun Spicy noodles", RuF = "сыр и двойной перец", EnF = "cheese and double chilli", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#d8641e" },
        new Def { Id = "CheeseRamyunFireHot", Kind = Kind.Brewed, RuM = "Красно-жёлтый бульон, как пламя в печке. Смотреть приятно, совать туда язык было смело.", EnM = "A red and yellow broth, like the flame in a stove. Nice to look at, sticking your tongue in was brave.", Raw = "CheeseRamyunFire", Mesh = "PotHot", Texture = "CheeseRamyunFireHot", Kg = 0.619f, Thirst = 15f, Warm = 2.2f, Shape = "kpack", Brand = "CheeseR", Kcal = 530f, Ru = "Лапша «Чиз Рамён Острый»", En = "Cheese Ramyun Spicy noodles", RuF = "сыр и двойной перец", EnF = "cheese and double chilli", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#d8641e" },
        new Def { Id = "CheeseRamyunBowl", Kind = Kind.Noodle, RuM = "Сырный рамён в большой миске. Большая миска сыра на острове без единой коровы: чудо логистики.", EnM = "Cheese ramyun in a big bowl. A big bowl of cheese on an island without a single cow: a wonder of logistics.", Mesh = "kbowl", Texture = "CheeseRamyunBowl", Kg = 0.11f, Water = 0.5f, Shape = "kbowl", Brand = "CheeseR", Kcal = 450f, Ru = "Лапша «Чиз Рамён» в большой миске", En = "Cheese Ramyun big bowl", RuF = "сырный рамён в миске", EnF = "cheese ramyun in a bowl", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#f2b73a" },
        new Def { Id = "CheeseRamyunBowlHot", Kind = Kind.Brewed, RuM = "Сыр тянется нитями от миски до рта. Нити тёплые, жёлтые и не рвутся. В отличие от ваших шнурков.", EnM = "The cheese stretches in strings from bowl to mouth. The strings are warm, yellow and do not snap. Unlike your bootlaces.", Raw = "CheeseRamyunBowl", Mesh = "kbowlHot", Texture = "CheeseRamyunBowl", Kg = 0.56f, Thirst = 21f, Warm = 1.4f, Shape = "kbowl", Brand = "CheeseR", Kcal = 450f, Ru = "Лапша «Чиз Рамён» в большой миске", En = "Cheese Ramyun big bowl", RuF = "сырный рамён в миске", EnF = "cheese ramyun in a bowl", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#f2b73a" },
        new Def { Id = "NagasakiJjamppong", Kind = Kind.Noodle, RuM = "Белый бульон с морепродуктами и зелёным перцем: выглядит невинно, жжётся честно.", EnM = "A white seafood broth with green chilli: looks innocent, burns honestly.", Mesh = "kpack0", Texture = "NagasakiJjamppong", Kg = 0.125f, Water = 0.55f, Shape = "kpack", Brand = "Nagasaki", Kcal = 520f, Ru = "Лапша «Нагасаки Чамппон»", En = "Nagasaki Jjamppong noodles", RuF = "белый бульон с морепродуктами и зелёным перцем: выглядит невинно, жжётся честно", EnF = "a white seafood broth with green chilli: looks innocent, burns honestly", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eadcc0" },
        new Def { Id = "NagasakiJjamppongHot", Kind = Kind.Brewed, RuM = "Белый бульон выглядит как молоко с креветками. Первый глоток объясняет, что молоко тут ни при чём.", EnM = "The white broth looks like milk with shrimp. The first sip explains that milk has nothing to do with it.", Raw = "NagasakiJjamppong", Mesh = "PotHot", Texture = "NagasakiJjamppongHot", Kg = 0.62f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Nagasaki", Kcal = 520f, Ru = "Лапша «Нагасаки Чамппон»", En = "Nagasaki Jjamppong noodles", RuF = "белый бульон с морепродуктами и зелёным перцем: выглядит невинно, жжётся честно", EnF = "a white seafood broth with green chilli: looks innocent, burns honestly", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eadcc0" },
        new Def { Id = "NagasakiCup", Kind = Kind.Noodle, RuM = "Белый чамппон в стакане. Белое на белом снегу: не уроните, не найдёте.", EnM = "White jjamppong in a cup. White on white snow: drop it and you will never find it.", Mesh = "tallcup", Texture = "NagasakiCup", Kg = 0.078f, Water = 0.35f, Shape = "tallcup", Brand = "Nagasaki", Kcal = 360f, Ru = "Лапша «Нагасаки Чамппон» в стакане", En = "Nagasaki Jjamppong cup", RuF = "белый острый бульон с морепродуктами", EnF = "a white spicy seafood broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eadcc0" },
        new Def { Id = "NagasakiCupHot", Kind = Kind.Brewed, RuM = "Бульон светлый, перец зелёный, оба притворяются безобидными. На острове так делает всё, что хочет вас съесть.", EnM = "The broth is pale, the pepper green, both pretend to be harmless. On the island so does everything that wants to eat you.", Raw = "NagasakiCup", Mesh = "tallcupHot", Texture = "NagasakiCup", Kg = 0.393f, Thirst = 18f, Warm = 1.8f, Shape = "tallcup", Brand = "Nagasaki", Kcal = 360f, Ru = "Лапша «Нагасаки Чамппон» в стакане", En = "Nagasaki Jjamppong cup", RuF = "белый острый бульон с морепродуктами", EnF = "a white spicy seafood broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#eadcc0" },
        new Def { Id = "Sutah", Kind = Kind.Noodle, RuM = "Лапша «ручной вытяжки», которую вытягивала машина. Руки у машины, надо признать, хорошие.", EnM = "\"Hand-pulled\" noodles pulled by a machine. The machine, to be fair, has good hands.", Mesh = "kpack1", Texture = "Sutah", Kg = 0.118f, Water = 0.55f, Shape = "kpack", Brand = "Sutah", Kcal = 540f, Ru = "Лапша «Сута Рамён»", En = "Sutah Ramyun noodles", RuF = "упругая лапша «ручной вытяжки» в остром говяжьем бульоне", EnF = "springy \"hand-pulled\" noodles in a spicy beef broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "SutahHot", Kind = Kind.Brewed, RuM = "Упругая лапша в остром говяжьем бульоне. Пружинит на зубах, как ветка под снегом. Только ветка потом бьёт по лицу.", EnM = "Springy noodles in spicy beef broth. They bounce on the teeth like a branch under snow. Only the branch then hits you in the face.", Raw = "Sutah", Mesh = "PotHot", Texture = "SutahHot", Kg = 0.613f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Sutah", Kcal = 540f, Ru = "Лапша «Сута Рамён»", En = "Sutah Ramyun noodles", RuF = "упругая лапша «ручной вытяжки» в остром говяжьем бульоне", EnF = "springy \"hand-pulled\" noodles in a spicy beef broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "SutahBowl", Kind = Kind.Noodle, RuM = "Большая миска с упругой лапшой. Тянуть её вручную не придётся, тянуть будете санки с дровами.", EnM = "A big bowl of springy noodles. No need to pull them by hand, you will be pulling a sled of firewood instead.", Mesh = "kbowl", Texture = "SutahBowl", Kg = 0.104f, Water = 0.5f, Shape = "kbowl", Brand = "Sutah", Kcal = 500f, Ru = "Лапша «Сута Рамён» в большой миске", En = "Sutah Ramyun big bowl", RuF = "острый говяжий бульон, большая миска", EnF = "spicy beef broth, a big bowl", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "SutahBowlHot", Kind = Kind.Brewed, RuM = "Красный говяжий бульон до краёв. Миску обхватываешь ладонями и минуту просто сидишь. Это тоже часть рецепта.", EnM = "Red beef broth to the brim. You wrap your palms around the bowl and just sit for a minute. That is part of the recipe too.", Raw = "SutahBowl", Mesh = "kbowlHot", Texture = "SutahBowl", Kg = 0.554f, Thirst = 18f, Warm = 1.8f, Shape = "kbowl", Brand = "Sutah", Kcal = 500f, Ru = "Лапша «Сута Рамён» в большой миске", En = "Sutah Ramyun big bowl", RuF = "острый говяжий бульон, большая миска", EnF = "spicy beef broth, a big bowl", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c4381c" },
        new Def { Id = "Rabokki", Kind = Kind.Noodle, RuM = "Рамён плюс токпокки, уличная еда корейских школьников. Сладкая, острая и красная, как нос на морозе.", EnM = "Ramyun plus tteokbokki, the street food of Korean schoolkids. Sweet, hot and red, like a nose in the frost.", Mesh = "bigcup", Texture = "Rabokki", Kg = 0.096f, Water = 0.5f, Shape = "bigcup", Brand = "Rabokki", Kcal = 460f, Ru = "Лапша «Рабокки» в большом стакане", En = "Rabokki big cup", RuF = "рамён в сладко-остром соусе от токпокки, без бульона", EnF = "ramyun in sweet and hot tteokbokki sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#b8281a" },
        new Def { Id = "RabokkiHot", Kind = Kind.Brewed, RuM = "Липкий красный соус, лапша блестит. После школы в Сеуле такое едят стоя у ларька. Вы тоже стоите, садиться холодно.", EnM = "Sticky red sauce, glossy noodles. After school in Seoul they eat this standing at a stall. You stand too, sitting is cold.", Raw = "Rabokki", Mesh = "bigcupHot", Texture = "Rabokki", Kg = 0.221f, Thirst = -10f, Warm = 1.35f, Shape = "bigcup", Brand = "Rabokki", Kcal = 460f, Ru = "Лапша «Рабокки» в большом стакане", En = "Rabokki big cup", RuF = "рамён в сладко-остром соусе от токпокки, без бульона", EnF = "ramyun in sweet and hot tteokbokki sauce, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#b8281a" },
        new Def { Id = "RabokkiCheese", Kind = Kind.Noodle, RuM = "Токпокки под сыром. Сыр придумали класть, чтобы было не так остро. Стало вкуснее, а остро осталось.", EnM = "Tteokbokki under cheese. The cheese was added to make it less hot. It got tastier, the heat stayed.", Mesh = "bigcup", Texture = "RabokkiCheese", Kg = 0.103f, Water = 0.5f, Shape = "bigcup", Brand = "Rabokki", Kcal = 470f, Ru = "Лапша «Рабокки Сырный» в большом стакане", En = "Rabokki Cheese big cup", RuF = "соус токпокки под сырной шапкой, без бульона", EnF = "tteokbokki sauce under a cap of cheese, no broth", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#cf6a28" },
        new Def { Id = "RabokkiCheeseHot", Kind = Kind.Brewed, RuM = "Сырная шапка на красном соусе. Шапка на острове главная вещь, даже если она из сыра.", EnM = "A cap of cheese on red sauce. On the island a cap is the most important thing, even one made of cheese.", Raw = "RabokkiCheese", Mesh = "bigcupHot", Texture = "RabokkiCheese", Kg = 0.228f, Thirst = -10f, Warm = 1.35f, Shape = "bigcup", Brand = "Rabokki", Kcal = 470f, Ru = "Лапша «Рабокки Сырный» в большом стакане", En = "Rabokki Cheese big cup", RuF = "соус токпокки под сырной шапкой, без бульона", EnF = "tteokbokki sauce under a cap of cheese, no broth", Spicy = 2, Dry = true, Fx = "appetite", Broth = "#cf6a28" },
        new Def { Id = "RabokkiRose", Kind = Kind.Noodle, RuM = "Розе: соус токпокки развели сливками. Получился цвет заката перед метелью.", EnM = "Rosé: tteokbokki sauce thinned with cream. The result is the colour of a sunset before a blizzard.", Mesh = "bigcup", Texture = "RabokkiRose", Kg = 0.1f, Water = 0.5f, Shape = "bigcup", Brand = "Rabokki", Kcal = 460f, Ru = "Лапша «Рабокки Розе» в большом стакане", En = "Rabokki Rose big cup", RuF = "соус токпокки со сливками, без бульона", EnF = "tteokbokki sauce with cream, no broth", Spicy = 1, Dry = true, Fx = "appetite", Broth = "#e08a6a" },
        new Def { Id = "RabokkiRoseHot", Kind = Kind.Brewed, RuM = "Розовый, мягкий и сладковатый соус. Закат перед метелью красивый, метель потом злая, а тут обошлось.", EnM = "A pink, soft, sweetish sauce. The sunset before a blizzard is lovely, the blizzard is vicious, but this time you got away.", Raw = "RabokkiRose", Mesh = "bigcupHot", Texture = "RabokkiRose", Kg = 0.225f, Thirst = -8f, Warm = 1.05f, Shape = "bigcup", Brand = "Rabokki", Kcal = 460f, Ru = "Лапша «Рабокки Розе» в большом стакане", En = "Rabokki Rose big cup", RuF = "соус токпокки со сливками, без бульона", EnF = "tteokbokki sauce with cream, no broth", Spicy = 1, Dry = true, Fx = "appetite", Broth = "#e08a6a" },
