        new Def { Id = "MiyeokHot", Kind = Kind.Brewed, RuM = "Тёмные водоросли в светлом бульоне. Когда у вас день рождения, уже не вспомнить. Пусть будет сегодня.", EnM = "Dark seaweed in a pale broth. You can no longer recall when your birthday is. Let it be today.", Raw = "Miyeok", Mesh = "PotHot", Texture = "MiyeokHot", Kg = 0.612f, Thirst = 24f, Warm = 1.0f, Shape = "kpack", Brand = "Miyeok", Kcal = 510f, Ru = "Лапша «Миёк Рамён»", En = "Miyeok Ramyun noodles", RuF = "корейский суп из водорослей, который варят на день рождения. Праздник посреди метели", EnF = "the Korean seaweed soup cooked for birthdays. A party in the middle of a blizzard", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b8a878" },
        new Def { Id = "Budae", Kind = Kind.Noodle, RuM = "«армейское рагу»: острый бульон, колбаса, фасоль и сыр. Всё, что нашлось на складе.", EnM = "\"army stew\": spicy broth, sausage, beans and cheese. Everything the depot had.", Mesh = "kpack0", Texture = "Budae", Kg = 0.127f, Water = 0.55f, Shape = "kpack", Brand = "Budae", Kcal = 520f, Ru = "Лапша «Пудэ Ччигэ»", En = "Budae Jjigae noodles", RuF = "«армейское рагу»: острый бульон, колбаса, фасоль и сыр. Всё, что нашлось на складе", EnF = "\"army stew\": spicy broth, sausage, beans and cheese. Everything the depot had", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b83a1c" },
        new Def { Id = "BudaeHot", Kind = Kind.Brewed, RuM = "Колбаса, фасоль, сыр и перец в одном бульоне. Блюдо придумали в голодные годы из того, что было. Вы понимаете его как никто.", EnM = "Sausage, beans, cheese and chilli in one broth. The dish was invented in hungry years from whatever there was. You understand it like nobody else.", Raw = "Budae", Mesh = "PotHot", Texture = "BudaeHot", Kg = 0.622f, Thirst = 18f, Warm = 1.8f, Shape = "kpack", Brand = "Budae", Kcal = 520f, Ru = "Лапша «Пудэ Ччигэ»", En = "Budae Jjigae noodles", RuF = "«армейское рагу»: острый бульон, колбаса, фасоль и сыр. Всё, что нашлось на складе", EnF = "\"army stew\": spicy broth, sausage, beans and cheese. Everything the depot had", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b83a1c" },
        new Def { Id = "BudaeBowl", Kind = Kind.Noodle, RuM = "Армейское рагу в большой миске. Устав не требует доедать, но голод требует.", EnM = "Army stew in a big bowl. Regulations do not order you to finish it, hunger does.", Mesh = "kbowl", Texture = "BudaeBowl", Kg = 0.116f, Water = 0.5f, Shape = "kbowl", Brand = "Budae", Kcal = 490f, Ru = "Лапша «Пудэ Ччигэ» в большой миске", En = "Budae Jjigae big bowl", RuF = "армейское рагу в большой миске", EnF = "army stew in a big bowl", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b83a1c" },
        new Def { Id = "BudaeBowlHot", Kind = Kind.Brewed, RuM = "Миска, в которой есть всё сразу. Примерно как ваш рюкзак, только это можно есть и оно не весит тридцать кило.", EnM = "A bowl that has everything at once. Much like your pack, only this is edible and does not weigh thirty kilos.", Raw = "BudaeBowl", Mesh = "kbowlHot", Texture = "BudaeBowl", Kg = 0.566f, Thirst = 18f, Warm = 1.8f, Shape = "kbowl", Brand = "Budae", Kcal = 490f, Ru = "Лапша «Пудэ Ччигэ» в большой миске", En = "Budae Jjigae big bowl", RuF = "армейское рагу в большой миске", EnF = "army stew in a big bowl", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b83a1c" },
        new Def { Id = "NaengMul", Kind = Kind.Noodle, RuM = "Гречневая лапша для ледяного бульона. Лёд на Великом Медведе бесплатный, но заваривают её всё же горячей.", EnM = "Buckwheat noodles for an icy broth. Ice is free on Great Bear, but you still brew them hot.", Mesh = "long0", Texture = "NaengMul", Kg = 0.095f, Water = 0.45f, Shape = "long", Brand = "Naeng", Kcal = 330f, Ru = "Лапша «Нэнмён Муль»", En = "Naengmyeon Mul noodles", RuF = "гречневая лапша для ледяного бульона. Лёд на Великом Медведе бесплатный, но заваривают её всё же горячей", EnF = "buckwheat noodles for an icy broth. Ice is free on Great Bear, but you still brew them hot", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d8cfae" },
        new Def { Id = "NaengMulHot", Kind = Kind.Brewed, RuM = "Гречневая лапша в горячем бульоне вопреки традиции. Традиция велит класть лёд, но традиция не ночевала в сугробе.", EnM = "Buckwheat noodles in hot broth, against tradition. Tradition says add ice, but tradition never spent a night in a snowdrift.", Raw = "NaengMul", Mesh = "PotHot", Texture = "NaengMulHot", Kg = 0.5f, Thirst = 24f, Warm = 1.0f, Shape = "long", Brand = "Naeng", Kcal = 330f, Ru = "Лапша «Нэнмён Муль»", En = "Naengmyeon Mul noodles", RuF = "гречневая лапша для ледяного бульона. Лёд на Великом Медведе бесплатный, но заваривают её всё же горячей", EnF = "buckwheat noodles for an icy broth. Ice is free on Great Bear, but you still brew them hot", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#d8cfae" },
