        new Def { Id = "MokoTanmen", Kind = Kind.Noodle, RuM = "Мисо с огненным тофу: самый острый стакан Японии. Крышку открывают с уважением.", EnM = "Miso with fiery tofu: the hottest cup in Japan. Open the lid with respect.", Mesh = "tallcup", Texture = "MokoTanmen", Kg = 0.071f, Water = 0.35f, Shape = "tallcup", Brand = "Moko", Kcal = 330f, Ru = "Лапша «Моко Танмэн» в стакане", En = "Moko Tanmen cup", RuF = "мисо с огненным тофу: самый острый стакан Японии. Крышку открывают с уважением", EnF = "miso with fiery tofu: the hottest cup in Japan. Open the lid with respect", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#b8401c" },
