        new Def { Id = "MokoHokkyoku", Kind = Kind.Noodle, RuM = "«Северный полюс»: ещё острее. Название подходит к погоде, вкус нет.", EnM = "\"North Pole\": hotter still. The name suits the weather, the taste does not.", Mesh = "tallcup", Texture = "MokoHokkyoku", Kg = 0.076f, Water = 0.35f, Shape = "tallcup", Brand = "Moko", Kcal = 350f, Ru = "Лапша «Моко Танмэн Хоккёку» в стакане", En = "Moko Tanmen Hokkyoku cup", RuF = "«Северный полюс»: ещё острее. Название подходит к погоде, вкус нет", EnF = "\"North Pole\": hotter still. The name suits the weather, the taste does not", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#8e1408" },
        new Def { Id = "MokoHokkyokuHot", Kind = Kind.Brewed, RuM = "«Северный полюс» в стакане, красный и кипящий. На настоящем полюсе сейчас теплее, чем у вас за дверью, и спокойнее, чем во рту.", EnM = "\"North Pole\" in a cup, red and boiling. The real pole is warmer right now than your doorstep and calmer than your mouth.", Raw = "MokoHokkyoku", Mesh = "tallcupHot", Texture = "MokoHokkyoku", Kg = 0.391f, Thirst = 12f, Warm = 2.6f, Shape = "tallcup", Brand = "Moko", Kcal = 350f, Ru = "Лапша «Моко Танмэн Хоккёку» в стакане", En = "Moko Tanmen Hokkyoku cup", RuF = "«Северный полюс»: ещё острее. Название подходит к погоде, вкус нет", EnF = "\"North Pole\": hotter still. The name suits the weather, the taste does not", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#8e1408" },
