        new Def { Id = "CupStarMiso", Kind = Kind.Noodle, RuM = "Мисо в стакане со звездой. Срок годности вышел, когда погас свет, но мисо и так уже ферментировано.", EnM = "Miso in a cup with a star. The best-before date passed when the lights went out, but miso is fermented already.", Mesh = "cup", Texture = "CupStarMiso", Kg = 0.067f, Water = 0.3f, Shape = "cup", Brand = "CupStar", Kcal = 350f, Ru = "Лапша «Кап Стар Мисо» в стакане", En = "Cup Star Miso cup", RuF = "бульон на мисо", EnF = "miso broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "CupStarMisoHot", Kind = Kind.Brewed, RuM = "Мутный золотистый бульон. Тёплый и немного сладкий. Звезда на стакане подмигивает, хотя, возможно, это сияние.", EnM = "A cloudy golden broth. Warm and a little sweet. The star on the cup winks, though that may be the aurora.", Raw = "CupStarMiso", Mesh = "cupHot", Texture = "CupStarMiso", Kg = 0.337f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "CupStar", Kcal = 350f, Ru = "Лапша «Кап Стар Мисо» в стакане", En = "Cup Star Miso cup", RuF = "бульон на мисо", EnF = "miso broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "CupStarTonkotsu", Kind = Kind.Noodle, RuM = "Свиной бульон под звездой. Свинья, звезда и стакан: басня, а не обед.", EnM = "Pork broth under a star. A pig, a star and a cup: a fable, not a lunch.", Mesh = "cup", Texture = "CupStarTonkotsu", Kg = 0.074f, Water = 0.3f, Shape = "cup", Brand = "CupStar", Kcal = 330f, Ru = "Лапша «Кап Стар Тонкоцу» в стакане", En = "Cup Star Tonkotsu cup", RuF = "белый свиной бульон", EnF = "white pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "CupStarTonkotsuHot", Kind = Kind.Brewed, RuM = "Белый жирный бульон. Обжигает губы, греет грудь, оседает в животе приятной тяжестью, как хороший запас дров.", EnM = "A white, rich broth. It burns the lips, warms the chest and settles in the belly with a pleasant weight, like a good stock of firewood.", Raw = "CupStarTonkotsu", Mesh = "cupHot", Texture = "CupStarTonkotsu", Kg = 0.344f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "CupStar", Kcal = 330f, Ru = "Лапша «Кап Стар Тонкоцу» в стакане", En = "Cup Star Tonkotsu cup", RuF = "белый свиной бульон", EnF = "white pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "CupStarShio", Kind = Kind.Noodle, RuM = "Лёгкий солёный бульон. Соль на острове достать трудно, а тут она уже внутри.", EnM = "A light salt broth. Salt is hard to come by on the island, and here it is already inside.", Mesh = "cup", Texture = "CupStarShio", Kg = 0.069f, Water = 0.3f, Shape = "cup", Brand = "CupStar", Kcal = 330f, Ru = "Лапша «Кап Стар Сио» в стакане", En = "Cup Star Shio cup", RuF = "лёгкий солёный бульон", EnF = "a light salt broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#ecd9a0" },
        new Def { Id = "CupStarShioHot", Kind = Kind.Brewed, RuM = "Прозрачный бульон с кунжутом. Лёгкий, как рюкзак в первый день. Наслаждайтесь, оба эти ощущения недолгие.", EnM = "A clear broth with sesame. As light as your pack on the first day. Enjoy it, neither feeling lasts.", Raw = "CupStarShio", Mesh = "cupHot", Texture = "CupStarShio", Kg = 0.339f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "CupStar", Kcal = 330f, Ru = "Лапша «Кап Стар Сио» в стакане", En = "Cup Star Shio cup", RuF = "лёгкий солёный бульон", EnF = "a light salt broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#ecd9a0" },
        new Def { Id = "SuperCupShoyu", Kind = Kind.Noodle, RuM = "Полторы порции. Кто-то в Японии честно посчитал, что одной порции взрослому человеку мало.", EnM = "One and a half helpings. Someone in Japan honestly worked out that one helping is not enough for an adult.", Mesh = "bigcup", Texture = "SuperCupShoyu", Kg = 0.102f, Water = 0.5f, Shape = "bigcup", Brand = "SuperCup", Kcal = 490f, Ru = "Лапша «Супер Кап 1.5 Сёю» в большом стакане", En = "Super Cup 1.5 Shoyu big cup", RuF = "полторы порции в соевом бульоне", EnF = "one and a half helpings in soy broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "SuperCupShoyuHot", Kind = Kind.Brewed, RuM = "Стакан в полтора раза больше обычного. Соевый бульон в нём не кончается дольше, чем метель за окном. Почти.", EnM = "A cup half as big again as usual. The soy broth in it outlasts the blizzard outside. Almost.", Raw = "SuperCupShoyu", Mesh = "bigcupHot", Texture = "SuperCupShoyu", Kg = 0.552f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "SuperCup", Kcal = 490f, Ru = "Лапша «Супер Кап 1.5 Сёю» в большом стакане", En = "Super Cup 1.5 Shoyu big cup", RuF = "полторы порции в соевом бульоне", EnF = "one and a half helpings in soy broth", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "SuperCupTonkotsu", Kind = Kind.Noodle, RuM = "Полторы порции свиного бульона. Половинку добавили специально для тех, кто сегодня тащил оленя.", EnM = "One and a half helpings of pork broth. The extra half was added for those who hauled a deer today.", Mesh = "bigcup", Texture = "SuperCupTonkotsu", Kg = 0.094f, Water = 0.5f, Shape = "bigcup", Brand = "SuperCup", Kcal = 470f, Ru = "Лапша «Супер Кап 1.5 Тонкоцу» в большом стакане", En = "Super Cup 1.5 Tonkotsu big cup", RuF = "полторы порции в свином бульоне", EnF = "one and a half helpings in pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "SuperCupTonkotsuHot", Kind = Kind.Brewed, RuM = "Белый бульон в огромном стакане. Последний глоток уже чуть тёплый, но вы всё равно его допьёте. Тут ничего не выливают.", EnM = "White broth in a huge cup. The last sip is barely warm, but you will drink it anyway. Nothing is poured away here.", Raw = "SuperCupTonkotsu", Mesh = "bigcupHot", Texture = "SuperCupTonkotsu", Kg = 0.544f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "SuperCup", Kcal = 470f, Ru = "Лапша «Супер Кап 1.5 Тонкоцу» в большом стакане", En = "Super Cup 1.5 Tonkotsu big cup", RuF = "полторы порции в свином бульоне", EnF = "one and a half helpings in pork broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "SuperCupMiso", Kind = Kind.Noodle, RuM = "Полторы порции мисо. Математика простая: больше стакан, меньше причин выходить на улицу.", EnM = "One and a half helpings of miso. Simple maths: a bigger cup, fewer reasons to go outside.", Mesh = "bigcup", Texture = "SuperCupMiso", Kg = 0.097f, Water = 0.5f, Shape = "bigcup", Brand = "SuperCup", Kcal = 450f, Ru = "Лапша «Супер Кап 1.5 Мисо» в большом стакане", En = "Super Cup 1.5 Miso big cup", RuF = "полторы порции в мисо", EnF = "one and a half helpings in miso", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "SuperCupMisoHot", Kind = Kind.Brewed, RuM = "Густое мисо, которого хватает на весь вечер у печки. Книга, огонь, стакан. Почти отпуск, если не смотреть в окно.", EnM = "Thick miso that lasts the whole evening by the stove. A book, a fire, a cup. Nearly a holiday, if you do not look out of the window.", Raw = "SuperCupMiso", Mesh = "bigcupHot", Texture = "SuperCupMiso", Kg = 0.547f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "SuperCup", Kcal = 450f, Ru = "Лапша «Супер Кап 1.5 Мисо» в большом стакане", En = "Super Cup 1.5 Miso big cup", RuF = "полторы порции в мисо", EnF = "one and a half helpings in miso", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "Umakacchan", Kind = Kind.Noodle, RuM = "Тонкоцу с острова Кюсю. «Умакаттян» на местном диалекте значит «вкуснятина». Островитяне друг друга поймут.", EnM = "Tonkotsu from the island of Kyushu. \"Umakacchan\" is local dialect for \"yummy\". Islanders will understand each other.", Mesh = "jpack0", Texture = "Umakacchan", Kg = 0.099f, Water = 0.5f, Shape = "jpack", Brand = "Umaka", Kcal = 420f, Ru = "Лапша «Умакаттян»", En = "Umakacchan noodles", RuF = "тонкоцу с острова Кюсю, свиной бульон с ароматным маслом", EnF = "tonkotsu from Kyushu, pork broth with scented oil", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "UmakacchanHot", Kind = Kind.Brewed, RuM = "Свиной бульон с каплей ароматного масла. На Кюсю тепло и растут мандарины. Обидно, но вкусно.", EnM = "Pork broth with a drop of fragrant oil. On Kyushu it is warm and mandarins grow. Unfair, but tasty.", Raw = "Umakacchan", Mesh = "DonburiHot", Texture = "UmakacchanHot", Kg = 0.549f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Umaka", Kcal = 420f, Ru = "Лапша «Умакаттян»", En = "Umakacchan noodles", RuF = "тонкоцу с острова Кюсю, свиной бульон с ароматным маслом", EnF = "tonkotsu from Kyushu, pork broth with scented oil", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "UmakaTakana", Kind = Kind.Noodle, RuM = "Тонкоцу с острой маринованной горчицей. Листья горчицы, а не та, что в тюбике. Тюбик бы тоже пригодился.", EnM = "Tonkotsu with spicy pickled mustard. Mustard greens, not the kind in a tube. A tube would come in handy too.", Mesh = "jpack0", Texture = "UmakaTakana", Kg = 0.101f, Water = 0.5f, Shape = "jpack", Brand = "Umaka", Kcal = 440f, Ru = "Лапша «Умакаттян Караси Такана»", En = "Umakacchan Karashi Takana noodles", RuF = "тонкоцу с острой маринованной горчицей", EnF = "tonkotsu with hot pickled mustard greens", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0b878" },
        new Def { Id = "UmakaTakanaHot", Kind = Kind.Brewed, RuM = "Белый бульон, тёмная зелень, перец. Маринованные листья хрустят и жгутся. Витамины с характером.", EnM = "White broth, dark greens, chilli. The pickled leaves crunch and bite. Vitamins with an attitude.", Raw = "UmakaTakana", Mesh = "DonburiHot", Texture = "UmakaTakanaHot", Kg = 0.551f, Thirst = 18f, Warm = 1.8f, Shape = "jpack", Brand = "Umaka", Kcal = 440f, Ru = "Лапша «Умакаттян Караси Такана»", En = "Umakacchan Karashi Takana noodles", RuF = "тонкоцу с острой маринованной горчицей", EnF = "tonkotsu with hot pickled mustard greens", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0b878" },
        new Def { Id = "GotochiSapporo", Kind = Kind.Noodle, RuM = "Мисо с севера, с кукурузой и маслом. Там тоже знают, что такое зима.", EnM = "Miso from the north with corn and butter. They know winter there too.", Mesh = "jpack2", Texture = "GotochiSapporo", Kg = 0.105f, Water = 0.5f, Shape = "jpack", Brand = "Gotochi", Kcal = 410f, Ru = "Лапша «Гототи Рамен Саппоро Мисо»", En = "Gotochi Ramen Sapporo Miso noodles", RuF = "мисо с севера, с кукурузой и маслом. Там тоже знают, что такое зима", EnF = "miso from the north with corn and butter. They know winter there too", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "GotochiSapporoHot", Kind = Kind.Brewed, RuM = "Мисо, кукуруза и кусочек масла, который тает сверху. Северяне придумали это не от хорошей жизни, и вышло хорошо.", EnM = "Miso, corn and a pat of butter melting on top. Northerners did not invent this out of an easy life, and it came out well.", Raw = "GotochiSapporo", Mesh = "DonburiHot", Texture = "GotochiSapporoHot", Kg = 0.555f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Gotochi", Kcal = 410f, Ru = "Лапша «Гототи Рамен Саппоро Мисо»", En = "Gotochi Ramen Sapporo Miso noodles", RuF = "мисо с севера, с кукурузой и маслом. Там тоже знают, что такое зима", EnF = "miso from the north with corn and butter. They know winter there too", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "GotochiHakodate", Kind = Kind.Noodle, RuM = "Солёный бульон из портового города Хакодатэ. Порт там не замерзает. Хвастаться нехорошо, но они могут.", EnM = "Salt broth from the port city of Hakodate. The harbour there never freezes. Boasting is bad form, but they can afford it.", Mesh = "jpack0", Texture = "GotochiHakodate", Kg = 0.103f, Water = 0.5f, Shape = "jpack", Brand = "Gotochi", Kcal = 450f, Ru = "Лапша «Гототи Рамен Хакодатэ Сио»", En = "Gotochi Ramen Hakodate Shio noodles", RuF = "прозрачный солёный бульон из портового города", EnF = "a clear salt broth from a port town", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "GotochiHakodateHot", Kind = Kind.Brewed, RuM = "Бульон прозрачный, как утро после бури. Тихо, чисто, и на минуту кажется, что всё наладится.", EnM = "A broth as clear as the morning after a storm. Quiet, clean, and for a minute it seems things will work out.", Raw = "GotochiHakodate", Mesh = "DonburiHot", Texture = "GotochiHakodateHot", Kg = 0.553f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Gotochi", Kcal = 450f, Ru = "Лапша «Гототи Рамен Хакодатэ Сио»", En = "Gotochi Ramen Hakodate Shio noodles", RuF = "прозрачный солёный бульон из портового города", EnF = "a clear salt broth from a port town", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#ecd9a0" },
        new Def { Id = "GotochiKitakata", Kind = Kind.Noodle, RuM = "Широкая волнистая лапша из города, где рамен едят на завтрак. На острове завтрак бывает, когда повезёт.", EnM = "Wide wavy noodles from a town where ramen is breakfast. On the island breakfast happens when you are lucky.", Mesh = "jpack2", Texture = "GotochiKitakata", Kg = 0.103f, Water = 0.5f, Shape = "jpack", Brand = "Gotochi", Kcal = 460f, Ru = "Лапша «Гототи Рамен Китаката Сёю»", En = "Gotochi Ramen Kitakata Shoyu noodles", RuF = "соевый бульон и широкая волнистая лапша", EnF = "soy broth and broad wavy noodles", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "GotochiKitakataHot", Kind = Kind.Brewed, RuM = "Волнистая лапша в соевом бульоне. Волны на ней единственные на сто километров: море стоит.", EnM = "Wavy noodles in soy broth. The waves on them are the only ones for a hundred kilometres: the sea stands still.", Raw = "GotochiKitakata", Mesh = "DonburiHot", Texture = "GotochiKitakataHot", Kg = 0.553f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Gotochi", Kcal = 460f, Ru = "Лапша «Гототи Рамен Китаката Сёю»", En = "Gotochi Ramen Kitakata Shoyu noodles", RuF = "соевый бульон и широкая волнистая лапша", EnF = "soy broth and broad wavy noodles", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#8a5a2b" },
        new Def { Id = "GotochiKumamoto", Kind = Kind.Noodle, RuM = "Тонкоцу с чёрным чесночным маслом. Чёрный рамен из Кумамото, края вулканов. Вулкан бы вам сейчас не помешал.", EnM = "Tonkotsu with black garlic oil. Black ramen from Kumamoto, a land of volcanoes. A volcano would not hurt you right now.", Mesh = "jpack0", Texture = "GotochiKumamoto", Kg = 0.094f, Water = 0.5f, Shape = "jpack", Brand = "Gotochi", Kcal = 450f, Ru = "Лапша «Гототи Рамен Кумамото Чёрный»", En = "Gotochi Ramen Kumamoto Black noodles", RuF = "тонкоцу с чёрным маслом жжёного чеснока", EnF = "tonkotsu with black burnt-garlic oil", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#bfa888" },
        new Def { Id = "GotochiKumamotoHot", Kind = Kind.Brewed, RuM = "Чёрное масло расплылось по белому бульону, как полынья на озере. В эту полынью можно и нужно нырять ложкой.", EnM = "Black oil has spread over the white broth like open water on a lake. This is one hole in the ice you should dive into, with a spoon.", Raw = "GotochiKumamoto", Mesh = "DonburiHot", Texture = "GotochiKumamotoHot", Kg = 0.544f, Thirst = 24f, Warm = 1.0f, Shape = "jpack", Brand = "Gotochi", Kcal = 450f, Ru = "Лапша «Гототи Рамен Кумамото Чёрный»", En = "Gotochi Ramen Kumamoto Black noodles", RuF = "тонкоцу с чёрным маслом жжёного чеснока", EnF = "tonkotsu with black burnt-garlic oil", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#bfa888" },
        new Def { Id = "GotsumoriYakisoba", Kind = Kind.Noodle, RuM = "«Гоцумори» значит «с горой». Гора жареной лапши и пакетик майонеза: японцы тоже умеют в калории.", EnM = "\"Gotsumori\" means \"heaped\". A mountain of fried noodles and a sachet of mayo: the Japanese know calories too.", Mesh = "box", Texture = "GotsumoriYakisoba", Kg = 0.135f, Water = 0.5f, Shape = "box", Brand = "Gotsumori", Kcal = 530f, Ru = "Лапша «Гоцумори Якисоба» в коробке", En = "Gotsumori Yakisoba box", RuF = "гора жареной лапши с пакетиком майонеза, без бульона", EnF = "a mountain of fried noodles with a sachet of mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "GotsumoriYakisobaHot", Kind = Kind.Brewed, RuM = "Гора лапши под майонезом. Единственная гора в округе, на которую не надо лезть с верёвкой.", EnM = "A mountain of noodles under mayo. The only mountain around that needs no rope to climb.", Raw = "GotsumoriYakisoba", Mesh = "PlateHot", Texture = "GotsumoriYakisobaHot", Kg = 0.26f, Thirst = -6f, Warm = 0.75f, Shape = "box", Brand = "Gotsumori", Kcal = 530f, Ru = "Лапша «Гоцумори Якисоба» в коробке", En = "Gotsumori Yakisoba box", RuF = "гора жареной лапши с пакетиком майонеза, без бульона", EnF = "a mountain of fried noodles with a sachet of mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#8a4a1c" },
        new Def { Id = "GotsumoriShio", Kind = Kind.Noodle, RuM = "Солёная якисоба с горкой и майонезом. Для тех, кто хочет много и без сладкого соуса.", EnM = "Heaped salt yakisoba with mayo. For those who want a lot and no sweet sauce.", Mesh = "box", Texture = "GotsumoriShio", Kg = 0.131f, Water = 0.5f, Shape = "box", Brand = "Gotsumori", Kcal = 540f, Ru = "Лапша «Гоцумори Сио-якисоба» в коробке", En = "Gotsumori Shio Yakisoba box", RuF = "жареная лапша с солью и майонезом, без бульона", EnF = "fried noodles with salt and mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d8c890" },
        new Def { Id = "GotsumoriShioHot", Kind = Kind.Brewed, RuM = "Светлая лапша, соль, перец, белые полоски майонеза. Выглядит как сугроб, по калориям как медвежья отбивная.", EnM = "Pale noodles, salt, pepper, white stripes of mayo. Looks like a snowdrift, counts like a bear steak.", Raw = "GotsumoriShio", Mesh = "PlateHot", Texture = "GotsumoriShioHot", Kg = 0.256f, Thirst = -6f, Warm = 0.75f, Shape = "box", Brand = "Gotsumori", Kcal = 540f, Ru = "Лапша «Гоцумори Сио-якисоба» в коробке", En = "Gotsumori Shio Yakisoba box", RuF = "жареная лапша с солью и майонезом, без бульона", EnF = "fried noodles with salt and mayo, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d8c890" },
        new Def { Id = "KareUdon", Kind = Kind.Noodle, RuM = "Удон в густом карри. Рубашку после него можно не стирать, а выбрасывать.", EnM = "Udon in thick curry. Do not wash the shirt afterwards, just throw it away.", Mesh = "bowl", Texture = "KareUdon", Kg = 0.095f, Water = 0.45f, Shape = "bowl", Brand = "KareUdon", Kcal = 440f, Ru = "Удон «Карэ Удон» в миске", En = "Kare Udon bowl", RuF = "удон в густом карри. Рубашку после него можно не стирать, а выбрасывать", EnF = "udon in thick curry. Do not wash the shirt afterwards, just throw it away", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "KareUdonHot", Kind = Kind.Brewed, RuM = "Удон в карри, густом, как смола. Брызги летят на куртку и остаются с вами до конца. До чьего, не уточняется.", EnM = "Udon in curry as thick as tar. Splashes land on your jacket and stay with you to the end. Whose end is not specified.", Raw = "KareUdon", Mesh = "bowlHot", Texture = "KareUdon", Kg = 0.5f, Thirst = 21f, Warm = 1.4f, Shape = "bowl", Brand = "KareUdon", Kcal = 440f, Ru = "Удон «Карэ Удон» в миске", En = "Kare Udon bowl", RuF = "удон в густом карри. Рубашку после него можно не стирать, а выбрасывать", EnF = "udon in thick curry. Do not wash the shirt afterwards, just throw it away", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "BaishanBone", Kind = Kind.Noodle, RuM = "«Белый слон». Наваристый бульон на свиной кости. Слонов тут нет, кости найдутся.", EnM = "\"White Elephant\". A rich broth on pork bone. No elephants here, bones can be found.", Mesh = "brick1", Texture = "BaishanBone", Kg = 0.084f, Water = 0.4f, Shape = "brick", Brand = "Baishan", Kcal = 410f, Ru = "Лапша «Байсян Костный бульон»", En = "Baishan Bone Broth noodles", RuF = "наваристый бульон на свиной кости", EnF = "a rich pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "BaishanBoneHot", Kind = Kind.Brewed, RuM = "Густой белый бульон. Китайские рабочие едят его после смены. Ваша смена не кончается, так что ешьте когда получится.", EnM = "A thick white broth. Chinese workers eat it after a shift. Your shift never ends, so eat when you can.", Raw = "BaishanBone", Mesh = "DonburiHot", Texture = "BaishanBoneHot", Kg = 0.444f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Baishan", Kcal = 410f, Ru = "Лапша «Байсян Костный бульон»", En = "Baishan Bone Broth noodles", RuF = "наваристый бульон на свиной кости", EnF = "a rich pork bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#eadcc0" },
        new Def { Id = "BaishanChicken", Kind = Kind.Noodle, RuM = "Курица с грибами шиитаке. Грибы сушёные и терпеливые, они ждали вас в этой пачке несколько лет.", EnM = "Chicken with shiitake mushrooms. The mushrooms are dried and patient, they waited for you in this pack for years.", Mesh = "brick1", Texture = "BaishanChicken", Kg = 0.08f, Water = 0.4f, Shape = "brick", Brand = "Baishan", Kcal = 370f, Ru = "Лапша «Байсян Курица с грибами»", En = "Baishan Chicken Mushroom noodles", RuF = "курица с шиитаке", EnF = "chicken with shiitake", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "BaishanChickenHot", Kind = Kind.Brewed, RuM = "Тёмные шляпки набухли в курином бульоне. Пахнет лесом после дождя. Дождя вы не видели давно, только снег и снег.", EnM = "The dark caps have swollen in the chicken broth. It smells of forest after rain. You have not seen rain for a long time, only snow.", Raw = "BaishanChicken", Mesh = "DonburiHot", Texture = "BaishanChickenHot", Kg = 0.44f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Baishan", Kcal = 370f, Ru = "Лапша «Байсян Курица с грибами»", En = "Baishan Chicken Mushroom noodles", RuF = "курица с шиитаке", EnF = "chicken with shiitake", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "BaishanSpicy", Kind = Kind.Noodle, RuM = "Говядина в остром масле. Белый слон покраснел.", EnM = "Beef in hot oil. The white elephant has turned red.", Mesh = "brick0", Texture = "BaishanSpicy", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "Baishan", Kcal = 410f, Ru = "Лапша «Байсян Острая говядина»", En = "Baishan Spicy Beef noodles", RuF = "говядина в остром масле", EnF = "beef in hot oil", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#a8200e" },
        new Def { Id = "BaishanSpicyHot", Kind = Kind.Brewed, RuM = "Красное масло, тёмный бульон. Пот выступает даже на затылке под шапкой. Шапку всё равно не снимайте.", EnM = "Red oil, dark broth. Sweat comes out even on the back of your head under the hat. Keep the hat on anyway.", Raw = "BaishanSpicy", Mesh = "DonburiHot", Texture = "BaishanSpicyHot", Kg = 0.448f, Thirst = 15f, Warm = 2.2f, Shape = "brick", Brand = "Baishan", Kcal = 410f, Ru = "Лапша «Байсян Острая говядина»", En = "Baishan Spicy Beef noodles", RuF = "говядина в остром масле", EnF = "beef in hot oil", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#a8200e" },
        new Def { Id = "TungICabbage", Kind = Kind.Noodle, RuM = "Говядина с квашеной капустой из старой бочки.", EnM = "Beef with pickled cabbage from an old crock.", Mesh = "big1", Texture = "TungICabbage", Kg = 0.137f, Water = 0.55f, Shape = "big", Brand = "TungI", Kcal = 570f, Ru = "Лапша «Тун-И Квашеная капуста»", En = "Tung-I Pickled Cabbage noodles", RuF = "говядина с квашеной капустой из старой бочки", EnF = "beef with pickled cabbage from an old crock", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b8862a" },
        new Def { Id = "TungICabbageHot", Kind = Kind.Brewed, RuM = "Кислый бульон с говядиной и капустой, которая помнит свою бочку. Бочка у вас на причале тоже есть, но в ней не капуста.", EnM = "A sour broth with beef and cabbage that remembers its barrel. You have a barrel on the pier as well, but there is no cabbage in it.", Raw = "TungICabbage", Mesh = "DonburiHot", Texture = "TungICabbageHot", Kg = 0.632f, Thirst = 18f, Warm = 1.8f, Shape = "big", Brand = "TungI", Kcal = 570f, Ru = "Лапша «Тун-И Квашеная капуста»", En = "Tung-I Pickled Cabbage noodles", RuF = "говядина с квашеной капустой из старой бочки", EnF = "beef with pickled cabbage from an old crock", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#b8862a" },
        new Def { Id = "TungIBeef", Kind = Kind.Noodle, RuM = "Тушёная говядина по-тайваньски. Пачка яркая, как вывеска ночного рынка, которого вам очень не хватает.", EnM = "Taiwanese stewed beef. The pack is as bright as a night market sign, and you miss night markets badly.", Mesh = "big1", Texture = "TungIBeef", Kg = 0.137f, Water = 0.55f, Shape = "big", Brand = "TungI", Kcal = 540f, Ru = "Лапша «Тун-И Тушёная говядина»", En = "Tung-I Braised Beef noodles", RuF = "густой бульон с тушёной говядиной", EnF = "a thick braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "TungIBeefHot", Kind = Kind.Brewed, RuM = "Густой тёмный бульон с говядиной. Глоток, и где-то шумит рынок, жарят, кричат, смеются. Потом снова только ветер.", EnM = "A thick dark beef broth. One sip and somewhere a market hums, things fry, people shout and laugh. Then just the wind again.", Raw = "TungIBeef", Mesh = "DonburiHot", Texture = "TungIBeefHot", Kg = 0.632f, Thirst = 21f, Warm = 1.4f, Shape = "big", Brand = "TungI", Kcal = 540f, Ru = "Лапша «Тун-И Тушёная говядина»", En = "Tung-I Braised Beef noodles", RuF = "густой бульон с тушёной говядиной", EnF = "a thick braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "TungIPork", Kind = Kind.Noodle, RuM = "Свиной фарш с жареным луком. Тайваньская классика, с которой там начинают знакомство с лапшой.", EnM = "Minced pork with fried shallots. The Taiwanese classic people there first meet noodles with.", Mesh = "brick2", Texture = "TungIPork", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "TungI", Kcal = 410f, Ru = "Лапша «Тун-И Свиной фарш»", En = "Tung-I Minced Pork noodles", RuF = "тайваньская классика с жареным луком и фаршем", EnF = "a Taiwanese classic with fried shallots and mince", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "TungIPorkHot", Kind = Kind.Brewed, RuM = "Светлый бульон пахнет жареным луком. Запах простой и домашний, от него чужая хижина на час становится своей.", EnM = "A light broth that smells of fried shallots. A plain homely smell that makes a stranger's cabin yours for an hour.", Raw = "TungIPork", Mesh = "DonburiHot", Texture = "TungIPorkHot", Kg = 0.446f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "TungI", Kcal = 410f, Ru = "Лапша «Тун-И Свиной фарш»", En = "Tung-I Minced Pork noodles", RuF = "тайваньская классика с жареным луком и фаршем", EnF = "a Taiwanese classic with fried shallots and mince", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "SuanLaFen", Kind = Kind.Noodle, RuM = "Стеклянная лапша из батата: сначала кисло, потом остро, потом снова хочется.", EnM = "Sweet potato glass noodles: sour first, hot next, then you want more.", Mesh = "bucket", Texture = "SuanLaFen", Kg = 0.113f, Water = 0.5f, Shape = "bucket", Brand = "SuanLa", Kcal = 520f, Ru = "Лапша «Суаньлафэнь» в ведёрке", En = "Suan La Fen bucket", RuF = "стеклянная лапша из батата: сначала кисло, потом остро, потом снова хочется", EnF = "sweet potato glass noodles: sour first, hot next, then you want more", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a8301a" },
        new Def { Id = "SuanLaFenHot", Kind = Kind.Brewed, RuM = "Стеклянная лапша скользит, как вы по льду в первый день. Кисло, остро, и ложка сама тянется за следующей порцией.", EnM = "Glass noodles as slippery as you on the ice on day one. Sour, hot, and the spoon reaches for more by itself.", Raw = "SuanLaFen", Mesh = "bucketHot", Texture = "SuanLaFen", Kg = 0.563f, Thirst = 15f, Warm = 2.2f, Shape = "bucket", Brand = "SuanLa", Kcal = 520f, Ru = "Лапша «Суаньлафэнь» в ведёрке", En = "Suan La Fen bucket", RuF = "стеклянная лапша из батата: сначала кисло, потом остро, потом снова хочется", EnF = "sweet potato glass noodles: sour first, hot next, then you want more", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a8301a" },
        new Def { Id = "SuanLaFenMala", Kind = Kind.Noodle, RuM = "Батат, уксус и онемляющий перец. Ведёрко честно предупреждает иероглифом «ма»: рта вы не почувствуете.", EnM = "Sweet potato, vinegar and numbing pepper. The bucket warns you fairly with the character \"ma\": you will not feel your mouth.", Mesh = "bucket", Texture = "SuanLaFenMala", Kg = 0.111f, Water = 0.5f, Shape = "bucket", Brand = "SuanLa", Kcal = 480f, Ru = "Лапша «Суаньлафэнь Мала» в ведёрке", En = "Suan La Fen Mala bucket", RuF = "стеклянная лапша с онемляющим перцем", EnF = "glass noodles with numbing pepper", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#8e1408" },
        new Def { Id = "SuanLaFenMalaHot", Kind = Kind.Brewed, RuM = "Прозрачная лапша в красном бульоне. Губы немеют, как пальцы без варежек, только это приятно и проходит само.", EnM = "Clear noodles in a red broth. Your lips go numb like fingers without mittens, only it is pleasant and wears off.", Raw = "SuanLaFenMala", Mesh = "bucketHot", Texture = "SuanLaFenMala", Kg = 0.561f, Thirst = 12f, Warm = 2.6f, Shape = "bucket", Brand = "SuanLa", Kcal = 480f, Ru = "Лапша «Суаньлафэнь Мала» в ведёрке", En = "Suan La Fen Mala bucket", RuF = "стеклянная лапша с онемляющим перцем", EnF = "glass noodles with numbing pepper", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#8e1408" },
        new Def { Id = "Xiaomian", Kind = Kind.Noodle, RuM = "Уличная лапша из Чунцина, города на горах, где её едят в шесть утра на табуретке. Табуретку вы уже сожгли.", EnM = "Street noodles from Chongqing, a city on hills where they eat them at six in the morning on a stool. You have burned the stool already.", Mesh = "brick2", Texture = "Xiaomian", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Xiaomian", Kcal = 420f, Ru = "Лапша «Чунцин Сяомянь»", En = "Chongqing Xiaomian noodles", RuF = "уличная лапша из Чунцина: масло чили и сычуаньский перец", EnF = "street noodles from Chongqing: chilli oil and Sichuan pepper", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a8200e" },
        new Def { Id = "XiaomianHot", Kind = Kind.Brewed, RuM = "Масло чили плавает красными кругами. Чунцин называют городом-печкой. Печка в миске, как заказывали.", EnM = "Chilli oil floats in red rings. Chongqing is called the furnace city. A furnace in a bowl, as ordered.", Raw = "Xiaomian", Mesh = "DonburiHot", Texture = "XiaomianHot", Kg = 0.445f, Thirst = 15f, Warm = 2.2f, Shape = "brick", Brand = "Xiaomian", Kcal = 420f, Ru = "Лапша «Чунцин Сяомянь»", En = "Chongqing Xiaomian noodles", RuF = "уличная лапша из Чунцина: масло чили и сычуаньский перец", EnF = "street noodles from Chongqing: chilli oil and Sichuan pepper", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#a8200e" },
        new Def { Id = "XiaomianPea", Kind = Kind.Noodle, RuM = "С жёлтым горохом и фаршем. Горох разварен в кашу, и это не брак, а лучшая часть.", EnM = "With yellow peas and minced meat. The peas are boiled to a mash, and that is not a defect but the best part.", Mesh = "brick1", Texture = "XiaomianPea", Kg = 0.083f, Water = 0.4f, Shape = "brick", Brand = "Xiaomian", Kcal = 370f, Ru = "Лапша «Чунцин Сяомянь Ваньцза»", En = "Chongqing Xiaomian Wanza noodles", RuF = "с жёлтым горохом и мясным фаршем, почти без бульона", EnF = "with yellow peas and minced meat, almost no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#b8641e" },
        new Def { Id = "XiaomianPeaHot", Kind = Kind.Brewed, RuM = "Горох, мясо, красное масло, почти без бульона. Сытно так, что до утра можно не вспоминать про банку собачьих консервов.", EnM = "Peas, meat, red oil, hardly any broth. So filling you can forget the can of dog food until morning.", Raw = "XiaomianPea", Mesh = "PlateHot", Texture = "XiaomianPeaHot", Kg = 0.183f, Thirst = -10f, Warm = 1.35f, Shape = "brick", Brand = "Xiaomian", Kcal = 370f, Ru = "Лапша «Чунцин Сяомянь Ваньцза»", En = "Chongqing Xiaomian Wanza noodles", RuF = "с жёлтым горохом и мясным фаршем, почти без бульона", EnF = "with yellow peas and minced meat, almost no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#b8641e" },
        new Def { Id = "LaoTanFish", Kind = Kind.Noodle, RuM = "Рыбный бульон с квашеной горчицей. Рыбу ловить не надо, уже хорошо.", EnM = "Fish broth with pickled mustard greens. No ice fishing needed, already a win.", Mesh = "big2", Texture = "LaoTanFish", Kg = 0.125f, Water = 0.55f, Shape = "big", Brand = "LaoTan", Kcal = 550f, Ru = "Лапша «Лао Тань Кислая рыба»", En = "Lao Tan Sour Fish noodles", RuF = "рыбный бульон с квашеной горчицей. Рыбу ловить не надо, уже хорошо", EnF = "fish broth with pickled mustard greens. No ice fishing needed, already a win", Spicy = 2, Dry = false, Fx = "", Broth = "#d8c070" },
        new Def { Id = "LaoTanFishHot", Kind = Kind.Brewed, RuM = "Кислый рыбный бульон с перцем и горчицей. Сиг из лунки смотрит на это с завистью: его просто жарят.", EnM = "A sour fish broth with chilli and mustard greens. The whitefish from the ice hole looks on with envy: it just gets fried.", Raw = "LaoTanFish", Mesh = "DonburiHot", Texture = "LaoTanFishHot", Kg = 0.62f, Thirst = 18f, Warm = 1.8f, Shape = "big", Brand = "LaoTan", Kcal = 550f, Ru = "Лапша «Лао Тань Кислая рыба»", En = "Lao Tan Sour Fish noodles", RuF = "рыбный бульон с квашеной горчицей. Рыбу ловить не надо, уже хорошо", EnF = "fish broth with pickled mustard greens. No ice fishing needed, already a win", Spicy = 2, Dry = false, Fx = "", Broth = "#d8c070" },
        new Def { Id = "Reganmian", Kind = Kind.Noodle, RuM = "«горячая сухая лапша»: густая кунжутная паста, без бульона. Название честное.", EnM = "\"hot dry noodles\": thick sesame paste, no broth. An honest name.", Mesh = "brick0", Texture = "Reganmian", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "Regan", Kcal = 400f, Ru = "Лапша «Уханьская Жэгань»", En = "Wuhan Regan noodles", RuF = "«горячая сухая лапша»: густая кунжутная паста, без бульона. Название честное", EnF = "\"hot dry noodles\": thick sesame paste, no broth. An honest name", Spicy = 1, Dry = true, Fx = "", Broth = "#a8763a" },
        new Def { Id = "ReganmianHot", Kind = Kind.Brewed, RuM = "Густая кунжутная паста облепила лапшу. Горячая, сухая, тяжёлая. Завтрак грузчиков Уханя, а вы сегодня тот ещё грузчик.", EnM = "Thick sesame paste clings to the noodles. Hot, dry, heavy. The breakfast of Wuhan dockers, and you were quite a docker today.", Raw = "Reganmian", Mesh = "PlateHot", Texture = "ReganmianHot", Kg = 0.186f, Thirst = -8f, Warm = 1.05f, Shape = "brick", Brand = "Regan", Kcal = 400f, Ru = "Лапша «Уханьская Жэгань»", En = "Wuhan Regan noodles", RuF = "«горячая сухая лапша»: густая кунжутная паста, без бульона. Название честное", EnF = "\"hot dry noodles\": thick sesame paste, no broth. An honest name", Spicy = 1, Dry = true, Fx = "", Broth = "#a8763a" },
        new Def { Id = "WeiLiZhajiang", Kind = Kind.Noodle, RuM = "Тайваньская лапша с мясной пастой. В коробке две миски: одна под лапшу, вторая под суп. Сервиз, считайте.", EnM = "Taiwanese noodles with meat paste. The box holds two bowls: one for the noodles, one for the soup. A dinner set, basically.", Mesh = "box", Texture = "WeiLiZhajiang", Kg = 0.126f, Water = 0.5f, Shape = "box", Brand = "WeiLi", Kcal = 590f, Ru = "Лапша «Вэй Ли Чжацзян» в коробке", En = "Wei Li Zhajiang box", RuF = "тайваньская лапша с мясной пастой, без бульона", EnF = "Taiwanese noodles with meat paste, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#8a5a2b" },
        new Def { Id = "WeiLiZhajiangHot", Kind = Kind.Brewed, RuM = "Тёмная мясная паста на лапше, бульон отдельно. Два блюда из одной коробки, а вы думали, что на острове не бывает обедов из двух блюд.", EnM = "Dark meat paste on noodles, broth on the side. Two courses from one box, and you thought the island had no two-course dinners.", Raw = "WeiLiZhajiang", Mesh = "PlateHot", Texture = "WeiLiZhajiangHot", Kg = 0.251f, Thirst = -6f, Warm = 0.75f, Shape = "box", Brand = "WeiLi", Kcal = 590f, Ru = "Лапша «Вэй Ли Чжацзян» в коробке", En = "Wei Li Zhajiang box", RuF = "тайваньская лапша с мясной пастой, без бульона", EnF = "Taiwanese noodles with meat paste, no broth", Spicy = 0, Dry = true, Fx = "", Broth = "#8a5a2b" },
