        new Def { Id = "WeiLiSesameHot", Kind = Kind.Brewed, RuM = "Кунжутное масло, имбирь, курица. Тайваньские бабушки дают это всем, кто замёрз. Вы подходите по всем пунктам.", EnM = "Sesame oil, ginger, chicken. Taiwanese grannies give this to anyone who is cold. You qualify on every count.", Raw = "WeiLiSesame", Mesh = "bucketHot", Texture = "WeiLiSesame", Kg = 0.554f, Thirst = 24f, Warm = 1.6f, Shape = "bucket", Brand = "WeiLi", Kcal = 460f, Ru = "Лапша «Вэй Ли Кунжутная курица» в ведёрке", En = "Wei Li Sesame Oil Chicken bucket", RuF = "курица на кунжутном масле с имбирём: тайваньское средство от холода", EnF = "chicken in sesame oil with ginger: the Taiwanese cure for the cold", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99040" },
        new Def { Id = "PopMiAyam", Kind = Kind.Noodle, RuM = "Индонезийский стакан с курицей. В комплекте складная вилка, инженерное чудо размером с палец.", EnM = "An Indonesian cup with chicken. A folding fork is included, an engineering marvel the size of a finger.", Mesh = "cup", Texture = "PopMiAyam", Kg = 0.073f, Water = 0.3f, Shape = "cup", Brand = "PopMi", Kcal = 340f, Ru = "Лапша «Поп Ми Аям» в стакане", En = "Pop Mi Ayam cup", RuF = "индонезийский стакан: курица", EnF = "an Indonesian cup: chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
