        new Def { Id = "PopMiBaso", Kind = Kind.Noodle, RuM = "С говяжьими фрикадельками басо. В Индонезии их продают с тележек под стук ложки о миску.", EnM = "With bakso beef meatballs. In Indonesia they are sold from carts to the sound of a spoon tapping a bowl.", Mesh = "cup", Texture = "PopMiBaso", Kg = 0.073f, Water = 0.3f, Shape = "cup", Brand = "PopMi", Kcal = 320f, Ru = "Лапша «Поп Ми Басо» в стакане", En = "Pop Mi Baso cup", RuF = "бульон с говяжьими фрикадельками", EnF = "broth with beef meatballs", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "PopMiBasoHot", Kind = Kind.Brewed, RuM = "Маленькие фрикадельки всплыли в бульоне. Пересчитайте их и ешьте по одной, растягивая праздник.", EnM = "Little meatballs have surfaced in the broth. Count them and eat one at a time to make the feast last.", Raw = "PopMiBaso", Mesh = "cupHot", Texture = "PopMiBaso", Kg = 0.343f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "PopMi", Kcal = 320f, Ru = "Лапша «Поп Ми Басо» в стакане", En = "Pop Mi Baso cup", RuF = "бульон с говяжьими фрикадельками", EnF = "broth with beef meatballs", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
