        new Def { Id = "PopMiPedasHot", Kind = Kind.Brewed, RuM = "Красный бульон, губы горят и пухнут. Зато на морозе они теперь точно не потрескаются. Наверное.", EnM = "A red broth, lips burning and swelling. At least now they will certainly not crack in the frost. Probably.", Raw = "PopMiPedas", Mesh = "cupHot", Texture = "PopMiPedas", Kg = 0.339f, Thirst = 15f, Warm = 2.2f, Shape = "cup", Brand = "PopMi", Kcal = 320f, Ru = "Лапша «Поп Ми Педас Довер» в стакане", En = "Pop Mi Pedas Dower cup", RuF = "курица с перцем «до распухших губ»", EnF = "chicken with chilli \"till your lips swell\"", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#b8281a" },
        new Def { Id = "SarimiBawang", Kind = Kind.Noodle, RuM = "Курица с жареным луком в жёлтой пачке. Скромная индонезийская лапша, которая ничего из себя не строит.", EnM = "Chicken with fried onion in a yellow pack. Modest Indonesian noodles that put on no airs.", Mesh = "mini0", Texture = "SarimiBawang", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "Sarimi", Kcal = 290f, Ru = "Лапша «Сарими Аям Баванг»", En = "Sarimie Ayam Bawang noodles", RuF = "курица с жареным луком", EnF = "chicken with fried onion", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0b860" },
        new Def { Id = "SarimiBawangHot", Kind = Kind.Brewed, RuM = "Светлый бульон с луком. Простая еда для простого вечера: печка трещит, ветер воет, вы живы. Уже неплохо.", EnM = "A light broth with onion. Simple food for a simple evening: the stove crackles, the wind howls, you are alive. Not bad already.", Raw = "SarimiBawang", Mesh = "BowlHot", Texture = "SarimiBawangHot", Kg = 0.377f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Sarimi", Kcal = 290f, Ru = "Лапша «Сарими Аям Баванг»", En = "Sarimie Ayam Bawang noodles", RuF = "курица с жареным луком", EnF = "chicken with fried onion", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0b860" },
