        new Def { Id = "SarimiDuo", Kind = Kind.Noodle, RuM = "Две лепёшки в одной пачке. Вторая не для друга, а для вас через час.", EnM = "Two noodle cakes in one pack. The second is not for a friend, it is for you in an hour.", Mesh = "big2", Texture = "SarimiDuo", Kg = 0.126f, Water = 0.55f, Shape = "big", Brand = "Sarimi", Kcal = 590f, Ru = "Лапша «Сарими Иси 2»", En = "Sarimie Isi 2 noodles", RuF = "две лепёшки в одной пачке, жареная, без бульона", EnF = "two cakes in one pack, fried, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#b8782a" },
