        new Def { Id = "SupermiGoreng", Kind = Kind.Noodle, RuM = "Жареная, со сладким соевым соусом. Соус густой, как патока, и тёмный, как подвал плотины.", EnM = "Fried, with sweet soy sauce. The sauce is as thick as molasses and as dark as the basement of the dam.", Mesh = "brick0", Texture = "SupermiGoreng", Kg = 0.085f, Water = 0.4f, Shape = "brick", Brand = "Supermi", Kcal = 410f, Ru = "Лапша «Супер Ми Горенг»", En = "Supermie Goreng noodles", RuF = "жареная, со сладким соевым соусом, без бульона", EnF = "fried, with sweet soy sauce, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#8a5a2b" },
        new Def { Id = "SupermiGorengHot", Kind = Kind.Brewed, RuM = "Сладкая тёмная лапша. В подвале плотины вас ждал волк, а тут ждёт ужин. Сегодня хороший день.", EnM = "Sweet dark noodles. In the basement of the dam a wolf was waiting, here it is dinner. Today is a good day.", Raw = "SupermiGoreng", Mesh = "PlateHot", Texture = "SupermiGorengHot", Kg = 0.185f, Thirst = -8f, Warm = 1.05f, Shape = "brick", Brand = "Supermi", Kcal = 410f, Ru = "Лапша «Супер Ми Горенг»", En = "Supermie Goreng noodles", RuF = "жареная, со сладким соевым соусом, без бульона", EnF = "fried, with sweet soy sauce, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#8a5a2b" },
