        new Def { Id = "MamyMonsterBBQ", Kind = Kind.Noodle, RuM = "Лапша-снек со вкусом барбекю. Монстр на пачке держит вилку, и это единственное, что у вас с ним общего.", EnM = "A noodle snack with barbecue flavour. The monster on the pack holds a fork, the only thing you have in common.", Mesh = "mini0", Texture = "MamyMonsterBBQ", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "MamyMonster", Kcal = 270f, Ru = "Лапша «Мами Монстр Барбекю»", En = "Mamy Monster BBQ noodles", RuF = "лапша-снек со вкусом барбекю", EnF = "snack noodles with barbecue flavour", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#a8501e" },
        new Def { Id = "MamyMonsterBBQHot", Kind = Kind.Brewed, RuM = "Сладковатый дымный бульон и мелкая лапша. На один зуб, зато весело. Веселья на острове не выдают, берите.", EnM = "A sweetish smoky broth and tiny noodles. One bite's worth, but fun. Fun is not issued on the island, so take it.", Raw = "MamyMonsterBBQ", Mesh = "BowlHot", Texture = "MamyMonsterBBQHot", Kg = 0.373f, Thirst = 24f, Warm = 0.7f, Shape = "mini", Brand = "MamyMonster", Kcal = 270f, Ru = "Лапша «Мами Монстр Барбекю»", En = "Mamy Monster BBQ noodles", RuF = "лапша-снек со вкусом барбекю", EnF = "snack noodles with barbecue flavour", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#a8501e" },
        new Def { Id = "GhostPepper", Kind = Kind.Noodle, RuM = "Чёрная лапша с перцем-призраком, без бульона. «Больдак» рядом с ней отдыхает.", EnM = "Black noodles with ghost pepper, no broth. Burndak is a holiday next to it.", Mesh = "bigcup", Texture = "GhostPepper", Kg = 0.105f, Water = 0.5f, Shape = "bigcup", Brand = "Daebag", Kcal = 490f, Ru = "Лапша «Дэбаг Перец-призрак» в большом стакане", En = "Daebag Ghost Pepper big cup", RuF = "чёрная лапша с перцем-призраком, без бульона. «Больдак» рядом с ней отдыхает", EnF = "black noodles with ghost pepper, no broth. Burndak is a holiday next to it", Spicy = 4, Dry = true, Fx = "heartburn tears", Broth = "#5a0e06" },
        new Def { Id = "GhostPepperHot", Kind = Kind.Brewed, RuM = "Чёрная лапша блестит, как мокрый асфальт. Призрак приходит не сразу, зато остаётся дольше всех гостей на этом острове.", EnM = "Black noodles shining like wet asphalt. The ghost does not come at once, but it stays longer than any guest on this island.", Raw = "GhostPepper", Mesh = "bigcupHot", Texture = "GhostPepper", Kg = 0.23f, Thirst = -14f, Warm = 1.95f, Shape = "bigcup", Brand = "Daebag", Kcal = 490f, Ru = "Лапша «Дэбаг Перец-призрак» в большом стакане", En = "Daebag Ghost Pepper big cup", RuF = "чёрная лапша с перцем-призраком, без бульона. «Больдак» рядом с ней отдыхает", EnF = "black noodles with ghost pepper, no broth. Burndak is a holiday next to it", Spicy = 4, Dry = true, Fx = "heartburn tears", Broth = "#5a0e06" },
        new Def { Id = "GhostPepperSoup", Kind = Kind.Noodle, RuM = "Чёрная лапша в бульоне с кимчи. Призрак приходит через минуту.", EnM = "Black noodles in kimchi broth. The ghost arrives a minute later.", Mesh = "bigcup", Texture = "GhostPepperSoup", Kg = 0.102f, Water = 0.5f, Shape = "bigcup", Brand = "Daebag", Kcal = 490f, Ru = "Лапша «Дэбаг Перец-призрак Кимчи» в большом стакане", En = "Daebag Ghost Pepper Kimchi big cup", RuF = "чёрная лапша в бульоне с кимчи. Призрак приходит через минуту", EnF = "black noodles in kimchi broth. The ghost arrives a minute later", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#a81408" },
        new Def { Id = "GhostPepperSoupHot", Kind = Kind.Brewed, RuM = "Чёрная лапша в красном бульоне. Тьма за окном, тьма в стакане, огонь внутри. Северное сияние отдыхает.", EnM = "Black noodles in a red broth. Darkness outside, darkness in the cup, fire within. The aurora can take the night off.", Raw = "GhostPepperSoup", Mesh = "bigcupHot", Texture = "GhostPepperSoup", Kg = 0.552f, Thirst = 12f, Warm = 2.6f, Shape = "bigcup", Brand = "Daebag", Kcal = 490f, Ru = "Лапша «Дэбаг Перец-призрак Кимчи» в большом стакане", En = "Daebag Ghost Pepper Kimchi big cup", RuF = "чёрная лапша в бульоне с кимчи. Призрак приходит через минуту", EnF = "black noodles in kimchi broth. The ghost arrives a minute later", Spicy = 4, Dry = false, Fx = "heartburn tears", Broth = "#a81408" },
        new Def { Id = "PenangWhiteCurry", Kind = Kind.Noodle, RuM = "Кокосовое карри с пастой из чили: мягкое на вид, злое внутри.", EnM = "Coconut curry with chilli paste: mild to look at, mean inside.", Mesh = "big0", Texture = "PenangWhiteCurry", Kg = 0.13f, Water = 0.55f, Shape = "big", Brand = "MaKuali", Kcal = 600f, Ru = "Лапша «Ма Куали Пенангское белое карри»", En = "Ma Kuali Penang White Curry noodles", RuF = "кокосовое карри с пастой из чили: мягкое на вид, злое внутри", EnF = "coconut curry with chilli paste: mild to look at, mean inside", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#e0a050" },
        new Def { Id = "PenangWhiteCurryHot", Kind = Kind.Brewed, RuM = "Белёсое карри с красной ложкой пасты чили. Размешали всю? Смело. Аптечка в рюкзаке, вода в бутылке.", EnM = "A pale curry with a red spoonful of chilli paste. Stirred it all in? Brave. The first aid kit is in your pack, the water in the bottle.", Raw = "PenangWhiteCurry", Mesh = "BowlHot", Texture = "PenangWhiteCurryHot", Kg = 0.625f, Thirst = 15f, Warm = 2.2f, Shape = "big", Brand = "MaKuali", Kcal = 600f, Ru = "Лапша «Ма Куали Пенангское белое карри»", En = "Ma Kuali Penang White Curry noodles", RuF = "кокосовое карри с пастой из чили: мягкое на вид, злое внутри", EnF = "coconut curry with chilli paste: mild to look at, mean inside", Spicy = 3, Dry = false, Fx = "appetite heartburn", Broth = "#e0a050" },
        new Def { Id = "PenangPrawn", Kind = Kind.Noodle, RuM = "Густой креветочный бульон по-хоккиенски. Сварен на креветочных головах, и это комплимент.", EnM = "A thick Hokkien-style prawn broth. Made from prawn heads, and that is a compliment.", Mesh = "big0", Texture = "PenangPrawn", Kg = 0.133f, Water = 0.55f, Shape = "big", Brand = "MaKuali", Kcal = 540f, Ru = "Лапша «Ма Куали Пенангская креветка»", En = "Ma Kuali Penang Hokkien Prawn noodles", RuF = "густой креветочный бульон по-хоккиенски", EnF = "a thick Hokkien prawn broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c85a28" },
        new Def { Id = "PenangPrawnHot", Kind = Kind.Brewed, RuM = "Тёмно-оранжевый бульон пахнет креветкой на всю округу. Медведи рыбу любят, про креветок данных нет. Проверять не будем.", EnM = "A deep orange broth that smells of prawn for miles. Bears like fish, on prawns there is no data. Let us not check.", Raw = "PenangPrawn", Mesh = "BowlHot", Texture = "PenangPrawnHot", Kg = 0.628f, Thirst = 18f, Warm = 1.8f, Shape = "big", Brand = "MaKuali", Kcal = 540f, Ru = "Лапша «Ма Куали Пенангская креветка»", En = "Ma Kuali Penang Hokkien Prawn noodles", RuF = "густой креветочный бульон по-хоккиенски", EnF = "a thick Hokkien prawn broth", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c85a28" },
        new Def { Id = "PenangTomYum", Kind = Kind.Noodle, RuM = "Том-ям из Пенанга с лемонграссом. Лемонграсс пахнет лимоном и летом, двумя вещами, которых тут нет.", EnM = "Tom yum from Penang with lemongrass. Lemongrass smells of lemon and summer, two things this place lacks.", Mesh = "big0", Texture = "PenangTomYum", Kg = 0.128f, Water = 0.55f, Shape = "big", Brand = "MaKuali", Kcal = 570f, Ru = "Лапша «Ма Куали Пенангский том-ям»", En = "Ma Kuali Penang Tom Yum noodles", RuF = "кисло-острый бульон с лемонграссом", EnF = "a hot and sour broth with lemongrass", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "PenangTomYumHot", Kind = Kind.Brewed, RuM = "Кисло-острый бульон с травами. После него дышится легко, как на вершине. Только лезть никуда не пришлось.", EnM = "A sour and spicy broth with herbs. After it you breathe as easily as on a summit. Only there was no climbing involved.", Raw = "PenangTomYum", Mesh = "BowlHot", Texture = "PenangTomYumHot", Kg = 0.623f, Thirst = 18f, Warm = 1.8f, Shape = "big", Brand = "MaKuali", Kcal = 570f, Ru = "Лапша «Ма Куали Пенангский том-ям»", En = "Ma Kuali Penang Tom Yum noodles", RuF = "кисло-острый бульон с лемонграссом", EnF = "a hot and sour broth with lemongrass", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#e0662a" },
        new Def { Id = "OmachyBeef", Kind = Kind.Noodle, RuM = "Вьетнамская лапша из картофеля. Реклама обещает, что от неё «не жарко». На острове это не то обещание, которого ждёшь.", EnM = "Vietnamese noodles made from potato. The advert promises they \"do not overheat you\". On the island that is not the promise you want.", Mesh = "brick2", Texture = "OmachyBeef", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "Omachy", Kcal = 370f, Ru = "Лапша «Омачи Тушёная говядина»", En = "Omachy Beef Stew noodles", RuF = "вьетнамская лапша из картофеля, бульон с тушёной говядиной", EnF = "Vietnamese potato noodles, braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "OmachyBeefHot", Kind = Kind.Brewed, RuM = "Тушёная говядина в тёмном бульоне, лапша жёлтая и упругая. Картошка и мясо: формула счастья, понятная на любой широте.", EnM = "Stewed beef in a dark broth, yellow springy noodles. Potatoes and meat: a formula for happiness understood at any latitude.", Raw = "OmachyBeef", Mesh = "BowlHot", Texture = "OmachyBeefHot", Kg = 0.446f, Thirst = 21f, Warm = 1.4f, Shape = "brick", Brand = "Omachy", Kcal = 370f, Ru = "Лапша «Омачи Тушёная говядина»", En = "Omachy Beef Stew noodles", RuF = "вьетнамская лапша из картофеля, бульон с тушёной говядиной", EnF = "Vietnamese potato noodles, braised beef broth", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#9a4a1e" },
        new Def { Id = "OmachyRibs", Kind = Kind.Noodle, RuM = "Свиные рёбрышки с овощами. Рёбрышки в виде аромата, овощи в виде хлопьев. Воображение своё.", EnM = "Pork ribs with vegetables. The ribs come as an aroma, the vegetables as flakes. Bring your own imagination.", Mesh = "brick2", Texture = "OmachyRibs", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "Omachy", Kcal = 390f, Ru = "Лапша «Омачи Свиные рёбрышки»", En = "Omachy Pork Ribs noodles", RuF = "бульон на свиных рёбрышках с овощами", EnF = "pork rib broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "OmachyRibsHot", Kind = Kind.Brewed, RuM = "Бульон на рёбрышках, сладковатый и домашний. Обглодать нечего, зато и волкам потом нечего подбирать.", EnM = "A rib broth, sweetish and homely. Nothing to gnaw on, but nothing for the wolves to pick up afterwards either.", Raw = "OmachyRibs", Mesh = "BowlHot", Texture = "OmachyRibsHot", Kg = 0.446f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Omachy", Kcal = 390f, Ru = "Лапша «Омачи Свиные рёбрышки»", En = "Omachy Pork Ribs noodles", RuF = "бульон на свиных рёбрышках с овощами", EnF = "pork rib broth with vegetables", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "OmachySpaghetti", Kind = Kind.Noodle, RuM = "Вьетнамская лапша с соусом для спагетти. Италия через Сайгон до Канады: маршрут, который не строил ни один навигатор.", EnM = "Vietnamese noodles with spaghetti sauce. Italy via Saigon to Canada: a route no navigator ever plotted.", Mesh = "brick1", Texture = "OmachySpaghetti", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "Omachy", Kcal = 420f, Ru = "Лапша «Омачи Соус спагетти»", En = "Omachy Spaghetti Sauce noodles", RuF = "лапша с томатно-мясным соусом, без бульона", EnF = "noodles with tomato and meat sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d2452a" },
        new Def { Id = "OmachySpaghettiHot", Kind = Kind.Brewed, RuM = "Томатно-мясной соус на картофельной лапше. Не спагетти, не рамен, не пойми что. Вкусно, остальное неважно.", EnM = "Tomato and meat sauce on potato noodles. Not spaghetti, not ramen, who knows what. Tasty, the rest does not matter.", Raw = "OmachySpaghetti", Mesh = "PlateHot", Texture = "OmachySpaghettiHot", Kg = 0.19f, Thirst = -6f, Warm = 0.75f, Shape = "brick", Brand = "Omachy", Kcal = 420f, Ru = "Лапша «Омачи Соус спагетти»", En = "Omachy Spaghetti Sauce noodles", RuF = "лапша с томатно-мясным соусом, без бульона", EnF = "noodles with tomato and meat sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d2452a" },
        new Def { Id = "SaigonBunBo", Kind = Kind.Noodle, RuM = "Бун бо хюэ: суп императорской столицы. Императоры ели его во дворце, вы едите его в прицепе у озера.", EnM = "Bun bo Hue: the soup of the imperial capital. Emperors ate it in a palace, you eat it in a trailer by the lake.", Mesh = "bowl", Texture = "SaigonBunBo", Kg = 0.102f, Water = 0.45f, Shape = "bowl", Brand = "Saigon", Kcal = 400f, Ru = "Лапша «Сайгон Бун Бун Бо Хюэ» в миске", En = "Saigon Bun Bun Bo Hue bowl", RuF = "рисовая лапша в остром говяжьем бульоне с лемонграссом", EnF = "rice noodles in a spicy beef broth with lemongrass", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c85a28" },
        new Def { Id = "SaigonBunBoHot", Kind = Kind.Brewed, RuM = "Толстая рисовая лапша в красном бульоне с лемонграссом. Остро, пряно, по-царски. Прицеп временно считается дворцом.", EnM = "Thick rice noodles in a red lemongrass broth. Hot, fragrant, regal. The trailer counts as a palace for now.", Raw = "SaigonBunBo", Mesh = "bowlHot", Texture = "SaigonBunBo", Kg = 0.507f, Thirst = 18f, Warm = 1.8f, Shape = "bowl", Brand = "Saigon", Kcal = 400f, Ru = "Лапша «Сайгон Бун Бун Бо Хюэ» в миске", En = "Saigon Bun Bun Bo Hue bowl", RuF = "рисовая лапша в остром говяжьем бульоне с лемонграссом", EnF = "rice noodles in a spicy beef broth with lemongrass", Spicy = 2, Dry = false, Fx = "appetite", Broth = "#c85a28" },
        new Def { Id = "SaigonHuTieu", Kind = Kind.Noodle, RuM = "Ху тьеу: сайгонский суп со свининой и креветкой. Миска картонная, но держит кипяток и ваше настроение.", EnM = "Hu tieu: the Saigon soup with pork and shrimp. The bowl is cardboard, yet it holds boiling water and your mood.", Mesh = "bowl", Texture = "SaigonHuTieu", Kg = 0.103f, Water = 0.45f, Shape = "bowl", Brand = "Saigon", Kcal = 430f, Ru = "Лапша «Сайгон Бун Ху Тьеу» в миске", En = "Saigon Bun Hu Tieu bowl", RuF = "рисовая лапша в свином бульоне с креветкой", EnF = "rice noodles in pork broth with shrimp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "SaigonHuTieuHot", Kind = Kind.Brewed, RuM = "Светлый сладковатый бульон и прозрачная лапша. Лёгкий, как утро без ветра. Таких утр тут два в месяц, запомните это.", EnM = "A light sweetish broth and translucent noodles. As easy as a windless morning. There are two of those a month here, remember this one.", Raw = "SaigonHuTieu", Mesh = "bowlHot", Texture = "SaigonHuTieu", Kg = 0.508f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Saigon", Kcal = 430f, Ru = "Лапша «Сайгон Бун Ху Тьеу» в миске", En = "Saigon Bun Hu Tieu bowl", RuF = "рисовая лапша в свином бульоне с креветкой", EnF = "rice noodles in pork broth with shrimp", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#c9a36a" },
        new Def { Id = "SaigonMienGa", Kind = Kind.Noodle, RuM = "Стеклянная лапша с курицей. Прозрачная, как лёд, и почти такая же скользкая.", EnM = "Glass noodles with chicken. As clear as ice and nearly as slippery.", Mesh = "bowl", Texture = "SaigonMienGa", Kg = 0.096f, Water = 0.45f, Shape = "bowl", Brand = "Saigon", Kcal = 400f, Ru = "Лапша «Сайгон Бун Мьен Га» в миске", En = "Saigon Bun Mien Ga bowl", RuF = "стеклянная лапша с курицей", EnF = "glass noodles with chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "SaigonMienGaHot", Kind = Kind.Brewed, RuM = "Куриный бульон, в нём лапша, которой почти не видно. Ловить её ложкой труднее, чем кролика камнем, но оно того стоит.", EnM = "Chicken broth with noodles you can hardly see. Catching them with a spoon is harder than a rabbit with a stone, but worth it.", Raw = "SaigonMienGa", Mesh = "bowlHot", Texture = "SaigonMienGa", Kg = 0.501f, Thirst = 24f, Warm = 1.0f, Shape = "bowl", Brand = "Saigon", Kcal = 400f, Ru = "Лапша «Сайгон Бун Мьен Га» в миске", En = "Saigon Bun Mien Ga bowl", RuF = "стеклянная лапша с курицей", EnF = "glass noodles with chicken", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "PaylesChilimansi", Kind = Kind.Noodle, RuM = "«Экстра Биг»: бюджетная, зато большая. Название значит «платишь меньше». На острове вы не платите вообще, рекорд.", EnM = "\"Xtra Big\": cheap but large. The name means \"pay less\". On the island you pay nothing at all, a record.", Mesh = "brick0", Texture = "PaylesChilimansi", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "Payles", Kcal = 400f, Ru = "Лапша «Пэйлес Экстра Биг»", En = "Payles Xtra Big noodles", RuF = "филиппинская бюджетная жареная лапша с перцем и каламанси, без бульона", EnF = "Filipino budget fried noodles with chilli and calamansi, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a84a1a" },
        new Def { Id = "PaylesChilimansiHot", Kind = Kind.Brewed, RuM = "Жареная лапша с перцем и каламанси, порция с горкой. Дёшево, много и остро: три желания студента и выжившего.", EnM = "Fried noodles with chilli and calamansi, a heaped helping. Cheap, plenty and hot: the three wishes of a student and a survivor.", Raw = "PaylesChilimansi", Mesh = "PlateHot", Texture = "PaylesChilimansiHot", Kg = 0.188f, Thirst = -10f, Warm = 1.35f, Shape = "brick", Brand = "Payles", Kcal = 400f, Ru = "Лапша «Пэйлес Экстра Биг»", En = "Payles Xtra Big noodles", RuF = "филиппинская бюджетная жареная лапша с перцем и каламанси, без бульона", EnF = "Filipino budget fried noodles with chilli and calamansi, no broth", Spicy = 2, Dry = true, Fx = "", Broth = "#a84a1a" },
        new Def { Id = "PaylesBatchoy", Kind = Kind.Noodle, RuM = "Суп батчой из Ла-Паса: свинина и жареный чеснок.", EnM = "La Paz batchoy soup: pork and fried garlic.", Mesh = "mini2", Texture = "PaylesBatchoy", Kg = 0.059f, Water = 0.35f, Shape = "mini", Brand = "Payles", Kcal = 290f, Ru = "Лапша «Пэйлес Батчой»", En = "Payles Batchoy noodles", RuF = "суп батчой из Ла-Паса: свинина и жареный чеснок", EnF = "La Paz batchoy soup: pork and fried garlic", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "PaylesBatchoyHot", Kind = Kind.Brewed, RuM = "Свиной бульон с жареным чесноком. На рынке в Ла-Пасе его едят в жару. В мороз он, честно говоря, ещё лучше.", EnM = "Pork broth with fried garlic. At the market in La Paz they eat it in the heat. In the frost it is, frankly, even better.", Raw = "PaylesBatchoy", Mesh = "BowlHot", Texture = "PaylesBatchoyHot", Kg = 0.374f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Payles", Kcal = 290f, Ru = "Лапша «Пэйлес Батчой»", En = "Payles Batchoy noodles", RuF = "суп батчой из Ла-Паса: свинина и жареный чеснок", EnF = "La Paz batchoy soup: pork and fried garlic", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#c99a55" },
        new Def { Id = "PaylesBulalo", Kind = Kind.Noodle, RuM = "Бульон на мозговой кости. Филиппинцы варят булало в прохладных горах. Их «прохладно» это плюс пятнадцать.", EnM = "Marrow bone broth. Filipinos cook bulalo in the cool highlands. Their \"cool\" is plus fifteen.", Mesh = "mini2", Texture = "PaylesBulalo", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Payles", Kcal = 280f, Ru = "Лапша «Пэйлес Булало»", En = "Payles Bulalo noodles", RuF = "бульон на говяжьей мозговой кости", EnF = "a beef marrow bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "PaylesBulaloHot", Kind = Kind.Brewed, RuM = "Жирный говяжий бульон. Кость из него вы бы сейчас раскололи и высосали, но пакетик справился за вас.", EnM = "A rich beef broth. You would crack the bone and suck it dry right now, but the sachet did it for you.", Raw = "PaylesBulalo", Mesh = "BowlHot", Texture = "PaylesBulaloHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Payles", Kcal = 280f, Ru = "Лапша «Пэйлес Булало»", En = "Payles Bulalo noodles", RuF = "бульон на говяжьей мозговой кости", EnF = "a beef marrow bone broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "YipeeMagic", Kind = Kind.Noodle, RuM = "Круглая лепёшка лапши, чтобы ровно ложилась в кастрюлю и не ломалась. Индийские инженеры подумали о вашем котелке.", EnM = "A round noodle cake that fits the pan and does not break. Indian engineers were thinking of your pot.", Mesh = "mini0", Texture = "YipeeMagic", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Yipee", Kcal = 290f, Ru = "Лапша «Йиппи Мэджик Масала»", En = "Yipee Magic Masala noodles", RuF = "круглая лепёшка лапши с индийскими пряностями", EnF = "a round noodle cake with Indian spices", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "YipeeMagicHot", Kind = Kind.Brewed, RuM = "Жёлтая лапша с масалой, длинная и не слипается. «Йиппи!» на острове кричат редко, но тут можно. Шёпотом.", EnM = "Yellow masala noodles, long and never sticky. \"Yippee!\" is rarely shouted on the island, but here you may. In a whisper.", Raw = "YipeeMagic", Mesh = "BowlHot", Texture = "YipeeMagicHot", Kg = 0.373f, Thirst = 21f, Warm = 1.4f, Shape = "mini", Brand = "Yipee", Kcal = 290f, Ru = "Лапша «Йиппи Мэджик Масала»", En = "Yipee Magic Masala noodles", RuF = "круглая лепёшка лапши с индийскими пряностями", EnF = "a round noodle cake with Indian spices", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "YipeeMood", Kind = Kind.Noodle, RuM = "Масала поострее, два пакетика специй. Второй пакетик для настроения, так прямо и называется.", EnM = "A hotter masala with two spice sachets. The second sachet is for the mood, and is named exactly that.", Mesh = "mini2", Texture = "YipeeMood", Kg = 0.061f, Water = 0.35f, Shape = "mini", Brand = "Yipee", Kcal = 270f, Ru = "Лапша «Йиппи Муд Масала»", En = "Yipee Mood Masala noodles", RuF = "масала поострее, с двумя пакетиками специй", EnF = "a hotter masala with two spice sachets", Spicy = 2, Dry = false, Fx = "", Broth = "#c85a28" },
        new Def { Id = "YipeeMoodHot", Kind = Kind.Brewed, RuM = "Оранжевая, пряная и бодрая. Настроение после неё поднимается градуса на три. Температура за окном нет.", EnM = "Orange, spicy and lively. Your mood goes up about three degrees afterwards. The temperature outside does not.", Raw = "YipeeMood", Mesh = "BowlHot", Texture = "YipeeMoodHot", Kg = 0.376f, Thirst = 18f, Warm = 1.8f, Shape = "mini", Brand = "Yipee", Kcal = 270f, Ru = "Лапша «Йиппи Муд Масала»", En = "Yipee Mood Masala noodles", RuF = "масала поострее, с двумя пакетиками специй", EnF = "a hotter masala with two spice sachets", Spicy = 2, Dry = false, Fx = "", Broth = "#c85a28" },
        new Def { Id = "YipeeAtta", Kind = Kind.Noodle, RuM = "Лапша из цельнозерновой муки. Полезная. На острове, где полезно всё, что не убивает, это отдельное достижение.", EnM = "Whole wheat noodles. Healthy. On an island where anything that does not kill you is healthy, that is an achievement.", Mesh = "mini2", Texture = "YipeeAtta", Kg = 0.063f, Water = 0.35f, Shape = "mini", Brand = "Yipee", Kcal = 280f, Ru = "Лапша «Йиппи Атта»", En = "Yipee Atta noodles", RuF = "лапша из цельнозерновой муки", EnF = "whole-wheat noodles", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "YipeeAttaHot", Kind = Kind.Brewed, RuM = "Тёмная лапша с пряностями. Клетчатка, цельное зерно, забота о здоровье. Диетолог был бы доволен, жаль, его съели бы первым.", EnM = "Dark noodles with spices. Fibre, whole grain, health care. A dietitian would be pleased, a pity he would be eaten first.", Raw = "YipeeAtta", Mesh = "BowlHot", Texture = "YipeeAttaHot", Kg = 0.378f, Thirst = 21f, Warm = 1.4f, Shape = "mini", Brand = "Yipee", Kcal = 280f, Ru = "Лапша «Йиппи Атта»", En = "Yipee Atta noodles", RuF = "лапша из цельнозерновой муки", EnF = "whole-wheat noodles", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c98f45" },
        new Def { Id = "ChoyzChicken", Kind = Kind.Noodle, RuM = "Со вкусом курицы. Название от слова «выбор», хотя выбора у вас как раз нет: что нашли, то и ужин.", EnM = "Chicken flavour. The name comes from \"choice\", though choice is what you lack: what you find is dinner.", Mesh = "brick2", Texture = "ChoyzChicken", Kg = 0.082f, Water = 0.4f, Shape = "brick", Brand = "Choyz", Kcal = 390f, Ru = "Лапша «Чойз Курица»", En = "Choyz Chicken noodles", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "ChoyzChickenHot", Kind = Kind.Brewed, RuM = "Жёлтый бульон, лапша волной. Никаких открытий, просто горячо и съедобно. Иногда это и есть открытие.", EnM = "Yellow broth, wavy noodles. No discoveries, just hot and edible. Sometimes that is the discovery.", Raw = "ChoyzChicken", Mesh = "BowlHot", Texture = "ChoyzChickenHot", Kg = 0.442f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Choyz", Kcal = 390f, Ru = "Лапша «Чойз Курица»", En = "Choyz Chicken noodles", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "ChoyzBeef", Kind = Kind.Noodle, RuM = "Со вкусом говядины. Корову для этого вкуса придумал технолог, и у него был талант.", EnM = "Beef flavour. The cow for this flavour was invented by a food technologist, and he had talent.", Mesh = "brick2", Texture = "ChoyzBeef", Kg = 0.088f, Water = 0.4f, Shape = "brick", Brand = "Choyz", Kcal = 400f, Ru = "Лапша «Чойз Говядина»", En = "Choyz Beef noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "ChoyzBeefHot", Kind = Kind.Brewed, RuM = "Коричневый бульон, пар, тишина. Ничего особенного, и именно этого вам сегодня не хватало.", EnM = "Brown broth, steam, silence. Nothing special, which is exactly what you were short of today.", Raw = "ChoyzBeef", Mesh = "BowlHot", Texture = "ChoyzBeefHot", Kg = 0.448f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "Choyz", Kcal = 400f, Ru = "Лапша «Чойз Говядина»", En = "Choyz Beef noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "ChoyzChili", Kind = Kind.Noodle, RuM = "Курица с перцем. Тот самый выбор для тех, кто хочет поострее, но без подвигов.", EnM = "Chicken with chilli. The very choice for those who want it hotter but without heroics.", Mesh = "brick1", Texture = "ChoyzChili", Kg = 0.081f, Water = 0.4f, Shape = "brick", Brand = "Choyz", Kcal = 400f, Ru = "Лапша «Чойз Острая курица»", En = "Choyz Spicy Chicken noodles", RuF = "курица с перцем", EnF = "chicken with chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "ChoyzChiliHot", Kind = Kind.Brewed, RuM = "Бульон с красными искрами. Греет как костёр из трёх поленьев: без пожара, но ощутимо.", EnM = "A broth with red sparks. It warms like a three-log campfire: no blaze, but you feel it.", Raw = "ChoyzChili", Mesh = "BowlHot", Texture = "ChoyzChiliHot", Kg = 0.441f, Thirst = 18f, Warm = 1.8f, Shape = "brick", Brand = "Choyz", Kcal = 400f, Ru = "Лапша «Чойз Острая курица»", En = "Choyz Spicy Chicken noodles", RuF = "курица с перцем", EnF = "chicken with chilli", Spicy = 2, Dry = false, Fx = "", Broth = "#c4381c" },
        new Def { Id = "ChoyzCup", Kind = Kind.Noodle, RuM = "Курица в стакане. Просто, быстро, одной рукой. Вторая рука свободна для фонаря или ножа.", EnM = "Chicken in a cup. Simple, quick, one-handed. The other hand stays free for a lantern or a knife.", Mesh = "cup", Texture = "ChoyzCup", Kg = 0.071f, Water = 0.3f, Shape = "cup", Brand = "Choyz", Kcal = 350f, Ru = "Лапша «Чойз Курица» в стакане", En = "Choyz Chicken cup", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "ChoyzCupHot", Kind = Kind.Brewed, RuM = "Горячий стакан куриного бульона. Пить стоя, глядя в окно на метель, с видом человека, у которого всё под контролем.", EnM = "A hot cup of chicken broth. Drink it standing, watching the blizzard through the window, with the air of someone in control.", Raw = "ChoyzCup", Mesh = "cupHot", Texture = "ChoyzCup", Kg = 0.341f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "Choyz", Kcal = 350f, Ru = "Лапша «Чойз Курица» в стакане", En = "Choyz Chicken cup", RuF = "со вкусом курицы", EnF = "chicken flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AlexSofaChicken", Kind = Kind.Noodle, RuM = "Со вкусом курицы. Кто такие Александр и Софа, не знает никто.", EnM = "Chicken flavour. Nobody knows who Alexander and Sofa are.", Mesh = "mini1", Texture = "AlexSofaChicken", Kg = 0.056f, Water = 0.35f, Shape = "mini", Brand = "AlexSofa", Kcal = 280f, Ru = "Лапша «Александр и Софа Курица»", En = "Alexander & Sofa Chicken noodles", RuF = "со вкусом курицы. Кто такие Александр и Софа, не знает никто", EnF = "chicken flavour. Nobody knows who Alexander and Sofa are", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AlexSofaChickenHot", Kind = Kind.Brewed, RuM = "Куриный бульон от Александра и Софы. Кто бы они ни были, спасибо им. Больше на этом острове о вас никто не подумал.", EnM = "Chicken broth from Alexander and Sofa. Whoever they are, thank them. Nobody else on this island gave you a thought.", Raw = "AlexSofaChicken", Mesh = "BowlHot", Texture = "AlexSofaChickenHot", Kg = 0.371f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "AlexSofa", Kcal = 280f, Ru = "Лапша «Александр и Софа Курица»", En = "Alexander & Sofa Chicken noodles", RuF = "со вкусом курицы. Кто такие Александр и Софа, не знает никто", EnF = "chicken flavour. Nobody knows who Alexander and Sofa are", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AlexSofaBeef", Kind = Kind.Noodle, RuM = "Говядина от загадочной пары. На пачке ни портрета, ни адреса. Возможно, они тоже где-то выживают.", EnM = "Beef from the mysterious couple. No portrait, no address on the pack. Perhaps they are surviving somewhere too.", Mesh = "mini0", Texture = "AlexSofaBeef", Kg = 0.057f, Water = 0.35f, Shape = "mini", Brand = "AlexSofa", Kcal = 270f, Ru = "Лапша «Александр и Софа Говядина»", En = "Alexander & Sofa Beef noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "AlexSofaBeefHot", Kind = Kind.Brewed, RuM = "Тёмный бульон, мягкая лапша. Александр, наверное, варил, Софа, наверное, солила. Получилось по-семейному.", EnM = "Dark broth, soft noodles. Alexander probably cooked, Sofa probably salted. It came out like a family meal.", Raw = "AlexSofaBeef", Mesh = "BowlHot", Texture = "AlexSofaBeefHot", Kg = 0.372f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "AlexSofa", Kcal = 270f, Ru = "Лапша «Александр и Софа Говядина»", En = "Alexander & Sofa Beef noodles", RuF = "со вкусом говядины", EnF = "beef flavour", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "AlexSofaMushroom", Kind = Kind.Noodle, RuM = "Грибы от Александра и Софы. Третий вкус, а ясности про них так и не прибавилось.", EnM = "Mushrooms from Alexander and Sofa. A third flavour, and still no clarity about them.", Mesh = "mini1", Texture = "AlexSofaMushroom", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "AlexSofa", Kcal = 290f, Ru = "Лапша «Александр и Софа Грибы»", En = "Alexander & Sofa Mushroom noodles", RuF = "со вкусом грибов", EnF = "mushroom flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b89a6a" },
        new Def { Id = "AlexSofaMushroomHot", Kind = Kind.Brewed, RuM = "Грибной бульон пахнет осенью. Хочется верить, что Александр и Софа сейчас в тепле, собирают грибы и ни о чём не знают.", EnM = "The mushroom broth smells of autumn. You want to believe Alexander and Sofa are warm right now, picking mushrooms, knowing nothing.", Raw = "AlexSofaMushroom", Mesh = "BowlHot", Texture = "AlexSofaMushroomHot", Kg = 0.377f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "AlexSofa", Kcal = 290f, Ru = "Лапша «Александр и Софа Грибы»", En = "Alexander & Sofa Mushroom noodles", RuF = "со вкусом грибов", EnF = "mushroom flavour", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#b89a6a" },
        new Def { Id = "HonestChicken", Kind = Kind.Noodle, RuM = "Самая дешёвая. Курица в составе указана из вежливости.", EnM = "The cheapest there is. Chicken is on the list out of politeness.", Mesh = "mini2", Texture = "HonestChicken", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "HonestPrice", Kcal = 280f, Ru = "Лапша «Честная цена Курица»", En = "Honest Price Chicken noodles", RuF = "самая дешёвая. Курица в составе указана из вежливости", EnF = "the cheapest there is. Chicken is on the list out of politeness", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#e8b04a" },
        new Def { Id = "HonestChickenHot", Kind = Kind.Brewed, RuM = "Бульон бледный, лапша честная. Курицу в нём не найдёт и следователь, но он тёплый, а цену никто не спросит.", EnM = "The broth is pale, the noodles honest. Not even a detective would find chicken in it, but it is warm and nobody asks the price.", Raw = "HonestChicken", Mesh = "BowlHot", Texture = "HonestChickenHot", Kg = 0.377f, Thirst = 24f, Warm = 0.7f, Shape = "mini", Brand = "HonestPrice", Kcal = 280f, Ru = "Лапша «Честная цена Курица»", En = "Honest Price Chicken noodles", RuF = "самая дешёвая. Курица в составе указана из вежливости", EnF = "the cheapest there is. Chicken is on the list out of politeness", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#e8b04a" },
        new Def { Id = "HonestBeef", Kind = Kind.Noodle, RuM = "Самая дешёвая. На дизайн пачки денег не хватило, на говядину тоже.", EnM = "The cheapest there is. No money left for the pack design, nor for the beef.", Mesh = "mini1", Texture = "HonestBeef", Kg = 0.062f, Water = 0.35f, Shape = "mini", Brand = "HonestPrice", Kcal = 280f, Ru = "Лапша «Честная цена Говядина»", En = "Honest Price Beef noodles", RuF = "самая дешёвая. На дизайн пачки денег не хватило, на говядину тоже", EnF = "the cheapest there is. No money left for the pack design, nor for the beef", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#b9692d" },
        new Def { Id = "HonestBeefHot", Kind = Kind.Brewed, RuM = "Говядины здесь столько же, сколько оленей в вашем спальнике. Зато горячо, и совесть у производителя чиста: он не обещал.", EnM = "There is as much beef here as there are deer in your bedroll. But it is hot, and the maker's conscience is clear: he promised nothing.", Raw = "HonestBeef", Mesh = "BowlHot", Texture = "HonestBeefHot", Kg = 0.377f, Thirst = 24f, Warm = 0.7f, Shape = "mini", Brand = "HonestPrice", Kcal = 280f, Ru = "Лапша «Честная цена Говядина»", En = "Honest Price Beef noodles", RuF = "самая дешёвая. На дизайн пачки денег не хватило, на говядину тоже", EnF = "the cheapest there is. No money left for the pack design, nor for the beef", Spicy = 0, Dry = false, Fx = "brothreserve emptycal", Broth = "#b9692d" },
        new Def { Id = "KespeBeef", Kind = Kind.Noodle, RuM = "Казахстанская домашняя лапша. В степи тоже ветер, мороз и ни души на сто километров, так что она поймёт.", EnM = "Kazakh home-style noodles. The steppe also has wind, frost and not a soul for a hundred kilometres, so they will understand.", Mesh = "brick2", Texture = "KespeBeef", Kg = 0.09f, Water = 0.4f, Shape = "brick", Brand = "KespeKhan", Kcal = 400f, Ru = "Лапша «Кеспе-хан Говядина»", En = "Kespe Khan Beef noodles", RuF = "казахстанская домашняя лапша в говяжьем бульоне", EnF = "Kazakh home-style noodles in beef broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "KespeBeefHot", Kind = Kind.Brewed, RuM = "Широкая лапша в говяжьем бульоне. Как у бабушки в ауле, только бабушка ещё дала бы баурсак и спросила, почему вы такой худой.", EnM = "Wide noodles in beef broth. Like at granny's in the village, only granny would add a fried bun and ask why you are so thin.", Raw = "KespeBeef", Mesh = "BowlHot", Texture = "KespeBeefHot", Kg = 0.45f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "KespeKhan", Kcal = 400f, Ru = "Лапша «Кеспе-хан Говядина»", En = "Kespe Khan Beef noodles", RuF = "казахстанская домашняя лапша в говяжьем бульоне", EnF = "Kazakh home-style noodles in beef broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "KespeLamb", Kind = Kind.Noodle, RuM = "Бульон на баранине. Баранов на Великом Медведе нет, а запах стоит такой, будто отара прошла.", EnM = "A mutton broth. Great Bear has no sheep, yet it smells as if a flock just went by.", Mesh = "brick0", Texture = "KespeLamb", Kg = 0.089f, Water = 0.4f, Shape = "brick", Brand = "KespeKhan", Kcal = 410f, Ru = "Лапша «Кеспе-хан Баранина»", En = "Kespe Khan Lamb noodles", RuF = "бульон на баранине с зеленью", EnF = "lamb broth with herbs", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#b8823a" },
        new Def { Id = "KespeLambHot", Kind = Kind.Brewed, RuM = "Жирный бараний бульон с зеленью. Остывает быстро, поэтому ешьте сразу. Застывший бараний жир не красит ни миску, ни жизнь.", EnM = "A rich mutton broth with herbs. It cools fast, so eat at once. Set mutton fat improves neither the bowl nor life.", Raw = "KespeLamb", Mesh = "BowlHot", Texture = "KespeLambHot", Kg = 0.449f, Thirst = 21f, Warm = 1.4f, Shape = "brick", Brand = "KespeKhan", Kcal = 410f, Ru = "Лапша «Кеспе-хан Баранина»", En = "Kespe Khan Lamb noodles", RuF = "бульон на баранине с зеленью", EnF = "lamb broth with herbs", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#b8823a" },
        new Def { Id = "KespeKazy", Kind = Kind.Noodle, RuM = "Со вкусом конской колбасы казы. На Великом Медведе коней нет, так что только так.", EnM = "With the taste of kazy horse sausage. No horses on Great Bear, so this is your only way.", Mesh = "brick1", Texture = "KespeKazy", Kg = 0.086f, Water = 0.4f, Shape = "brick", Brand = "KespeKhan", Kcal = 370f, Ru = "Лапша «Кеспе-хан Казы»", En = "Kespe Khan Kazy noodles", RuF = "со вкусом конской колбасы казы. На Великом Медведе коней нет, так что только так", EnF = "with the taste of kazy horse sausage. No horses on Great Bear, so this is your only way", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#a8603a" },
        new Def { Id = "KespeKazyHot", Kind = Kind.Brewed, RuM = "Бульон с духом конской колбасы. Кочевники с такой едой проходили полконтинента. Вам надо всего лишь до соседней долины.", EnM = "A broth with the spirit of horse sausage. Nomads crossed half a continent on food like this. You only need to reach the next valley.", Raw = "KespeKazy", Mesh = "BowlHot", Texture = "KespeKazyHot", Kg = 0.446f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "KespeKhan", Kcal = 370f, Ru = "Лапша «Кеспе-хан Казы»", En = "Kespe Khan Kazy noodles", RuF = "со вкусом конской колбасы казы. На Великом Медведе коней нет, так что только так", EnF = "with the taste of kazy horse sausage. No horses on Great Bear, so this is your only way", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#a8603a" },
        new Def { Id = "KespeCup", Kind = Kind.Noodle, RuM = "Домашняя лапша в большом стакане. Дом в стакане: удобно, когда своего дома у вас сейчас нет.", EnM = "Home-style noodles in a big cup. A home in a cup: handy when you have no home of your own right now.", Mesh = "bigcup", Texture = "KespeCup", Kg = 0.096f, Water = 0.5f, Shape = "bigcup", Brand = "KespeKhan", Kcal = 470f, Ru = "Лапша «Кеспе-хан Говядина» в большом стакане", En = "Kespe Khan Beef big cup", RuF = "домашняя лапша в говяжьем бульоне", EnF = "home-style noodles in beef broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "KespeCupHot", Kind = Kind.Brewed, RuM = "Говяжий бульон с широкой лапшой. Стакан большой, как пиала для дорогого гостя. Гость сегодня вы, хозяин тоже вы.", EnM = "Beef broth with wide noodles. The cup is as big as a bowl for an honoured guest. Today the guest is you, and so is the host.", Raw = "KespeCup", Mesh = "bigcupHot", Texture = "KespeCup", Kg = 0.546f, Thirst = 24f, Warm = 1.0f, Shape = "bigcup", Brand = "KespeKhan", Kcal = 470f, Ru = "Лапша «Кеспе-хан Говядина» в большом стакане", En = "Kespe Khan Beef big cup", RuF = "домашняя лапша в говяжьем бульоне", EnF = "home-style noodles in beef broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
        new Def { Id = "LagmanBeef", Kind = Kind.Noodle, RuM = "Узбекский лагман. Настоящий тянут руками и бьют об стол. Этот не били, он и так всё понял.", EnM = "Uzbek lagman. The real one is pulled by hand and slapped on the table. This one was not slapped, it got the idea anyway.", Mesh = "big0", Texture = "LagmanBeef", Kg = 0.136f, Water = 0.55f, Shape = "big", Brand = "Lagman", Kcal = 550f, Ru = "Лапша «Лагман-экспресс»", En = "Lagman Express noodles", RuF = "узбекский лагман: тянутая лапша в густой подливе с говядиной и перцем", EnF = "Uzbek lagman: pulled noodles in a thick gravy with beef and peppers", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c8502a" },
        new Def { Id = "LagmanBeefHot", Kind = Kind.Brewed, RuM = "Густая подлива с говядиной и перцем на длинной лапше. Не суп и не второе, а всё сразу. На острове так и надо.", EnM = "A thick gravy of beef and pepper on long noodles. Neither soup nor a main course but both at once. Just right for the island.", Raw = "LagmanBeef", Mesh = "BowlHot", Texture = "LagmanBeefHot", Kg = 0.631f, Thirst = 21f, Warm = 1.4f, Shape = "big", Brand = "Lagman", Kcal = 550f, Ru = "Лапша «Лагман-экспресс»", En = "Lagman Express noodles", RuF = "узбекский лагман: тянутая лапша в густой подливе с говядиной и перцем", EnF = "Uzbek lagman: pulled noodles in a thick gravy with beef and peppers", Spicy = 1, Dry = false, Fx = "brothreserve appetite", Broth = "#c8502a" },
        new Def { Id = "LagmanKovurma", Kind = Kind.Noodle, RuM = "Жареный лагман, без бульона. Казан заменит котелок, а чайхану заменит что угодно с крышей.", EnM = "Fried lagman, no broth. The pot stands in for a cauldron, and anything with a roof for a teahouse.", Mesh = "big1", Texture = "LagmanKovurma", Kg = 0.137f, Water = 0.55f, Shape = "big", Brand = "Lagman", Kcal = 570f, Ru = "Лапша «Лагман-экспресс Ковурма»", En = "Lagman Express Kovurma noodles", RuF = "жареный лагман, без бульона", EnF = "fried lagman, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#a85a2a" },
        new Def { Id = "LagmanKovurmaHot", Kind = Kind.Brewed, RuM = "Лапша в томатной зажарке с перцем. Пахнет базаром, дымом и югом. Юг отсюда в любую сторону, кроме одной.", EnM = "Noodles in a fried tomato and pepper sauce. It smells of bazaar, smoke and the south. From here the south is in every direction but one.", Raw = "LagmanKovurma", Mesh = "PlateHot", Texture = "LagmanKovurmaHot", Kg = 0.275f, Thirst = -8f, Warm = 1.05f, Shape = "big", Brand = "Lagman", Kcal = 570f, Ru = "Лапша «Лагман-экспресс Ковурма»", En = "Lagman Express Kovurma noodles", RuF = "жареный лагман, без бульона", EnF = "fried lagman, no broth", Spicy = 1, Dry = true, Fx = "", Broth = "#a85a2a" },
        new Def { Id = "AminaRosol", Kind = Kind.Noodle, RuM = "Польский куриный бульон. В Польше росул варят по воскресеньям и лечат им простуду, тоску и понедельник.", EnM = "Polish chicken broth. In Poland rosol is made on Sundays and cures a cold, the blues and Monday.", Mesh = "mini1", Texture = "AminaRosol", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Amina", Kcal = 270f, Ru = "Лапша «Амина Росул»", En = "Amina Rosol noodles", RuF = "польский куриный бульон с вермишелью", EnF = "Polish chicken broth with vermicelli", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AminaRosolHot", Kind = Kind.Brewed, RuM = "Золотой бульон с тонкой вермишелью. Не хватает только морковки и бабушки, которая говорит «ешь, остынет».", EnM = "A golden broth with fine vermicelli. All it lacks is a carrot and a granny saying \"eat, it will get cold\".", Raw = "AminaRosol", Mesh = "BowlHot", Texture = "AminaRosolHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Amina", Kcal = 270f, Ru = "Лапша «Амина Росул»", En = "Amina Rosol noodles", RuF = "польский куриный бульон с вермишелью", EnF = "Polish chicken broth with vermicelli", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
        new Def { Id = "AminaBarszcz", Kind = Kind.Noodle, RuM = "Красный борщ с лапшой. Да, борщ быстрого приготовления существует.", EnM = "Red borscht with noodles. Yes, instant borscht exists.", Mesh = "mini1", Texture = "AminaBarszcz", Kg = 0.063f, Water = 0.35f, Shape = "mini", Brand = "Amina", Kcal = 280f, Ru = "Лапша «Амина Барщ»", En = "Amina Barszcz noodles", RuF = "красный борщ с лапшой. Да, борщ быстрого приготовления существует", EnF = "red borscht with noodles. Yes, instant borscht exists", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#a8183a" },
        new Def { Id = "AminaBarszczHot", Kind = Kind.Brewed, RuM = "Красный и кисловатый, со свёклой. Борщ из пакетика на канадском острове. Бабушки двух стран хватаются за сердце.", EnM = "Red and tangy, with beetroot. Borscht from a sachet on a Canadian island. The grannies of two countries clutch their hearts.", Raw = "AminaBarszcz", Mesh = "BowlHot", Texture = "AminaBarszczHot", Kg = 0.378f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Amina", Kcal = 280f, Ru = "Лапша «Амина Барщ»", En = "Amina Barszcz noodles", RuF = "красный борщ с лапшой. Да, борщ быстрого приготовления существует", EnF = "red borscht with noodles. Yes, instant borscht exists", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#a8183a" },
        new Def { Id = "AminaZurek", Kind = Kind.Noodle, RuM = "Журек: кислый суп на ржаной закваске. Звучит как ошибка повара, а это национальная гордость.", EnM = "Zurek: a sour soup on fermented rye. Sounds like a cook's mistake, yet it is a national pride.", Mesh = "mini0", Texture = "AminaZurek", Kg = 0.06f, Water = 0.35f, Shape = "mini", Brand = "Amina", Kcal = 260f, Ru = "Лапша «Амина Журек»", En = "Amina Zurek noodles", RuF = "кислый ржаной суп с колбасой", EnF = "sour rye soup with sausage", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0d2a8" },
