        new Def { Id = "AminaPomidor", Kind = Kind.Noodle, RuM = "Томатный суп. Тот, что варят из вчерашнего бульона. Вчерашнего у вас нет, поэтому сразу из пачки.", EnM = "Tomato soup. The kind made from yesterday's broth. You have no yesterday's, so straight from the pack.", Mesh = "mini1", Texture = "AminaPomidor", Kg = 0.058f, Water = 0.35f, Shape = "mini", Brand = "Amina", Kcal = 300f, Ru = "Лапша «Амина Помидорова»", En = "Amina Pomidorowa noodles", RuF = "томатный суп", EnF = "tomato soup", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d2452a" },
        new Def { Id = "AminaPomidorHot", Kind = Kind.Brewed, RuM = "Оранжево-красный суп с лапшой. Сладковатый, детский, из школьной столовой. Единственная столовая в радиусе острова.", EnM = "An orange-red soup with noodles. Sweetish, childish, straight from the school canteen. The only canteen within an island's radius.", Raw = "AminaPomidor", Mesh = "BowlHot", Texture = "AminaPomidorHot", Kg = 0.373f, Thirst = 24f, Warm = 1.0f, Shape = "mini", Brand = "Amina", Kcal = 300f, Ru = "Лапша «Амина Помидорова»", En = "Amina Pomidorowa noodles", RuF = "томатный суп", EnF = "tomato soup", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d2452a" },
        new Def { Id = "PottChicken", Kind = Kind.Noodle, RuM = "Главная еда британского студента. Готовить не умеешь, чайник есть.", EnM = "The staple of the British student. Cannot cook, owns a kettle.", Mesh = "tallcup", Texture = "PottChicken", Kg = 0.075f, Water = 0.35f, Shape = "tallcup", Brand = "Pott", Kcal = 330f, Ru = "Лапша «Потт Нудл Курица с грибами» в стакане", En = "Pott Noodle Chicken & Mushroom cup", RuF = "главная еда британского студента. Готовить не умеешь, чайник есть", EnF = "the staple of the British student. Cannot cook, owns a kettle", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0c890" },
        new Def { Id = "PottChickenHot", Kind = Kind.Brewed, RuM = "Густой бульон с курицей и грибами, лапша короткая. Британцы едят это вилкой прямо из стакана и считают ужином. На острове вы с ними согласны.", EnM = "A thick chicken and mushroom broth with short noodles. The British eat it with a fork straight from the pot and call it dinner. On the island you agree.", Raw = "PottChicken", Mesh = "tallcupHot", Texture = "PottChicken", Kg = 0.39f, Thirst = 24f, Warm = 1.0f, Shape = "tallcup", Brand = "Pott", Kcal = 330f, Ru = "Лапша «Потт Нудл Курица с грибами» в стакане", En = "Pott Noodle Chicken & Mushroom cup", RuF = "главная еда британского студента. Готовить не умеешь, чайник есть", EnF = "the staple of the British student. Cannot cook, owns a kettle", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e0c890" },
        new Def { Id = "PottBeef", Kind = Kind.Noodle, RuM = "Говядина с томатом. В комплекте пакетик соуса, который британцы торжественно выдавливают сверху.", EnM = "Beef and tomato. A sauce sachet is included, which the British solemnly squeeze on top.", Mesh = "tallcup", Texture = "PottBeef", Kg = 0.079f, Water = 0.35f, Shape = "tallcup", Brand = "Pott", Kcal = 360f, Ru = "Лапша «Потт Нудл Говядина с томатом» в стакане", En = "Pott Noodle Beef & Tomato cup", RuF = "говядина с томатом", EnF = "beef and tomato", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d2452a" },
        new Def { Id = "PottBeefHot", Kind = Kind.Brewed, RuM = "Густая красноватая подлива и лапша. Не изысканно, зато честно, как дождь в Манчестере. Дождю вы бы сейчас обрадовались.", EnM = "A thick reddish gravy and noodles. Not refined but honest, like rain in Manchester. You would welcome rain right now.", Raw = "PottBeef", Mesh = "tallcupHot", Texture = "PottBeef", Kg = 0.394f, Thirst = 24f, Warm = 1.0f, Shape = "tallcup", Brand = "Pott", Kcal = 360f, Ru = "Лапша «Потт Нудл Говядина с томатом» в стакане", En = "Pott Noodle Beef & Tomato cup", RuF = "говядина с томатом", EnF = "beef and tomato", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#d2452a" },
        new Def { Id = "PottCurry", Kind = Kind.Noodle, RuM = "Карри из закусочной на углу. Угол остался в Англии, запах доехал целиком.", EnM = "Curry from the chip shop on the corner. The corner stayed in England, the smell arrived whole.", Mesh = "tallcup", Texture = "PottCurry", Kg = 0.072f, Water = 0.35f, Shape = "tallcup", Brand = "Pott", Kcal = 360f, Ru = "Лапша «Потт Нудл Карри» в стакане", En = "Pott Noodle Original Curry cup", RuF = "карри из закусочной", EnF = "chip shop curry", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "PottCurryHot", Kind = Kind.Brewed, RuM = "Жёлтый соус, сладковатый и мягкий. Так пахнет пятничный вечер в городе, где горят фонари и ходят автобусы.", EnM = "A yellow sauce, sweetish and mild. This is how a Friday night smells in a town with street lights and buses.", Raw = "PottCurry", Mesh = "tallcupHot", Texture = "PottCurry", Kg = 0.387f, Thirst = 21f, Warm = 1.4f, Shape = "tallcup", Brand = "Pott", Kcal = 360f, Ru = "Лапша «Потт Нудл Карри» в стакане", En = "Pott Noodle Original Curry cup", RuF = "карри из закусочной", EnF = "chip shop curry", Spicy = 1, Dry = false, Fx = "brothreserve", Broth = "#d39a1e" },
        new Def { Id = "PottBadBoy", Kind = Kind.Noodle, RuM = "Самый острый в линейке, по британским меркам.", EnM = "The hottest of the lot, by British standards.", Mesh = "tallcup", Texture = "PottBadBoy", Kg = 0.079f, Water = 0.35f, Shape = "tallcup", Brand = "Pott", Kcal = 320f, Ru = "Лапша «Потт Нудл Бомбей Бэд Бой» в стакане", En = "Pott Noodle Bombay Bad Boy cup", RuF = "самый острый в линейке, по британским меркам", EnF = "the hottest of the lot, by British standards", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#b8401c" },
        new Def { Id = "PottBadBoyHot", Kind = Kind.Brewed, RuM = "«Плохой парень из Бомбея» покраснел и дымится. Для Лондона это дерзко. Корейские пачки на соседней полке тихо смеются.", EnM = "The \"Bombay Bad Boy\" has gone red and is steaming. For London this is daring. The Korean packs on the next shelf chuckle quietly.", Raw = "PottBadBoy", Mesh = "tallcupHot", Texture = "PottBadBoy", Kg = 0.394f, Thirst = 15f, Warm = 2.2f, Shape = "tallcup", Brand = "Pott", Kcal = 320f, Ru = "Лапша «Потт Нудл Бомбей Бэд Бой» в стакане", En = "Pott Noodle Bombay Bad Boy cup", RuF = "самый острый в линейке, по британским меркам", EnF = "the hottest of the lot, by British standards", Spicy = 3, Dry = false, Fx = "heartburn", Broth = "#b8401c" },
