        new Def { Id = "TerrinaRahmHot", Kind = Kind.Brewed, RuM = "Белый сливочный соус с зеленью. Аккуратно, сытно, по расписанию. Единственное на острове, что случилось вовремя.", EnM = "A white cream sauce with herbs. Neat, filling, on schedule. The only thing on the island that happened on time.", Raw = "TerrinaRahm", Mesh = "cupHot", Texture = "TerrinaRahm", Kg = 0.146f, Thirst = -6f, Warm = 0.75f, Shape = "cup", Brand = "Terrina", Kcal = 310f, Ru = "Лапша «Фюнф Минутен Лапша в сливочном соусе» в стакане", En = "Funf Minuten Nudeln in Rahmsauce cup", RuF = "немецкая лапша в сливочном соусе с зеленью, без бульона", EnF = "German noodles in a cream and herb sauce, no broth", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#f1dcae" },
