        new Def { Id = "TerrinaBologneseHot", Kind = Kind.Brewed, RuM = "Красный мясной соус на коротких макаронах. Итальянец бы заплакал, а вы доедите и вылижете стакан.", EnM = "Red meat sauce on short pasta. An Italian would weep, and you will finish it and lick the cup clean.", Raw = "TerrinaBolognese", Mesh = "cupHot", Texture = "TerrinaBolognese", Kg = 0.143f, Thirst = -6f, Warm = 0.75f, Shape = "cup", Brand = "Terrina", Kcal = 350f, Ru = "Лапша «Фюнф Минутен Болоньезе» в стакане", En = "Funf Minuten Bolognese cup", RuF = "спагетти болоньезе из стакана, без бульона. Итальянцам не показывать", EnF = "spaghetti bolognese from a cup, no broth. Do not show it to Italians", Spicy = 0, Dry = true, Fx = "appetite", Broth = "#d2452a" },
