        new Def { Id = "TerrinaHuhnHot", Kind = Kind.Brewed, RuM = "Светлый суп с лапшой и морковными точками. Порядок в стакане. Хоть где-то на этом острове порядок.", EnM = "A light soup with noodles and specks of carrot. Order in a cup. At least somewhere on this island there is order.", Raw = "TerrinaHuhn", Mesh = "cupHot", Texture = "TerrinaHuhn", Kg = 0.342f, Thirst = 24f, Warm = 1.0f, Shape = "cup", Brand = "Terrina", Kcal = 330f, Ru = "Лапша «Фюнф Минутен Куриный суп» в стакане", En = "Funf Minuten Huhner-Nudeltopf cup", RuF = "куриный суп с лапшой", EnF = "chicken noodle soup", Spicy = 0, Dry = false, Fx = "brothreserve", Broth = "#e8b04a" },
