        new Def { Id = "AjiMenCarneHot", Kind = Kind.Brewed, RuM = "Тёмный бульон, кудрявая лапша. Ламы в горах жуют траву, вы жуёте лапшу. У каждого свои Анды.", EnM = "Dark broth, curly noodles. Llamas in the mountains chew grass, you chew noodles. Everyone has their own Andes.", Raw = "AjiMenCarne", Mesh = "BowlHot", Texture = "AjiMenCarneHot", Kg = 0.443f, Thirst = 24f, Warm = 1.0f, Shape = "brick", Brand = "AjiMen", Kcal = 390f, Ru = "Лапша «Ахи-но-мэн Говядина»", En = "Aji-no-men Carne noodles", RuF = "говяжий бульон", EnF = "beef broth", Spicy = 0, Dry = false, Fx = "brothreserve appetite", Broth = "#b9692d" },
